    /// Classifies the structure stored at a direct `SS8-16` route target offset by reading only the persisted magic value.<br/>
    /// Offset zero is treated as `None`; unknown magic values are invalid because route targets must point to known storage structures.<br/>
    /// This method intentionally exposes the extra classification read so walker costs stay measurable while direct fast paths remain unchanged.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `SS8-16` shelf magic value.</exception>
    internal Scalar8Scalar16RouteTargetKind ClassifyScalar8Scalar16RouteTarget(long targetOffset)
    {
        if (targetOffset == 0)
        {
            return Scalar8Scalar16RouteTargetKind.None;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            return Scalar8Scalar16RouteTargetKind.Router;
        }

        if (magic == Scalar8Scalar16Layout.Magic)
        {
            return Scalar8Scalar16RouteTargetKind.Shelf;
        }

        throw new InvalidDataException($"SS8-16 route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS8-16` key until the route target is classified as a shelf.<br/>
    /// The current implementation reads full router pages plus a 4-byte target classifier at each hop, matching the first `SS8-8` route walker shape.<br/>
    /// This walker is intentionally internal and conservative while route-target typing and deeper split behavior remain shape-local.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKey">The encoded key whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified shelf target reached by the route walk.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Scalar8Scalar16RouteTarget WalkScalar8Scalar16RouteTarget(
        long rootRouterOffset,
        ulong encodedKey,
        int maxRouterHops)
    {
        return WalkScalar8Scalar16RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops).Target;
    }

    /// <summary>
    /// Walks direct one-byte routers for an encoded `SS8-16` key and returns both the classified target and the parent router route that selected it.<br/>
    /// Parent-route split logic uses this to refine the exact router page that currently fans several prefixes into the same full shelf.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="encodedKey">The encoded key whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified route target and parent router route metadata.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Scalar8Scalar16RoutePathTarget WalkScalar8Scalar16RoutePathTarget(
        long rootRouterOffset,
        ulong encodedKey,
        int maxRouterHops)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        long routerOffset = rootRouterOffset;
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            byte[] routerBytes = new byte[RouterLayout.Size];
            kernel.Read(routerOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed page is not a valid router.");
            }

            byte prefixByte = GetScalar8Scalar8Prefix(encodedKey, reader.KeyDepth);
            long targetOffset = reader.FindTarget(prefixByte);
            if (targetOffset == 0)
            {
                throw new InvalidDataException("The routed SS8-16 target is unset.");
            }

            Scalar8Scalar16RouteTargetKind kind = ClassifyScalar8Scalar16RouteTarget(targetOffset);
            if (kind == Scalar8Scalar16RouteTargetKind.Shelf)
            {
                return new Scalar8Scalar16RoutePathTarget(
                    new Scalar8Scalar16RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte);
            }

            if (kind == Scalar8Scalar16RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed SS8-16 target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed SS8-16 target walk exceeded the configured maximum router hop count.");
    }

    /// <summary>
    /// Classifies the structure stored at a direct `SS16-16` route target offset by reading only the persisted magic value.<br/>
    /// Offset zero is treated as `None`; unknown magic values are invalid because route targets must point to known storage structures.<br/>
    /// This method intentionally exposes the extra classification read so walker costs stay measurable while direct fast paths remain unchanged.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `SS16-16` shelf magic value.</exception>
    internal Scalar16Scalar16RouteTargetKind ClassifyScalar16Scalar16RouteTarget(long targetOffset)
