    /// <summary>
    /// Stores one clean `SS8-8` shelf image for reuse by a later batch in the same session.<br/>
    /// The image must represent bytes already published through a successful commit; the cache is a performance hint and never the durable source of truth.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset used as the cache key.</param>
    /// <param name="profile">The `SS8-8` profile that determines the shelf extent size.</param>
    /// <param name="shelfBytes">The clean shelf image to keep for a later batch.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="shelfBytes"/> does not match the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="shelfBytes"/> is not a valid `SS8-8` shelf image.</exception>
    internal void StoreScalar8Scalar8CleanShelfBytesForBatch(long shelfOffset, Scalar8Scalar8Profile profile, byte[] shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The session-local SS8-8 clean shelf cache image must match the profiled shelf extent size.", nameof(shelfBytes));
        }

        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The session-local SS8-8 clean shelf cache attempted to store invalid shelf bytes.");
        }

        scalar8Scalar8CleanShelfCache[shelfOffset] = shelfBytes;
    }

    /// <summary>
    /// Stages one full `SS8-8` shelf rewrite for a batch-local mutation cache.<br/>
    /// In an active durability batch this increments the deferred commit-request count and leaves publication to the outer batch commit.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent to rewrite.</param>
    /// <param name="profile">The `SS8-8` profile that determines the expected shelf extent size.</param>
    /// <param name="shelfBytes">The final shelf bytes to stage.</param>
    /// <returns>Commit telemetry when no durability batch is active; otherwise default telemetry with the request deferred.</returns>
    /// <exception cref="ArgumentException">Thrown when the shelf byte span does not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="shelfBytes"/> does not contain a valid `SS8-8` shelf.</exception>
    internal DataKernelCommitTelemetry StageScalar8Scalar8ShelfRewriteForBatch(
        long shelfOffset,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<byte> shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The batch-local SS8-8 shelf rewrite bytes must match the profiled shelf extent size.", nameof(shelfBytes));
        }

        Scalar8Scalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The batch-local SS8-8 shelf cache attempted to stage invalid shelf bytes.");
        }

        if (durabilityBatchActive)
        {
            scalar8Scalar8MutableBatchShelfBytes[shelfOffset] = shelfBytes.ToArray();
            return CommitWithoutInvalidatingRouterReadCache();
        }

        RawDataReservation rewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        shelfBytes.CopyTo(rewrite.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }

    /// <summary>
    /// Stages one partial `SS8-8` shelf rewrite for a batch-local mutation cache.<br/>
    /// The caller owns full-shelf validation and only passes byte ranges whose contents were changed by cached shelf mutation.<br/>
    /// In an active durability batch this increments the deferred commit-request count and leaves publication to the outer batch commit.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent that owns the slice.</param>
    /// <param name="profile">The `SS8-8` profile that determines valid shelf bounds.</param>
    /// <param name="sliceOffset">The byte offset inside the shelf extent where the slice begins.</param>
    /// <param name="sliceBytes">The changed shelf bytes to stage.</param>
    /// <returns>Commit telemetry when no durability batch is active; otherwise default telemetry with the request deferred.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slice is outside the profiled shelf extent.</exception>
    internal DataKernelCommitTelemetry StageScalar8Scalar8ShelfSliceRewriteForBatch(
        long shelfOffset,
        Scalar8Scalar8Profile profile,
        int sliceOffset,
        ReadOnlySpan<byte> sliceBytes)
    {
        if (sliceOffset < 0 || sliceOffset > profile.ShelfExtentSize || sliceBytes.Length > profile.ShelfExtentSize - sliceOffset)
        {
            throw new ArgumentOutOfRangeException(nameof(sliceOffset), sliceOffset, "The batch-local SS8-8 shelf slice must fit inside the profiled shelf extent.");
        }

        if (sliceBytes.Length == 0)
        {
            return default;
        }

        if (durabilityBatchActive)
        {
            if (!scalar8Scalar8MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
            {
                dirtyShelfBytes = new byte[profile.ShelfExtentSize];
                kernel.Read(shelfOffset, dirtyShelfBytes);
                scalar8Scalar8MutableBatchShelfBytes[shelfOffset] = dirtyShelfBytes;
            }

            sliceBytes.CopyTo(dirtyShelfBytes.AsSpan(sliceOffset, sliceBytes.Length));
            return CommitWithoutInvalidatingRouterReadCache();
        }

        RawDataReservation rewrite = kernel.ReserveAt(shelfOffset + sliceOffset, sliceBytes.Length);
        sliceBytes.CopyTo(rewrite.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }

