    /// The image must represent bytes already published through a successful commit; the cache is a performance hint and never the durable source of truth.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset used as the cache key.</param>
    /// <param name="profile">The `SS8-16` profile that determines the shelf extent size.</param>
    /// <param name="shelfBytes">The clean shelf image to keep for a later batch.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="shelfBytes"/> does not match the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="shelfBytes"/> is not a valid `SS8-16` shelf image.</exception>
    internal void StoreScalar8Scalar16CleanShelfBytesForBatch(long shelfOffset, Scalar8Scalar16Profile profile, byte[] shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The session-local SS8-16 clean shelf cache image must match the profiled shelf extent size.", nameof(shelfBytes));
        }

