    /// <summary>
    /// Inserts one tuple into a routed `SS8-8` shelf without performing split handling.<br/>
    /// The method routes through the root router, reads the target shelf, stages a same-offset shelf rewrite, and commits only when the shelf insert mutates bytes.<br/>
    /// If the tuple is already present, the method returns without committing because the physical mutation is a no-op.<br/>
    /// If the shelf is full or a unique-key conflict occurs, the method returns that insert result without committing so the caller can choose the next structural path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte used to route to the shelf.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The routed shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when the route is unset or points to an invalid `SS8-8` shelf.</exception>
    internal (long ShelfOffset, Scalar8Scalar8InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertRoutedScalar8Scalar8NoSplit(
        long rootRouterOffset,
        byte prefixByte,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        long shelfOffset = FindRouterTarget(rootRouterOffset, prefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-8 shelf route is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The routed SS8-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar8InsertResult result = shelf.Insert(encodedKey, encodedIdentity, allowDuplicateKeys);
        if (result != Scalar8Scalar8InsertResult.Inserted)
        {
            return (shelfOffset, result, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (shelfOffset, result, telemetry);
    }

