    /// <summary>
    /// Inserts one tuple into a routed `SS8-16` shelf without performing split handling.<br/>
    /// The method routes through the root router, reads the target widened-identity shelf, stages a same-offset shelf rewrite, and commits only when the shelf insert mutates bytes.<br/>
    /// If the tuple is already present, the method returns without committing because the physical mutation is a no-op.<br/>
    /// If the shelf is full or a unique-key conflict occurs, the method returns that insert result without committing so the caller can choose the next structural path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte used to route to the shelf.</param>
    /// <param name="profile">The `SS8-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded sortable key to insert.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The routed shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when the route is unset or points to an invalid `SS8-16` shelf.</exception>
    internal (long ShelfOffset, Scalar8Scalar16InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertRoutedScalar8Scalar16NoSplit(
        long rootRouterOffset,
        byte prefixByte,
        Scalar8Scalar16Profile profile,
        ulong encodedKey,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys)
    {
        long shelfOffset = FindRouterTarget(rootRouterOffset, prefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-16 shelf route is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Scalar8Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The routed SS8-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar16 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar16InsertResult result = shelf.Insert(encodedKey, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys);
        if (result != Scalar8Scalar16InsertResult.Inserted)
        {
            return (shelfOffset, result, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (shelfOffset, result, telemetry);
    }

