    /// <summary>
    /// Splits a routed full `SS8-16` shelf by root prefix.<br/>
    /// This first widened-identity split path only covers split boundaries that are representable by the owning root router's current prefix byte.<br/>
    /// The existing shelf is read, the incoming tuple is merged into sorted order, tuples whose first key byte is below <paramref name="rightPrefixByte"/> remain left, and all others move right.<br/>
    /// Same-prefix splits are intentionally excluded because they require a later `SS8-16` shelf-to-router transform path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="leftPrefixByte">The prefix byte that continues to route to the rewritten left shelf.</param>
    /// <param name="rightPrefixByte">The prefix byte that will route to the appended right shelf after the split.</param>
    /// <param name="profile">The `SS8-16` shelf profile used for both split shelves.</param>
    /// <param name="encodedKey">The encoded key to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <returns>The left shelf offset, right shelf offset, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar8Scalar16ByRootPrefix(
            long rootRouterOffset,
            byte leftPrefixByte,
            byte rightPrefixByte,
            Scalar8Scalar16Profile profile,
            ulong encodedKey,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow)
    {
        long leftShelfOffset = FindRouterTarget(rootRouterOffset, leftPrefixByte);
        if (leftShelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-16 left shelf route is unset.");
        }

        long currentRightTarget = FindRouterTarget(rootRouterOffset, rightPrefixByte);
        if (currentRightTarget != leftShelfOffset)
        {
            throw new InvalidDataException("The first SS8-16 split path expects both root prefixes to currently route to the same full shelf.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(leftShelfOffset, existingShelfBytes);
        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingRouterReader = new(existingRouter);
        if (!existingRouterReader.IsValid || !existingRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        Scalar8Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The first SS8-16 split path expects a valid full shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keys = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey = existingShelf.ReadKeyAt(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareScalar8Scalar16Tuple(currentKey, currentIdentityHigh, currentIdentityLow, encodedKey, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                keys[targetIndex] = encodedKey;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKey == encodedKey && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                return (leftShelfOffset, 0, existingCount, 0, Scalar8Scalar16InsertResult.AlreadyPresent, default);
            }

            keys[targetIndex] = currentKey;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            keys[targetIndex] = encodedKey;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar16 leftShelf = new(leftShelfBytes, profile);
        Scalar8Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = GetScalar8Scalar8RootPrefix(keys[i]) >= rightPrefixByte;
            Scalar8Scalar16InsertResult result = goesRight
                ? rightShelf.Insert(keys[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keys[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split SS8-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The first SS8-16 split path requires both split shelves to receive at least one item.");
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(leftShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);
        RawDataReservation routerRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerRewrite.Span);
        RouterWriter writer = new(routerRewrite.Span);
        writer.WriteRoute(rightPrefixByte, rightPrefixByte, rightPrefixByte, rightAppend.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (leftShelfOffset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Scalar8Scalar16InsertResult.Inserted, telemetry);
    }

    /// <summary>
    /// Splits a full routed `SS8-16` shelf by transforming the shelf's existing offset into a child router and appending two replacement shelves.<br/>
    /// This path covers same-root-prefix widened-identity splits where the root route must stay stable and the next key byte decides left/right ownership.<br/>
    /// The parent root router is not dirtied; the former shelf location is structurally reused as a direct-index one-byte child router at key depth `1`.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root prefix byte that currently routes to the full shelf and will continue routing to the transformed child router.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `SS8-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded key to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar8Scalar16ByShelfTransform(
            long rootRouterOffset,
            byte rootPrefixByte,
            byte rightPrefixByte,
            Scalar8Scalar16Profile profile,
            ulong encodedKey,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow)
    {
        byte[] rootRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, rootRouterBytes);
        RouterReader rootRouterReader = new(rootRouterBytes);
        if (!rootRouterReader.IsValid || !rootRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        ushort allocationClassId = rootRouterReader.AllocationClassId;
        long childRouterOffset = rootRouterReader.FindTarget(rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-16 transform source route is unset.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(childRouterOffset, existingShelfBytes);
        return SplitRoutedScalar8Scalar16ByShelfTransform(
            childRouterOffset,
            existingShelfBytes,
            rightPrefixByte,
            profile,
            encodedKey,
            encodedIdentityHigh,
            encodedIdentityLow,
            allocationClassId,
            childRouterKeyDepth: 1);
    }

    /// <summary>
    /// Splits an already-routed full `SS8-16` shelf by transforming its offset into a child router using caller-provided shelf bytes.<br/>
    /// This reuse path avoids rereading the root router and full shelf when an outer insert decision has already loaded them.<br/>
    /// </summary>
    /// <param name="childRouterOffset">The old shelf offset that will be rewritten as the child router.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `SS8-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded key to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.</param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when supplied shelf bytes do not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when shelf validity or split partitioning is invalid.</exception>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar8Scalar16ByShelfTransform(
            long childRouterOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
            Scalar8Scalar16Profile profile,
            ulong encodedKey,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            ushort allocationClassId,
            ushort childRouterKeyDepth)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled SS8-16 shelf extent size.", nameof(existingShelfBytes));
        }

        Scalar8Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full SS8-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keys = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey = existingShelf.ReadKeyAt(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareScalar8Scalar16Tuple(currentKey, currentIdentityHigh, currentIdentityLow, encodedKey, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                keys[targetIndex] = encodedKey;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKey == encodedKey && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                return (childRouterOffset, 0, 0, existingCount, 0, Scalar8Scalar16InsertResult.AlreadyPresent, default);
            }

            keys[targetIndex] = currentKey;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            keys[targetIndex] = encodedKey;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseScalar8Scalar8TransformSplitPlan(keys, childRouterKeyDepth, rightPrefixByte);
        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar16 leftShelf = new(leftShelfBytes, profile);
        Scalar8Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = GetScalar8Scalar8Prefix(keys[i], splitKeyDepth) >= selectedRightPrefixByte;
            Scalar8Scalar16InsertResult result = goesRight
                ? rightShelf.Insert(keys[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keys[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split SS8-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
        long nextRouterOffset = 0;
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
            RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
            RouterWriter appendedWriter = new(appendedRouter.Span);
            appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
            nextRouterOffset = appendedRouter.Extent.Offset;
        }

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        childWriter.InitializeExpandedOneByte(
            childRouterKeyDepth,
            allocationClassId,
            CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        int routerArenaLength = Math.Min(profile.ShelfExtentSize, 64 * 1024);
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: routerArenaLength,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(routerArenaLength / RouterLayout.Size)),
            arenaFlags: 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, routerArenaLength);
        arena.MarkUsed(0);
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Scalar8Scalar16InsertResult.Inserted, telemetry);
    }

    /// <summary>
    /// Splits a routed full `SS16-8` shelf by root prefix.<br/>
    /// This first widened-key split path only covers split boundaries that are representable by the owning root router's current prefix byte.<br/>
    /// The existing shelf is read, the incoming tuple is merged into sorted order, tuples whose first widened-key byte is below <paramref name="rightPrefixByte"/> remain left, and all others move right.<br/>
    /// Same-prefix splits are intentionally excluded because they require a later `SS16-8` shelf-to-router transform path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="leftPrefixByte">The prefix byte that continues to route to the rewritten left shelf.</param>
    /// <param name="rightPrefixByte">The prefix byte that will route to the appended right shelf after the split.</param>
    /// <param name="profile">The `SS16-8` shelf profile used for both split shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity lane to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity lane to insert during the split.</param>
    /// <returns>The left shelf offset, right shelf offset, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar16Scalar8ByRootPrefix(
            long rootRouterOffset,
            byte leftPrefixByte,
            byte rightPrefixByte,
            Scalar16Scalar8Profile profile,
            ulong encodedKeyHigh,
            ulong encodedKeyLow,
            ulong encodedIdentity)
    {
        long leftShelfOffset = FindRouterTarget(rootRouterOffset, leftPrefixByte);
        if (leftShelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS16-8 left shelf route is unset.");
        }

        long currentRightTarget = FindRouterTarget(rootRouterOffset, rightPrefixByte);
        if (currentRightTarget != leftShelfOffset)
        {
            throw new InvalidDataException("The first SS16-8 split path expects both root prefixes to currently route to the same full shelf.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(leftShelfOffset, existingShelfBytes);
        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingRouterReader = new(existingRouter);
        if (!existingRouterReader.IsValid || !existingRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        Scalar16Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The first SS16-8 split path expects a valid full shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keyHighs = new ulong[existingCount + 1];
        ulong[] keyLows = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKeyHigh = existingShelf.ReadKeyHighAt(sourceIndex);
            ulong currentKeyLow = existingShelf.ReadKeyLowAt(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareScalar16Scalar8Tuple(currentKeyHigh, currentKeyLow, currentIdentity, encodedKeyHigh, encodedKeyLow, encodedIdentity) > 0)
            {
                keyHighs[targetIndex] = encodedKeyHigh;
                keyLows[targetIndex] = encodedKeyLow;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKeyHigh == encodedKeyHigh && currentKeyLow == encodedKeyLow && currentIdentity == encodedIdentity)
            {
                return (leftShelfOffset, 0, existingCount, 0, Scalar16Scalar8InsertResult.AlreadyPresent, default);
            }

            keyHighs[targetIndex] = currentKeyHigh;
            keyLows[targetIndex] = currentKeyLow;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            keyHighs[targetIndex] = encodedKeyHigh;
            keyLows[targetIndex] = encodedKeyLow;
            identities[targetIndex] = encodedIdentity;
        }

        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar8 leftShelf = new(leftShelfBytes, profile);
        Scalar16Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keyHighs.Length; i++)
        {
            bool goesRight = GetScalar16Scalar8RootPrefix(keyHighs[i]) >= rightPrefixByte;
            Scalar16Scalar8InsertResult result = goesRight
                ? rightShelf.Insert(keyHighs[i], keyLows[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keyHighs[i], keyLows[i], identities[i], allowDuplicateKeys: true);
            if (result != Scalar16Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split SS16-8 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The first SS16-8 split path requires both split shelves to receive at least one item.");
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(leftShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);
        RawDataReservation routerRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerRewrite.Span);
        RouterWriter writer = new(routerRewrite.Span);
        writer.WriteRoute(rightPrefixByte, rightPrefixByte, rightPrefixByte, rightAppend.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (leftShelfOffset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Scalar16Scalar8InsertResult.Inserted, telemetry);
    }

    /// <summary>
    /// Splits a routed full `FS32-8` shelf by root prefix.<br/>
    /// This first fixed-key split path only covers split boundaries that are representable by the owning root router's current prefix byte.<br/>
    /// The existing shelf is read, the incoming tuple is merged into sorted order, tuples whose first fixed-key byte is below <paramref name="rightPrefixByte"/> remain left, and all others move right.<br/>
    /// Same-prefix splits are intentionally excluded because they require a later `FS32-8` shelf-to-router transform path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="leftPrefixByte">The prefix byte that continues to route to the rewritten left shelf.</param>
    /// <param name="rightPrefixByte">The prefix byte that will route to the appended right shelf after the split.</param>
    /// <param name="profile">The `FS32-8` shelf profile used for both split shelves.</param>
    /// <param name="key0">The encoded key part 0 to insert during the split.</param>
    /// <param name="key1">The encoded key part 1 to insert during the split.</param>
    /// <param name="key2">The encoded key part 2 to insert during the split.</param>
    /// <param name="key3">The encoded key part 3 to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <returns>The left shelf offset, right shelf offset, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedFixed32Scalar8ByRootPrefix(
            long rootRouterOffset,
            byte leftPrefixByte,
            byte rightPrefixByte,
            Fixed32Scalar8Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity)
    {
        long leftShelfOffset = FindRouterTarget(rootRouterOffset, leftPrefixByte);
        if (leftShelfOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-8 left shelf route is unset.");
        }

        long currentRightTarget = FindRouterTarget(rootRouterOffset, rightPrefixByte);
        if (currentRightTarget != leftShelfOffset)
        {
            throw new InvalidDataException("The first FS32-8 split path expects both root prefixes to currently route to the same full shelf.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(leftShelfOffset, existingShelfBytes);
        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingRouterReader = new(existingRouter);
        if (!existingRouterReader.IsValid || !existingRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        Fixed32Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The first FS32-8 split path expects a valid full shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] key0s = new ulong[existingCount + 1];
        ulong[] key1s = new ulong[existingCount + 1];
        ulong[] key2s = new ulong[existingCount + 1];
        ulong[] key3s = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar8Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentity, key0, key1, key2, key3, encodedIdentity) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentity == encodedIdentity)
            {
                return (leftShelfOffset, 0, existingCount, 0, Fixed32Scalar8InsertResult.AlreadyPresent, default);
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identities[targetIndex] = encodedIdentity;
        }

        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar8 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = (byte)(key0s[i] >> 56) >= rightPrefixByte;
            Fixed32Scalar8InsertResult result = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split FS32-8 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The first FS32-8 split path requires both split shelves to receive at least one item.");
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(leftShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);
        RawDataReservation routerRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerRewrite.Span);
        RouterWriter writer = new(routerRewrite.Span);
        writer.WriteRoute(rightPrefixByte, rightPrefixByte, rightPrefixByte, rightAppend.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (leftShelfOffset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Fixed32Scalar8InsertResult.Inserted, telemetry);
    }

