    /// <summary>
    /// Splits an already-routed full `SS16-8` shelf by transforming its offset into a child router using caller-provided shelf bytes.<br/>
    /// This reuse path avoids rereading the root router and full shelf when an outer insert decision has already loaded them.<br/>
    /// </summary>
    /// <param name="childRouterOffset">The old shelf offset that will be rewritten as the child router.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `SS16-8` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.</param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when supplied shelf bytes do not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when shelf validity or split partitioning is invalid.</exception>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar16Scalar8ByShelfTransform(
            long childRouterOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
            Scalar16Scalar8Profile profile,
            ulong encodedKeyHigh,
            ulong encodedKeyLow,
            ulong encodedIdentity,
            ushort allocationClassId,
            ushort childRouterKeyDepth)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled SS16-8 shelf extent size.", nameof(existingShelfBytes));
        }

        Scalar16Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full SS16-8 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keyHighs = new ulong[existingCount + 1];
        ulong[] keyLows = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKeyHigh = existingShelf.ReadKeyHighAt(sourceIndex);
            ulong currentKeyLow = existingShelf.ReadKeyLowAt(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareScalar16Scalar8Tuple(currentKeyHigh, currentKeyLow, currentIdentity, encodedKeyHigh, encodedKeyLow, encodedIdentity) > 0)
            {
                keyHighs[targetIndex] = encodedKeyHigh;
                keyLows[targetIndex] = encodedKeyLow;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKeyHigh == encodedKeyHigh && currentKeyLow == encodedKeyLow && currentIdentity == encodedIdentity)
            {
                return (childRouterOffset, 0, 0, existingCount, 0, Scalar16Scalar8InsertResult.AlreadyPresent, default);
            }

            keyHighs[targetIndex] = currentKeyHigh;
            keyLows[targetIndex] = currentKeyLow;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            keyHighs[targetIndex] = encodedKeyHigh;
            keyLows[targetIndex] = encodedKeyLow;
            identities[targetIndex] = encodedIdentity;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseScalar16Scalar8TransformSplitPlan(keyHighs, keyLows, childRouterKeyDepth, rightPrefixByte);
        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar8 leftShelf = new(leftShelfBytes, profile);
        Scalar16Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keyHighs.Length; i++)
        {
            bool goesRight = GetScalar16Scalar8Prefix(keyHighs[i], keyLows[i], splitKeyDepth) >= selectedRightPrefixByte;
            Scalar16Scalar8InsertResult result = goesRight
                ? rightShelf.Insert(keyHighs[i], keyLows[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keyHighs[i], keyLows[i], identities[i], allowDuplicateKeys: true);
            if (result != Scalar16Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split SS16-8 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
        long nextRouterOffset = 0;
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
            RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
            RouterWriter appendedWriter = new(appendedRouter.Span);
            appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
            nextRouterOffset = appendedRouter.Extent.Offset;
        }

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        childWriter.InitializeExpandedOneByte(
            childRouterKeyDepth,
            allocationClassId,
            CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        int routerArenaLength = Math.Min(profile.ShelfExtentSize, 64 * 1024);
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: routerArenaLength,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(routerArenaLength / RouterLayout.Size)),
            arenaFlags: 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, routerArenaLength);
        arena.MarkUsed(0);
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Scalar16Scalar8InsertResult.Inserted, telemetry);
    }

