    /// <summary>
    /// Splits an already-routed full `SS16-16` shelf by transforming its offset into a child router using caller-provided shelf bytes.<br/>
    /// This reuse path avoids rereading the root router and full shelf when an outer insert decision has already loaded them.<br/>
    /// </summary>
    /// <param name="childRouterOffset">The old shelf offset that will be rewritten as the child router.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `SS16-16` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert during the split.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert during the split.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity half to insert during the split.</param>
    /// <param name="encodedIdentityLow">The encoded low identity half to insert during the split.</param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.</param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when supplied shelf bytes do not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when shelf validity or split partitioning is invalid.</exception>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar16Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar16Scalar16ByShelfTransform(
            long childRouterOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
            Scalar16Scalar16Profile profile,
            ulong encodedKeyHigh,
            ulong encodedKeyLow,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            ushort allocationClassId,
            ushort childRouterKeyDepth)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled SS16-16 shelf extent size.", nameof(existingShelfBytes));
        }

        Scalar16Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full SS16-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keyHighs = new ulong[existingCount + 1];
        ulong[] keyLows = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKeyHigh = existingShelf.ReadKeyHighAt(sourceIndex);
            ulong currentKeyLow = existingShelf.ReadKeyLowAt(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareScalar16Scalar16Tuple(currentKeyHigh, currentKeyLow, currentIdentityHigh, currentIdentityLow, encodedKeyHigh, encodedKeyLow, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                keyHighs[targetIndex] = encodedKeyHigh;
                keyLows[targetIndex] = encodedKeyLow;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKeyHigh == encodedKeyHigh && currentKeyLow == encodedKeyLow && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                return (childRouterOffset, 0, 0, existingCount, 0, Scalar16Scalar16InsertResult.AlreadyPresent, default);
            }

            keyHighs[targetIndex] = currentKeyHigh;
            keyLows[targetIndex] = currentKeyLow;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            keyHighs[targetIndex] = encodedKeyHigh;
            keyLows[targetIndex] = encodedKeyLow;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseScalar16Scalar8TransformSplitPlan(keyHighs, keyLows, childRouterKeyDepth, rightPrefixByte);
        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar16 leftShelf = new(leftShelfBytes, profile);
        Scalar16Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keyHighs.Length; i++)
        {
            bool goesRight = GetScalar16Scalar8Prefix(keyHighs[i], keyLows[i], splitKeyDepth) >= selectedRightPrefixByte;
            Scalar16Scalar16InsertResult result = goesRight
                ? rightShelf.Insert(keyHighs[i], keyLows[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keyHighs[i], keyLows[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (result != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split SS16-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
        long nextRouterOffset = 0;
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
            RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
            RouterWriter appendedWriter = new(appendedRouter.Span);
            appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
            nextRouterOffset = appendedRouter.Extent.Offset;
        }

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        childWriter.InitializeExpandedOneByte(
            childRouterKeyDepth,
            allocationClassId,
            CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: profile.ShelfExtentSize,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(profile.ShelfExtentSize / RouterLayout.Size)),
            arenaFlags: 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, profile.ShelfExtentSize);
        arena.MarkUsed(0);
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Scalar16Scalar16InsertResult.Inserted, telemetry);
    }

    /// <summary>
    /// Inserts one encoded tuple through the current rooted `SS8-8` routing graph and selects the first supported structural mutation path.<br/>
    /// The decision order is no-split shelf rewrite, root-prefix-visible split when an earlier root prefix still targets the same full shelf, then same-prefix shelf-to-router transform.<br/>
    /// This first orchestrator intentionally handles only the currently validated split shapes and does not claim general route-range refinement yet.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines shelf extent sizing.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when the route graph is invalid or the full-shelf split path cannot be selected safely.</exception>
    internal Scalar8Scalar8RoutedInsertResult InsertRoutedScalar8Scalar8(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        byte rootPrefixByte = GetScalar8Scalar8RootPrefix(encodedKey);
        byte[] rootRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, rootRouterBytes);
        RouterReader rootReader = new(rootRouterBytes);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        long shelfOffset = rootReader.FindTarget(rootPrefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-8 shelf route is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The routed SS8-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar8InsertResult noSplitResult = shelf.Insert(encodedKey, encodedIdentity, allowDuplicateKeys);

        if (noSplitResult == Scalar8Scalar8InsertResult.Inserted)
        {
            RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry noSplitCommit = CommitAndInvalidateRouterReadCache();
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoSplit,
                noSplitResult,
                shelfOffset,
                shelfOffset,
                0,
                noSplitCommit);
        }

        if (noSplitResult == Scalar8Scalar8InsertResult.AlreadyPresent)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoOp,
                noSplitResult,
                shelfOffset,
                0,
                0,
                default);
        }

        if (noSplitResult == Scalar8Scalar8InsertResult.KeyConflict)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.KeyConflict,
                noSplitResult,
                shelfOffset,
                0,
                0,
                default);
        }

        if (noSplitResult != Scalar8Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS8-8 routed insert result {noSplitResult}.");
        }

        byte leftRootPrefix = FindEarlierRootPrefixForSameTarget(rootReader, rootPrefixByte, shelfOffset);
        if (leftRootPrefix != rootPrefixByte)
        {
            (
                long leftShelfOffset,
                long rightShelfOffset,
                _,
                _,
                Scalar8Scalar8InsertResult splitResult,
                DataKernelCommitTelemetry splitCommit) = SplitRoutedScalar8Scalar8ByRootPrefix(
                    rootRouterOffset,
                    rootRouterBytes,
                    shelfOffset,
                    existingShelf,
                    rootPrefixByte,
                    profile,
                    encodedKey,
                    encodedIdentity);

            Scalar8Scalar8RoutedInsertKind kind = splitResult == Scalar8Scalar8InsertResult.Inserted
                ? Scalar8Scalar8RoutedInsertKind.RootPrefixSplit
                : Scalar8Scalar8RoutedInsertKind.NoOp;
            return new Scalar8Scalar8RoutedInsertResult(
                kind,
                splitResult,
                leftShelfOffset,
                leftShelfOffset,
                rightShelfOffset,
                splitCommit);
        }

        byte childRightPrefix = GetScalar8Scalar8Prefix(encodedKey, keyDepth: 1);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Scalar8Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar8Scalar8ByShelfTransform(
                shelfOffset,
                existingShelf,
                childRightPrefix,
                profile,
                encodedKey,
                encodedIdentity,
                rootReader.AllocationClassId,
                childRouterKeyDepth: 1);

        Scalar8Scalar8RoutedInsertKind transformKind = transformResult == Scalar8Scalar8InsertResult.Inserted
            ? Scalar8Scalar8RoutedInsertKind.ShelfTransformSplit
            : Scalar8Scalar8RoutedInsertKind.NoOp;
        return new Scalar8Scalar8RoutedInsertResult(
            transformKind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Appends a caller-populated `SS8-8` shelf and links multiple root-router prefix bytes to that same shelf in one commit.<br/>
    /// This helper exists for split-path validation where a single full shelf initially owns more than one root prefix byte.<br/>
    /// The supplied key and identity vectors are inserted through the shelf view, so persisted ordering and duplicate rules match normal shelf behavior.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that sizes the new shelf extent.</param>
    /// <param name="encodedKeys">The encoded scalar keys to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <param name="prefixBytes">The root-router prefix bytes to point at the new shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentException">Thrown when key and identity vector lengths differ.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar8Scalar8ShelfAndLinkRootRoutes(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<ulong> encodedKeys,
        ReadOnlySpan<ulong> encodedIdentities,
        ReadOnlySpan<byte> prefixBytes)
    {
        if (encodedKeys.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("SS8-8 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (encodedKeys.Length <= 0 || encodedKeys.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(encodedKeys), encodedKeys.Length, "SS8-8 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingReader = new(existingRouter);
        if (!existingReader.IsValid || !existingReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar8Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeys.Length; i++)
        {
            Scalar8Scalar8InsertResult result = shelf.Insert(encodedKeys[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-8 setup shelf insert at {i}, got {result}.");
            }
        }

        RawDataReservation routerReservation = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerReservation.Span);
        RouterWriter writer = new(routerReservation.Span);
        for (int i = 0; i < prefixBytes.Length; i++)
        {
            byte prefix = prefixBytes[i];
            writer.WriteRoute(prefix, prefix, prefix, shelfReservation.Extent.Offset);
        }

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Appends a caller-populated `SS8-8` shelf behind a new direct-index child router and links that child router from the root in one commit.<br/>
    /// This validation primitive creates a controlled deeper route graph where one child-router prefix owns a full shelf, allowing walked split behavior to be measured directly.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.</param>
    /// <param name="childPrefixByte">The child-router prefix byte that will point to the created shelf.</param>
    /// <param name="profile">The `SS8-8` shelf profile that sizes the new shelf extent.</param>
    /// <param name="encodedKeys">The encoded scalar keys to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when key and identity vector lengths differ.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar8Scalar8ShelfBehindChildRouter(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<ulong> encodedKeys,
        ReadOnlySpan<ulong> encodedIdentities)
    {
        if (encodedKeys.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("SS8-8 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (encodedKeys.Length <= 0 || encodedKeys.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(encodedKeys), encodedKeys.Length, "SS8-8 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar8Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeys.Length; i++)
        {
            Scalar8Scalar8InsertResult result = shelf.Insert(encodedKeys[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-8 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        childTargets[childPrefixByte] = shelfReservation.Extent.Offset;
        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Appends a caller-populated `SS16-8` shelf behind a new direct-index child router and links that child router from the root in one commit.<br/>
    /// This validation primitive mirrors the `SS8-8` deeper-route setup while keeping widened-key shelf population shape-local.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.</param>
    /// <param name="childPrefixByte">The child-router prefix byte that will point to the created shelf.</param>
    /// <param name="profile">The `SS16-8` shelf profile that sizes the new shelf extent.</param>
    /// <param name="encodedKeyHighs">The encoded high key halves to insert into the shelf.</param>
    /// <param name="encodedKeyLows">The encoded low key halves to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the supplied vectors have different lengths.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar16Scalar8ShelfBehindChildRouter(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Scalar16Scalar8Profile profile,
        ReadOnlySpan<ulong> encodedKeyHighs,
        ReadOnlySpan<ulong> encodedKeyLows,
        ReadOnlySpan<ulong> encodedIdentities)
    {
        if (encodedKeyHighs.Length != encodedKeyLows.Length || encodedKeyHighs.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("SS16-8 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (encodedKeyHighs.Length <= 0 || encodedKeyHighs.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(encodedKeyHighs), encodedKeyHighs.Length, "SS16-8 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar16Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeyHighs.Length; i++)
        {
            Scalar16Scalar8InsertResult result = shelf.Insert(encodedKeyHighs[i], encodedKeyLows[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Scalar16Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS16-8 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        childTargets[childPrefixByte] = shelfReservation.Extent.Offset;
        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Appends a caller-populated `FS32-8` shelf behind a new direct-index child router and links that child router from the root in one commit.<br/>
    /// This validation primitive mirrors the `SS16-8` deeper-route setup while keeping fixed-32-byte-key shelf population shape-local.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.</param>
    /// <param name="childPrefixByte">The child-router prefix byte that will point to the created shelf.</param>
    /// <param name="profile">The `FS32-8` shelf profile that sizes the new shelf extent.</param>
    /// <param name="key0s">The first encoded key lanes to insert into the shelf.</param>
    /// <param name="key1s">The second encoded key lanes to insert into the shelf.</param>
    /// <param name="key2s">The third encoded key lanes to insert into the shelf.</param>
    /// <param name="key3s">The fourth encoded key lanes to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the supplied vectors have different lengths.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateFixed32Scalar8ShelfBehindChildRouter(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Fixed32Scalar8Profile profile,
        ReadOnlySpan<ulong> key0s,
        ReadOnlySpan<ulong> key1s,
        ReadOnlySpan<ulong> key2s,
        ReadOnlySpan<ulong> key3s,
        ReadOnlySpan<ulong> encodedIdentities)
    {
        if (key0s.Length != key1s.Length || key0s.Length != key2s.Length || key0s.Length != key3s.Length || key0s.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("FS32-8 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (key0s.Length <= 0 || key0s.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(key0s), key0s.Length, "FS32-8 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar8 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < key0s.Length; i++)
        {
            Fixed32Scalar8InsertResult result = shelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-8 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        childTargets[childPrefixByte] = shelfReservation.Extent.Offset;
        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Appends a caller-populated `SS8-16` shelf behind a new direct-index child router and links that child router from the root in one commit.<br/>
    /// This validation primitive mirrors the `SS8-8` deeper-route setup while keeping widened-identity shelf population shape-local.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.</param>
    /// <param name="childPrefixByte">The child-router prefix byte that will point to the created shelf.</param>
    /// <param name="profile">The `SS8-16` shelf profile that sizes the new shelf extent.</param>
    /// <param name="encodedKeys">The encoded scalar keys to insert into the shelf.</param>
    /// <param name="encodedIdentityHighs">The encoded high identity halves to insert into the shelf.</param>
    /// <param name="encodedIdentityLows">The encoded low identity halves to insert into the shelf.</param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the supplied vectors have different lengths.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar8Scalar16ShelfBehindChildRouter(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Scalar8Scalar16Profile profile,
        ReadOnlySpan<ulong> encodedKeys,
        ReadOnlySpan<ulong> encodedIdentityHighs,
        ReadOnlySpan<ulong> encodedIdentityLows)
    {
        if (encodedKeys.Length != encodedIdentityHighs.Length || encodedKeys.Length != encodedIdentityLows.Length)
        {
            throw new ArgumentException("SS8-16 key and identity vectors must have the same length.", nameof(encodedIdentityLows));
        }

        if (encodedKeys.Length <= 0 || encodedKeys.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(encodedKeys), encodedKeys.Length, "SS8-16 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar8Scalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeys.Length; i++)
        {
            Scalar8Scalar16InsertResult result = shelf.Insert(encodedKeys[i], encodedIdentityHighs[i], encodedIdentityLows[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-16 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        childTargets[childPrefixByte] = shelfReservation.Extent.Offset;
        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Appends a caller-populated `SS16-16` shelf behind a new direct-index child router and links that child router from the root in one commit.<br/>
    /// This validation primitive mirrors the other deeper-route setups while keeping widened-key and widened-identity shelf population shape-local.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.</param>
    /// <param name="childPrefixByte">The child-router prefix byte that will point to the created shelf.</param>
    /// <param name="profile">The `SS16-16` shelf profile that sizes the new shelf extent.</param>
    /// <param name="encodedKeyHighs">The encoded high key halves to insert into the shelf.</param>
    /// <param name="encodedKeyLows">The encoded low key halves to insert into the shelf.</param>
    /// <param name="encodedIdentityHighs">The encoded high identity halves to insert into the shelf.</param>
    /// <param name="encodedIdentityLows">The encoded low identity halves to insert into the shelf.</param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the supplied vectors have different lengths.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateScalar16Scalar16ShelfBehindChildRouter(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Scalar16Scalar16Profile profile,
        ReadOnlySpan<ulong> encodedKeyHighs,
        ReadOnlySpan<ulong> encodedKeyLows,
        ReadOnlySpan<ulong> encodedIdentityHighs,
        ReadOnlySpan<ulong> encodedIdentityLows)
    {
        if (encodedKeyHighs.Length != encodedKeyLows.Length || encodedKeyHighs.Length != encodedIdentityHighs.Length || encodedKeyHighs.Length != encodedIdentityLows.Length)
        {
            throw new ArgumentException("SS16-16 key and identity vectors must have the same length.", nameof(encodedIdentityLows));
        }

        if (encodedKeyHighs.Length <= 0 || encodedKeyHighs.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(encodedKeyHighs), encodedKeyHighs.Length, "SS16-16 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Scalar16Scalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < encodedKeyHighs.Length; i++)
        {
            Scalar16Scalar16InsertResult result = shelf.Insert(encodedKeyHighs[i], encodedKeyLows[i], encodedIdentityHighs[i], encodedIdentityLows[i], allowDuplicateKeys: true);
            if (result != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS16-16 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        childTargets[childPrefixByte] = shelfReservation.Extent.Offset;
        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }

    /// <summary>
    /// Splits a full routed `SS8-8` shelf into an in-place left shelf and one appended right shelf, then updates one root route.<br/>
    /// This first split path only covers split boundaries that are representable by the owning root router's current prefix byte.<br/>
    /// The existing shelf is read, the incoming tuple is merged into sorted order, tuples whose first scalar key byte is below <paramref name="rightPrefixByte"/> remain left, and all others move right.<br/>
    /// Same-prefix splits are intentionally excluded because they require the later shelf-to-router transform path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="leftPrefixByte">The prefix byte that continues to route to the rewritten left shelf.</param>
    /// <param name="rightPrefixByte">The prefix byte that will route to the appended right shelf after the split.</param>
    /// <param name="profile">The `SS8-8` shelf profile used for both split shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <returns>The left shelf offset, right shelf offset, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar8Scalar8ByRootPrefix(
            long rootRouterOffset,
            byte leftPrefixByte,
            byte rightPrefixByte,
            Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity)
    {
        long leftShelfOffset = FindRouterTarget(rootRouterOffset, leftPrefixByte);
        if (leftShelfOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-8 left shelf route is unset.");
        }

        long currentRightTarget = FindRouterTarget(rootRouterOffset, rightPrefixByte);
        if (currentRightTarget != leftShelfOffset)
        {
            throw new InvalidDataException("The first split path expects both root prefixes to currently route to the same full shelf.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(leftShelfOffset, existingShelfBytes);
        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingRouterReader = new(existingRouter);
        if (!existingRouterReader.IsValid || !existingRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        return SplitRoutedScalar8Scalar8ByRootPrefix(
            rootRouterOffset,
            existingRouter,
            leftShelfOffset,
            existingShelfBytes,
            rightPrefixByte,
            profile,
            encodedKey,
            encodedIdentity);
    }

    /// <summary>
    /// Splits an already-routed full `SS8-8` shelf by root prefix using caller-provided router and shelf bytes.<br/>
    /// This reuse path avoids rereading the root router and full shelf when an outer insert decision has already loaded them.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="existingRouter">The already-read root router bytes.</param>
    /// <param name="leftShelfOffset">The file offset of the full shelf that will be rewritten as the left shelf.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="rightPrefixByte">The prefix byte that will route to the appended right shelf after the split.</param>
    /// <param name="profile">The `SS8-8` shelf profile used for both split shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <returns>The left shelf offset, right shelf offset, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when supplied byte buffers do not match their expected fixed sizes.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    private (
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar8Scalar8ByRootPrefix(
            long rootRouterOffset,
            ReadOnlySpan<byte> existingRouter,
            long leftShelfOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
            Scalar8Scalar8Profile profile,
            ulong encodedKey,
            ulong encodedIdentity)
    {
        if (existingRouter.Length != RouterLayout.Size)
        {
            throw new ArgumentException("The existing router buffer must match the fixed router page size.", nameof(existingRouter));
        }

        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled SS8-8 shelf extent size.", nameof(existingShelfBytes));
        }

        RouterReader existingRouterReader = new(existingRouter);
        if (!existingRouterReader.IsValid || !existingRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        Scalar8Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The first split path expects a valid full SS8-8 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keys = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey = existingShelf.ReadKeyAt(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareScalar8Scalar8Tuple(currentKey, currentIdentity, encodedKey, encodedIdentity) > 0)
            {
                keys[targetIndex] = encodedKey;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKey == encodedKey && currentIdentity == encodedIdentity)
            {
                return (leftShelfOffset, 0, existingCount, 0, Scalar8Scalar8InsertResult.AlreadyPresent, default);
            }

            keys[targetIndex] = currentKey;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            keys[targetIndex] = encodedKey;
            identities[targetIndex] = encodedIdentity;
        }

        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar8 leftShelf = new(leftShelfBytes, profile);
        Scalar8Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = GetScalar8Scalar8RootPrefix(keys[i]) >= rightPrefixByte;
            Scalar8Scalar8InsertResult result = goesRight
                ? rightShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split SS8-8 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The first split path requires both split shelves to receive at least one item.");
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(leftShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);
        RawDataReservation routerRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerRewrite.Span);
        RouterWriter writer = new(routerRewrite.Span);
        writer.WriteRoute(rightPrefixByte, rightPrefixByte, rightPrefixByte, rightAppend.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (leftShelfOffset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Scalar8Scalar8InsertResult.Inserted, telemetry);
    }

    /// <summary>
    /// Splits a full routed `SS8-8` shelf by transforming the shelf's existing offset into a child router and appending two replacement shelves.<br/>
    /// This path covers same-root-prefix splits where the root route must stay stable and the next key byte decides left/right ownership.<br/>
    /// The parent root router is not dirtied; the former shelf location is structurally reused as a direct-index one-byte child router at key depth `1`.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root prefix byte that currently routes to the full shelf and will continue routing to the transformed child router.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `SS8-8` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar8Scalar8ByShelfTransform(
            long rootRouterOffset,
            byte rootPrefixByte,
            byte rightPrefixByte,
            Scalar8Scalar8Profile profile,
            ulong encodedKey,
            ulong encodedIdentity)
    {
        byte[] rootRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, rootRouterBytes);
        RouterReader rootRouterReader = new(rootRouterBytes);
        if (!rootRouterReader.IsValid || !rootRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        ushort allocationClassId = rootRouterReader.AllocationClassId;
        long childRouterOffset = rootRouterReader.FindTarget(rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The routed SS8-8 transform source route is unset.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(childRouterOffset, existingShelfBytes);
        return SplitRoutedScalar8Scalar8ByShelfTransform(
            childRouterOffset,
            existingShelfBytes,
            rightPrefixByte,
            profile,
            encodedKey,
            encodedIdentity,
            allocationClassId,
            childRouterKeyDepth: 1);
    }

    /// <summary>
    /// Splits an already-routed full `SS8-8` shelf by transforming its offset into a child router using caller-provided shelf bytes.<br/>
    /// This reuse path avoids rereading the root router and full shelf when an outer insert decision has already loaded them.<br/>
    /// </summary>
    /// <param name="childRouterOffset">The old shelf offset that will be rewritten as the child router.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `SS8-8` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.</param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when supplied shelf bytes do not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when shelf validity or split partitioning is invalid.</exception>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Scalar8Scalar8InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedScalar8Scalar8ByShelfTransform(
            long childRouterOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        ushort allocationClassId,
        ushort childRouterKeyDepth)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled SS8-8 shelf extent size.", nameof(existingShelfBytes));
        }

        Scalar8Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full SS8-8 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keys = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey = existingShelf.ReadKeyAt(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareScalar8Scalar8Tuple(currentKey, currentIdentity, encodedKey, encodedIdentity) > 0)
            {
                keys[targetIndex] = encodedKey;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKey == encodedKey && currentIdentity == encodedIdentity)
            {
                return (childRouterOffset, 0, 0, existingCount, 0, Scalar8Scalar8InsertResult.AlreadyPresent, default);
            }

            keys[targetIndex] = currentKey;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            keys[targetIndex] = encodedKey;
            identities[targetIndex] = encodedIdentity;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseScalar8Scalar8TransformSplitPlan(keys, childRouterKeyDepth, rightPrefixByte);
        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar8 leftShelf = new(leftShelfBytes, profile);
        Scalar8Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = GetScalar8Scalar8Prefix(keys[i], splitKeyDepth) >= selectedRightPrefixByte;
            Scalar8Scalar8InsertResult result = goesRight
                ? rightShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true);
            if (result != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split SS8-8 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
        long nextRouterOffset = 0;
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
            RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
            RouterWriter appendedWriter = new(appendedRouter.Span);
            appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
            nextRouterOffset = appendedRouter.Extent.Offset;
        }

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        childWriter.InitializeExpandedOneByte(
            childRouterKeyDepth,
            allocationClassId,
            CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: profile.ShelfExtentSize,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(profile.ShelfExtentSize / RouterLayout.Size)),
            arenaFlags: 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, profile.ShelfExtentSize);
        arena.MarkUsed(0);
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Scalar8Scalar8InsertResult.Inserted, telemetry);
    }

    /// <summary>
    /// Chooses the byte depth and right-side prefix boundary for an `SS8-8` transform split from the sorted tuple set being repartitioned.<br/>
    /// The search starts at the immediate child-router depth and advances until it finds a prefix byte that can divide the full shelf plus incoming tuple into two replacement shelves.<br/>
    /// This allows bulk insert streams with long common prefixes to grow by appending a short router chain instead of failing at the first identical byte.<br/>
    /// </summary>
    /// <param name="sortedKeys">The complete sorted key set for the full shelf plus the incoming tuple.</param>
    /// <param name="firstKeyDepth">The first encoded key byte depth that can be owned by the router being created at the transformed shelf offset.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <returns>The byte depth and first prefix byte that should route to the right replacement shelf.</returns>
    /// <exception cref="InvalidDataException">Thrown when the key set has no usable prefix boundary in the encoded key.</exception>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseScalar8Scalar8TransformSplitPlan(
        ReadOnlySpan<ulong> sortedKeys,
        ushort firstKeyDepth,
        byte hintRightPrefixByte)
    {
        if (sortedKeys.Length < 2)
        {
            throw new InvalidDataException("The transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < Scalar8Scalar8Layout.KeySize; keyDepth++)
        {
            if (TryChooseScalar8Scalar8TransformSplitRightPrefix(sortedKeys, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The transform split path requires at least two distinct prefixes in the remaining encoded key bytes.");
    }

    /// <summary>
    /// Tries to create two replacement shelves for a full `SS8-8` shelf at one specific router byte depth.<br/>
    /// The method merges the incoming tuple with the existing sorted shelf, chooses a median-near prefix boundary, and populates left/right shelf byte arrays.<br/>
    /// Returning false means that byte depth cannot distinguish the tuple set and the caller should try another structural split strategy.<br/>
    /// </summary>
    /// <param name="existingShelf">The full existing shelf as a decoded mutable sidecar.</param>
    /// <param name="keyDepth">The encoded key byte depth used to divide the replacement shelves.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix at <paramref name="keyDepth"/>.</param>
    /// <param name="profile">The `SS8-8` shelf profile used for both replacement shelves.</param>
    /// <param name="encodedKey">The encoded scalar key to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="selectedRightPrefixByte">The selected first right-side prefix byte.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples in the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples in the right replacement shelf.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private static bool TryCreateScalar8Scalar8SplitShelves(
        ReadOnlySpan<byte> existingShelfBytes,
        ushort keyDepth,
        byte hintRightPrefixByte,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        out byte selectedRightPrefixByte,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out Scalar8Scalar8InsertResult insertResult)
    {
        selectedRightPrefixByte = 0;
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        Scalar8Scalar8ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The split path expects a valid full SS8-8 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] keys = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey = existingShelf.ReadKeyAt(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareScalar8Scalar8Tuple(currentKey, currentIdentity, encodedKey, encodedIdentity) > 0)
            {
                keys[targetIndex] = encodedKey;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKey == encodedKey && currentIdentity == encodedIdentity)
            {
                insertResult = Scalar8Scalar8InsertResult.AlreadyPresent;
                return false;
            }

            keys[targetIndex] = currentKey;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            keys[targetIndex] = encodedKey;
            identities[targetIndex] = encodedIdentity;
        }

        if (!TryChooseScalar8Scalar8TransformSplitRightPrefix(keys, keyDepth, hintRightPrefixByte, out selectedRightPrefixByte))
        {
            return false;
        }

        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar8 leftShelf = new(leftShelfBytes, profile);
        Scalar8Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < keys.Length; i++)
        {
            bool goesRight = GetScalar8Scalar8Prefix(keys[i], keyDepth) >= selectedRightPrefixByte;
            Scalar8Scalar8InsertResult itemResult = goesRight
                ? rightShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(keys[i], identities[i], allowDuplicateKeys: true);
            if (itemResult != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split SS8-8 insert at {i}, got {itemResult}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            return false;
        }

        leftItemCount = leftShelf.ItemCount;
        rightItemCount = rightShelf.ItemCount;
        insertResult = Scalar8Scalar8InsertResult.Inserted;
        return true;
    }

