        if (!TryChooseFixed32Scalar8TransformSplitRightPrefix(key0s, key1s, key2s, key3s, keyDepth, hintRightPrefixByte, out selectedRightPrefixByte))
        {
            return false;
        }

        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar8 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar8 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = GetFixed32Scalar8Prefix(key0s[i], key1s[i], key2s[i], key3s[i], keyDepth) >= selectedRightPrefixByte;
            Fixed32Scalar8InsertResult itemResult = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true);
            if (itemResult != Fixed32Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split FS32-8 insert at {i}, got {itemResult}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            return false;
        }

        leftItemCount = leftShelf.ItemCount;
        rightItemCount = rightShelf.ItemCount;
        insertResult = Fixed32Scalar8InsertResult.Inserted;
        return true;
    }

