        long shelfOffset = FindRouterTarget(childRouterOffset, childPrefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The child route to the SS16-16 shelf is unset.");
        }

        kernel.Read(shelfOffset, destination);
        Scalar16Scalar16ReadOnly shelf = new(destination, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The two-level routed SS16-16 shelf bytes are invalid.");
        }

        return (childRouterOffset, shelfOffset);
    }

    /// <summary>
    /// Inserts one encoded tuple into a shelf reached through a root router and one direct-index child router without performing split handling.<br/>
    /// This validates the first post-transform mutation path while deeper routed insert orchestration and generalized split selection are still being designed.<br/>
    /// If the tuple is already present, the method returns without committing because the physical mutation is a no-op.<br/>
    /// If the shelf is full or a unique-key conflict occurs, the method returns that insert result without committing so the next structural path can be added later.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The first encoded key byte used by the root router.</param>
    /// <param name="childPrefixByte">The second encoded key byte used by the transformed child router.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when either route is unset or the shelf bytes are invalid.</exception>
    internal Scalar8Scalar8RoutedInsertResult InsertTwoLevelRoutedScalar8Scalar8NoSplit(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        long childRouterOffset = FindRouterTarget(rootRouterOffset, rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The root route to the transformed child router is unset.");
        }

        long shelfOffset = FindRouterTarget(childRouterOffset, childPrefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The child route to the SS8-8 shelf is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The two-level routed SS8-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar8InsertResult insertResult = shelf.Insert(encodedKey, encodedIdentity, allowDuplicateKeys);
        if (insertResult == Scalar8Scalar8InsertResult.Inserted)
        {
            RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.TwoLevelNoSplit,
                insertResult,
                shelfOffset,
                shelfOffset,
                0,
                telemetry);
        }

        Scalar8Scalar8RoutedInsertKind kind = insertResult == Scalar8Scalar8InsertResult.KeyConflict
            ? Scalar8Scalar8RoutedInsertKind.KeyConflict
            : Scalar8Scalar8RoutedInsertKind.NoOp;
        return new Scalar8Scalar8RoutedInsertResult(
            kind,
            insertResult,
            shelfOffset,
            0,
            0,
            default);
    }

