    /// <summary>
    /// Inserts one encoded tuple through the classified `SS16-8` route walker and selects the first supported structural mutation path.<br/>
    /// The decision order matches the current `SS8-8` behavior envelope: no-split shelf rewrite, duplicate/no-op or key conflict, parent-route split, then shelf-to-router transform.<br/>
    /// This keeps widened-key orchestration shape-local while preserving the same low-friction caller contract for upcoming physical shapes.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS16-8` shelf profile that determines shelf extent sizing.</param>
    /// <param name="encodedKeyHigh">The encoded high key half to insert.</param>
    /// <param name="encodedKeyLow">The encoded low key half to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS16-8` shelf or the split cannot be selected safely.</exception>
    internal Scalar16Scalar8RoutedInsertResult InsertWalkedRoutedScalar16Scalar8(
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        ulong encodedKeyHigh,
        ulong encodedKeyLow,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Scalar16Scalar8RoutePathTarget pathTarget = WalkScalar16Scalar8RoutePathTarget(rootRouterOffset, encodedKeyHigh, encodedKeyLow, maxRouterHops);
        Scalar16Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS16-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar16Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS16-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar16Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar16Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKeyHigh, encodedKeyLow, encodedIdentity, allowDuplicateKeys, out Scalar16Scalar8MutationBounds mutationBounds);
        if (insertResult == Scalar16Scalar8InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Scalar16Scalar8InsertResult.AlreadyPresent)
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Scalar16Scalar8InsertResult.KeyConflict)
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Scalar16Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS16-8 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedScalar16Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            encodedKeyHigh,
            encodedKeyLow,
            encodedIdentity,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Scalar16Scalar8InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Scalar16Scalar8RoutedInsertResult(
                Scalar16Scalar8RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar16Scalar8Prefix(encodedKeyHigh, encodedKeyLow, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Scalar16Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar16Scalar8ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                encodedKeyHigh,
                encodedKeyLow,
                encodedIdentity,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Scalar16Scalar8RoutedInsertKind kind = transformResult == Scalar16Scalar8InsertResult.Inserted
            ? Scalar16Scalar8RoutedInsertKind.WalkedShelfTransformSplit
            : Scalar16Scalar8RoutedInsertKind.NoOp;
        return new Scalar16Scalar8RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `FS32-8` route walker when the routed shelf has room for a no-split rewrite.<br/>
    /// The method supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// Full-shelf split selection remains deliberately outside this slice; walked transform and parent-route refinement are added as separate validated steps.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-8` shelf profile that determines shelf extent sizing.</param>
    /// <param name="key0">The first encoded key lane to insert.</param>
    /// <param name="key1">The second encoded key lane to insert.</param>
    /// <param name="key2">The third encoded key lane to insert.</param>
    /// <param name="key3">The fourth encoded key lane to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `FS32-8` shelf or when a full shelf requires a not-yet-selected walked split path.</exception>
    internal Fixed32Scalar8RoutedInsertResult InsertWalkedRoutedFixed32Scalar8(
        long rootRouterOffset,
        Fixed32Scalar8Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Fixed32Scalar8RoutePathTarget pathTarget = WalkFixed32Scalar8RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Fixed32Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed FS32-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Fixed32Scalar8 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys, out Fixed32Scalar8MutationBounds mutationBounds);
        if (insertResult == Fixed32Scalar8InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Fixed32Scalar8RoutedInsertResult(
                Fixed32Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Fixed32Scalar8InsertResult.AlreadyPresent)
        {
            return new Fixed32Scalar8RoutedInsertResult(
                Fixed32Scalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Fixed32Scalar8InsertResult.KeyConflict)
        {
            return new Fixed32Scalar8RoutedInsertResult(
                Fixed32Scalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Fixed32Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported FS32-8 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedFixed32Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentity,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Fixed32Scalar8InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Fixed32Scalar8RoutedInsertResult(
                Fixed32Scalar8RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar8Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Fixed32Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedFixed32Scalar8ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                key0,
                key1,
                key2,
                key3,
                encodedIdentity,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Fixed32Scalar8RoutedInsertKind kind = transformResult == Fixed32Scalar8InsertResult.Inserted
            ? Fixed32Scalar8RoutedInsertKind.WalkedShelfTransformSplit
            : Fixed32Scalar8RoutedInsertKind.NoOp;
        return new Fixed32Scalar8RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Inserts one encoded tuple into a shelf reached by the classified `SS8-8` route walker without performing split handling.<br/>
    /// This path supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// The classifier reads make this path more general but not cheaper than direct fast paths where the route target shape is already known.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to use while walking routers to the target shelf.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-8` shelf.</exception>
    internal Scalar8Scalar8RoutedInsertResult InsertWalkedRoutedScalar8Scalar8NoSplit(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy = Scalar8Scalar8RouteReadPolicy.Uncached)
    {
        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops, readPolicy);
        Scalar8Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS8-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKey, encodedIdentity, allowDuplicateKeys, out Scalar8Scalar8MutationBounds mutationBounds);
        if (insertResult == Scalar8Scalar8InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        Scalar8Scalar8RoutedInsertKind kind = insertResult == Scalar8Scalar8InsertResult.KeyConflict
            ? Scalar8Scalar8RoutedInsertKind.KeyConflict
            : Scalar8Scalar8RoutedInsertKind.NoOp;
        return new Scalar8Scalar8RoutedInsertResult(
            kind,
            insertResult,
            target.Offset,
            0,
            0,
            default);
    }

    /// <summary>
    /// Inserts one encoded tuple through the classified `SS8-8` route walker and handles the first deeper split case.<br/>
    /// The current deeper split case is same-prefix transmorphic growth: when the walked target shelf is full, that shelf offset is rewritten as the next-depth router and two replacement shelves are appended.<br/>
    /// This keeps the parent router stable and makes file growth/slack behavior measurable before adding parent-router route refinement below the root.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `SS8-8` shelf profile that determines the shelf extent length.</param>
    /// <param name="encodedKey">The encoded scalar key to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="readPolicy">The route-read policy to use while walking routers to the target shelf.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `SS8-8` shelf or the split cannot be selected safely.</exception>
    internal Scalar8Scalar8RoutedInsertResult InsertWalkedRoutedScalar8Scalar8(
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ulong encodedKey,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops,
        Scalar8Scalar8RouteReadPolicy readPolicy = Scalar8Scalar8RouteReadPolicy.Uncached)
    {
        Scalar8Scalar8RoutePathTarget pathTarget = WalkScalar8Scalar8RoutePathTarget(rootRouterOffset, encodedKey, maxRouterHops, readPolicy);
        Scalar8Scalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an SS8-8 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Scalar8Scalar8ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed SS8-8 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Scalar8Scalar8 shelf = new(rewrittenShelf, profile);
        Scalar8Scalar8InsertResult insertResult = shelf.InsertWithMutationBounds(encodedKey, encodedIdentity, allowDuplicateKeys, out Scalar8Scalar8MutationBounds mutationBounds);
        if (insertResult == Scalar8Scalar8InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Scalar8Scalar8InsertResult.AlreadyPresent)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Scalar8Scalar8InsertResult.KeyConflict)
        {
            return new Scalar8Scalar8RoutedInsertResult(
                Scalar8Scalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Scalar8Scalar8InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported SS8-8 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedScalar8Scalar8ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            encodedKey,
            encodedIdentity,
            target.AllocationClassId,
            out Scalar8Scalar8RoutedInsertResult parentRouteSplit))
        {
            return parentRouteSplit;
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetScalar8Scalar8Prefix(encodedKey, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long leftShelfOffset,
            long rightShelfOffset,
            _,
            _,
            Scalar8Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedScalar8Scalar8ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                encodedKey,
                encodedIdentity,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Scalar8Scalar8RoutedInsertKind kind = transformResult == Scalar8Scalar8InsertResult.Inserted
            ? Scalar8Scalar8RoutedInsertKind.WalkedShelfTransformSplit
            : Scalar8Scalar8RoutedInsertKind.NoOp;
        return new Scalar8Scalar8RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            leftShelfOffset,
            rightShelfOffset,
            transformCommit);
    }

    /// <summary>
    /// Splits a full max-growth `VS8` shelf by transforming that shelf offset into a direct child router.<br/>
    /// The full shelf plus incoming tuple are merged in persisted key/identity order, a median-near raw-key byte boundary is selected, and two replacement shelves are appended.<br/>
    /// If all rows share the immediate child byte, the method appends a short router chain until a later raw-key byte can divide the replacement shelves.<br/>
    /// </summary>
    /// <param name="childRouterOffset">The existing shelf offset that will be rewritten as the child router.</param>
    /// <param name="existingShelfBytes">The full existing shelf bytes.</param>
    /// <param name="rightPrefixByte">The incoming key prefix byte at <paramref name="childRouterKeyDepth"/>.</param>
    /// <param name="profile">The current max-growth `VS8` shelf profile.</param>
    /// <param name="key">The incoming raw byte key.</param>
    /// <param name="encodedIdentity">The incoming encoded identity.</param>
    /// <param name="allocationClassId">The router allocation class identifier to preserve.</param>
    /// <param name="childRouterKeyDepth">The key byte depth owned by the router replacing the shelf.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        VarKeyScalar8InsertResult InsertResult,
            DataKernelCommitTelemetry Commit) SplitRoutedVarKeyScalar8ByShelfTransform(
            long childRouterOffset,
            VarKeyScalar8MutableShelf existingShelf,
            byte rightPrefixByte,
            VarKeyScalar8Profile profile,
            ReadOnlySpan<byte> key,
            ulong encodedIdentity,
            ushort allocationClassId,
            ushort childRouterKeyDepth,
            VarKeyScalar8RouteMutationHint routeMutationHint)
    {
        if (existingShelf.Bytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled VS8 shelf extent size.", nameof(existingShelf));
        }

        if (!TryCreateVarKeyScalar8SplitShelves(
            existingShelf,
            childRouterKeyDepth,
            rightPrefixByte,
            profile,
            key,
            encodedIdentity,
            out ushort splitKeyDepth,
            out byte selectedRightPrefixByte,
            out byte[] selectedPrefixStem,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out int leftItemCount,
            out int rightItemCount,
            out VarKeyScalar8InsertResult insertResult))
        {
            return (childRouterOffset, 0, 0, 0, 0, insertResult, default);
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        VarKeyScalar8TransformRouterPlan routerPlan = ChooseVarKeyScalar8TransformRouterPlan(childRouterKeyDepth, splitKeyDepth, selectedPrefixStem, routeMutationHint);
        if (routerPlan.Kind == VarKeyScalar8TransformRouterKind.ExpandedOneByte)
        {
            childWriter.InitializeExpandedOneByte(
                childRouterKeyDepth,
                allocationClassId,
                CreateUniformScalar8Scalar8RouteTargets(0, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        }
        else if (routerPlan.Kind == VarKeyScalar8TransformRouterKind.CompressedMultiByte)
        {
            RouterMultiByteRouteSnapshot[] routes =
            [
                new(routerPlan.PrefixStem, 0, checked((byte)(selectedRightPrefixByte - 1)), leftAppend.Extent.Offset),
                new(routerPlan.PrefixStem, selectedRightPrefixByte, byte.MaxValue, rightAppend.Extent.Offset)
            ];
            childWriter.InitializeCompressedMultiByte(
                routerPlan.PrefixByteCount,
                childRouterKeyDepth,
                maxRouteCount: 2,
                allocationClassId,
                routes);
        }
        else
        {
            int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
            long nextRouterOffset = 0;
            for (int i = appendedRouterCount - 1; i >= 0; i--)
            {
                ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
                long[] targets = routerDepth == splitKeyDepth
                    ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                    : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
                RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
                RouterWriter appendedWriter = new(appendedRouter.Span);
                appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
                nextRouterOffset = appendedRouter.Extent.Offset;
            }

            childWriter.InitializeExpandedOneByte(
                childRouterKeyDepth,
                allocationClassId,
                CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        }

        int varKeyScalar8RouterArenaLength = profile.ShelfExtentSize;
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: varKeyScalar8RouterArenaLength,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(varKeyScalar8RouterArenaLength / RouterLayout.Size)),
            arenaFlags: varKeyScalar8RouterArenaLength > ushort.MaxValue + 1 ? RouterLayout.ArenaLengthFromPageCountFlag : 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, varKeyScalar8RouterArenaLength);
        arena.MarkUsed(0);
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftItemCount, rightItemCount, insertResult, telemetry);
    }

    /// <summary>
    /// Creates two replacement shelves for a full `VS8` shelf at a selected raw-key byte boundary.<br/>
    /// The method keeps raw bytes as the comparison source, preserving the current storage model and avoiding text or typed projection in the shelf layer.<br/>
    /// Returning false means the key set cannot be separated by any available raw-key byte and therefore needs a later overflow/duplicate strategy.<br/>
    /// </summary>
    /// <param name="existingShelf">The full existing shelf as a decoded mutable sidecar.</param>
    /// <param name="firstKeyDepth">The first raw key byte depth to consider for the replacement router.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="profile">The `VS8` shelf profile used for both replacement shelves.</param>
    /// <param name="key">The incoming raw byte key.</param>
    /// <param name="encodedIdentity">The incoming encoded identity.</param>
    /// <param name="splitKeyDepth">The raw key byte depth selected for the split boundary.</param>
    /// <param name="selectedRightPrefixByte">The first prefix byte routed to the right replacement shelf.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples in the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples in the right replacement shelf.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private static bool TryCreateVarKeyScalar8SplitShelves(
        VarKeyScalar8MutableShelf existingShelf,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        VarKeyScalar8Profile profile,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        out ushort splitKeyDepth,
        out byte selectedRightPrefixByte,
        out byte[] selectedPrefixStem,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out VarKeyScalar8InsertResult insertResult)
    {
        splitKeyDepth = 0;
        selectedRightPrefixByte = 0;
        selectedPrefixStem = [];
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        int existingCount = existingShelf.ItemCount;
        int totalCount = checked(existingCount + 1);
        int[] rentedKeyOffsets = ArrayPool<int>.Shared.Rent(totalCount);
        int[] rentedKeyLengths = ArrayPool<int>.Shared.Rent(totalCount);
        ulong[] rentedIdentities = ArrayPool<ulong>.Shared.Rent(totalCount);
        try
        {
            Span<int> keyOffsets = rentedKeyOffsets.AsSpan(0, totalCount);
            Span<int> keyLengths = rentedKeyLengths.AsSpan(0, totalCount);
            Span<ulong> identities = rentedIdentities.AsSpan(0, totalCount);
            bool inserted = false;
            int targetIndex = 0;
            for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
            {
                ReadOnlySpan<byte> currentKey = existingShelf.ReadKeyAt(sourceIndex);
                ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
                if (!inserted && CompareVarKeyScalar8Tuple(currentKey, currentIdentity, key, encodedIdentity) > 0)
                {
                    keyOffsets[targetIndex] = -1;
                    keyLengths[targetIndex] = key.Length;
                    identities[targetIndex] = encodedIdentity;
                    targetIndex++;
                    inserted = true;
                }

                if (currentKey.SequenceEqual(key) && currentIdentity == encodedIdentity)
                {
                    insertResult = VarKeyScalar8InsertResult.AlreadyPresent;
                    return false;
                }

                existingShelf.ReadKeyLocationAt(sourceIndex, out int currentKeyOffset, out int currentKeyLength);
                keyOffsets[targetIndex] = currentKeyOffset;
                keyLengths[targetIndex] = currentKeyLength;
                identities[targetIndex] = currentIdentity;
                targetIndex++;
            }

            if (!inserted)
            {
                keyOffsets[targetIndex] = -1;
                keyLengths[targetIndex] = key.Length;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
            }

            if (targetIndex != totalCount)
            {
                throw new InvalidDataException("The VS8 transform split source map did not cover the complete tuple set.");
            }

            (splitKeyDepth, selectedRightPrefixByte) = ChooseVarKeyScalar8TransformSplitPlan(
                existingShelf,
                keyOffsets,
                keyLengths,
                key,
                firstKeyDepth,
                hintRightPrefixByte,
                profile.MaxKeyLength);
            selectedPrefixStem = CreateVarKeyScalar8SplitPrefixStem(
                ReadVarKeyScalar8SplitSourceKey(existingShelf.Bytes, keyOffsets[0], keyLengths[0], key),
                firstKeyDepth,
                splitKeyDepth);
            if (!TryBuildVarKeyScalar8SplitShelvesFromSources(
                existingShelf,
                keyOffsets,
                keyLengths,
                identities,
                key,
                splitKeyDepth,
                selectedRightPrefixByte,
                profile,
                out leftShelfBytes,
                out rightShelfBytes,
                out leftItemCount,
                out rightItemCount))
            {
                return false;
            }

            insertResult = VarKeyScalar8InsertResult.Inserted;
            return true;
        }
        finally
        {
            ArrayPool<int>.Shared.Return(rentedKeyOffsets, clearArray: false);
            ArrayPool<int>.Shared.Return(rentedKeyLengths, clearArray: false);
            ArrayPool<ulong>.Shared.Return(rentedIdentities, clearArray: false);
        }
    }

    /// <summary>
    /// Builds the two replacement `VS8` shelves directly from the sorted split source map.<br/>
    /// The method writes disk-shaped shelf images in one pass and avoids cloned key arrays, tuple lists, and a second read-only shelf decode.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="keyOffsets">The sorted key-payload offsets for existing tuples, with negative values representing the incoming tuple.</param>
    /// <param name="keyLengths">The sorted key lengths matching <paramref name="keyOffsets"/>.</param>
    /// <param name="identities">The sorted encoded identities matching <paramref name="keyOffsets"/>.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="splitKeyDepth">The raw-key byte depth selected for the split boundary.</param>
    /// <param name="selectedRightPrefixByte">The first prefix byte routed to the right replacement shelf.</param>
    /// <param name="profile">The `VS8` shelf profile used by both replacement shelves.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples written to the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples written to the right replacement shelf.</param>
    /// <returns>`true` when both replacement shelves were non-empty and fit the current profile.</returns>
    private static bool TryBuildVarKeyScalar8SplitShelvesFromSources(
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<ulong> identities,
        ReadOnlySpan<byte> incomingKey,
        ushort splitKeyDepth,
        byte selectedRightPrefixByte,
        VarKeyScalar8Profile profile,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount)
    {
        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        VarKeyScalar8Layout.Initialize(leftShelfBytes, profile);
        VarKeyScalar8Layout.Initialize(rightShelfBytes, profile);

        int leftSlotCursor = VarKeyScalar8Layout.HeaderSize;
        int rightSlotCursor = VarKeyScalar8Layout.HeaderSize;
        int leftRecordCursor = VarKeyScalar8Layout.HeaderSize + VarKeyScalar8Layout.ReadSlotCapacityBytes(leftShelfBytes);
        int rightRecordCursor = VarKeyScalar8Layout.HeaderSize + VarKeyScalar8Layout.ReadSlotCapacityBytes(rightShelfBytes);
        int leftSlotCapacityBytes = VarKeyScalar8Layout.ReadSlotCapacityBytes(leftShelfBytes);
        int rightSlotCapacityBytes = VarKeyScalar8Layout.ReadSlotCapacityBytes(rightShelfBytes);
        leftItemCount = 0;
        rightItemCount = 0;

        for (int i = 0; i < keyOffsets.Length; i++)
        {
            ReadOnlySpan<byte> currentKey = ReadVarKeyScalar8SplitSourceKey(existingShelf.Bytes, keyOffsets[i], keyLengths[i], incomingKey);
            ulong currentIdentity = identities[i];
            bool goesRight = GetVarKeyScalar8SplitSourcePrefix(existingShelf.Bytes, keyOffsets[i], keyLengths[i], incomingKey, splitKeyDepth) >= selectedRightPrefixByte;
            byte[] targetBytes = goesRight ? rightShelfBytes : leftShelfBytes;
            int slotCursor = goesRight ? rightSlotCursor : leftSlotCursor;
            int recordCursor = goesRight ? rightRecordCursor : leftRecordCursor;
            int slotCapacityBytes = goesRight ? rightSlotCapacityBytes : leftSlotCapacityBytes;
            if (slotCursor + VarKeyScalar8Layout.SlotSize > VarKeyScalar8Layout.HeaderSize + slotCapacityBytes)
            {
                return false;
            }

            int recordLength = VarKeyScalar8Layout.GetNewRecordLength(currentKey.Length);
            if (recordCursor + recordLength > profile.ShelfExtentSize)
            {
                return false;
            }

            VarKeyScalar8Layout.WriteRecord(targetBytes, recordCursor, currentKey, currentIdentity);
            VarKeyScalar8Layout.WriteSlotRecordOffset(targetBytes, slotCursor, recordCursor);
            VarKeyScalar8Layout.WriteSlotKeyPrefix(targetBytes, slotCursor, VarKeyScalar8Layout.CreateKeyPrefix(currentKey));
            slotCursor += VarKeyScalar8Layout.SlotSize;
            recordCursor += recordLength;
            if (goesRight)
            {
                rightSlotCursor = slotCursor;
                rightRecordCursor = recordCursor;
                rightItemCount++;
            }
            else
            {
                leftSlotCursor = slotCursor;
                leftRecordCursor = recordCursor;
                leftItemCount++;
            }
        }

        if (leftItemCount == 0 || rightItemCount == 0)
        {
            return false;
        }

        VarKeyScalar8Layout.WriteItemCount(leftShelfBytes, leftItemCount);
        VarKeyScalar8Layout.WriteSlotStreamLength(leftShelfBytes, leftSlotCursor - VarKeyScalar8Layout.HeaderSize);
        VarKeyScalar8Layout.WriteRecordArenaEnd(leftShelfBytes, leftRecordCursor);
        VarKeyScalar8Layout.WriteItemCount(rightShelfBytes, rightItemCount);
        VarKeyScalar8Layout.WriteSlotStreamLength(rightShelfBytes, rightSlotCursor - VarKeyScalar8Layout.HeaderSize);
        VarKeyScalar8Layout.WriteRecordArenaEnd(rightShelfBytes, rightRecordCursor);
        return true;
    }

    /// <summary>
    /// Reads a key from the split source map without cloning it into an intermediate array.<br/>
    /// A negative source slot represents the incoming tuple; non-negative slots point at the existing mutable shelf sidecar.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlot">The source slot index, or a negative value for the incoming tuple.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <returns>The key bytes for the mapped source tuple.</returns>
    private static ReadOnlySpan<byte> ReadVarKeyScalar8SplitSourceKey(
        VarKeyScalar8MutableShelf existingShelf,
        int sourceSlot,
        ReadOnlySpan<byte> incomingKey)
    {
        return sourceSlot < 0 ? incomingKey : existingShelf.ReadKeyAt(sourceSlot);
    }

    /// <summary>
    /// Reads a key from predecoded split key-location arrays without decoding the shelf record header again.<br/>
    /// A negative key offset represents the incoming tuple; non-negative offsets point at raw key payload bytes in the existing shelf image.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffset">The raw key payload offset, or a negative value for the incoming tuple.</param>
    /// <param name="keyLength">The raw key length in bytes.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <returns>The key bytes for the mapped source tuple.</returns>
    private static ReadOnlySpan<byte> ReadVarKeyScalar8SplitSourceKey(
        byte[] existingShelfBytes,
        int keyOffset,
        int keyLength,
        ReadOnlySpan<byte> incomingKey)
    {
        return keyOffset < 0 ? incomingKey : existingShelfBytes.AsSpan(keyOffset, keyLength);
    }

    /// <summary>
    /// Reads one split-boundary prefix byte from predecoded key-location arrays without constructing a span.<br/>
    /// This is used by deep shared-prefix scans where the same source descriptors are probed at many raw-key depths.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffset">The raw key payload offset, or a negative value for the incoming tuple.</param>
    /// <param name="keyLength">The raw key length in bytes.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="keyDepth">The raw-key byte depth to read.</param>
    /// <returns>The prefix byte at <paramref name="keyDepth"/>, or zero when the depth is beyond the key length.</returns>
    private static byte GetVarKeyScalar8SplitSourcePrefix(
        byte[] existingShelfBytes,
        int keyOffset,
        int keyLength,
        ReadOnlySpan<byte> incomingKey,
        int keyDepth)
    {
        if (keyDepth < 0)
        {
            return 0;
        }

        if (keyOffset < 0)
        {
            return keyDepth < incomingKey.Length ? incomingKey[keyDepth] : (byte)0;
        }

        return keyDepth < keyLength ? existingShelfBytes[keyOffset + keyDepth] : (byte)0;
    }

    /// <summary>
    /// Reads an encoded identity from the split source map without creating an intermediate tuple object.<br/>
    /// A negative source slot represents the incoming tuple; non-negative slots point at the existing mutable shelf sidecar.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlot">The source slot index, or a negative value for the incoming tuple.</param>
    /// <param name="incomingIdentity">The incoming encoded 8-byte identity.</param>
    /// <returns>The encoded identity for the mapped source tuple.</returns>
    private static ulong ReadVarKeyScalar8SplitSourceIdentity(
        VarKeyScalar8MutableShelf existingShelf,
        int sourceSlot,
        ulong incomingIdentity)
    {
        return sourceSlot < 0 ? incomingIdentity : existingShelf.ReadIdentityAt(sourceSlot);
    }

    private static byte[] CreateVarKeyScalar8SplitPrefixStem(ReadOnlySpan<byte> representativeKey, ushort firstKeyDepth, ushort splitKeyDepth)
    {
        int stemLength = splitKeyDepth - firstKeyDepth;
        byte[] stem = new byte[stemLength];
        for (int i = 0; i < stem.Length; i++)
        {
            stem[i] = GetVarKeyScalar8Prefix(representativeKey, firstKeyDepth + i);
        }

        return stem;
    }

    private static VarKeyScalar8TransformRouterPlan ChooseVarKeyScalar8TransformRouterPlan(
        ushort childRouterKeyDepth,
        ushort splitKeyDepth,
        ReadOnlySpan<byte> selectedPrefixStem,
        VarKeyScalar8RouteMutationHint routeMutationHint)
    {
        if (splitKeyDepth == childRouterKeyDepth)
        {
            return VarKeyScalar8TransformRouterPlan.ExpandedOneByte;
        }

        int stemLength = splitKeyDepth - childRouterKeyDepth;
        bool hasStrongWriteHint = routeMutationHint.SampleCount >= 2 &&
            routeMutationHint.MaxCommonPrefixBytes >= VarKeyScalar8MultiByteRouterMinStemBytes;
        bool hasStrongColdEvidence = stemLength >= VarKeyScalar8MultiByteRouterMinStemBytes;
        if ((hasStrongColdEvidence || hasStrongWriteHint) &&
            stemLength < VarKeyScalar8MultiByteRouterMaxPrefixBytes &&
            selectedPrefixStem.Length == stemLength)
        {
            byte[] stem = selectedPrefixStem.ToArray();
            return VarKeyScalar8TransformRouterPlan.CompressedMultiByte(
                checked((byte)(stemLength + 1)),
                stem);
        }

        return VarKeyScalar8TransformRouterPlan.ExpandedOneByteChain;
    }

    private void RecordVarKeyScalar8RouteMutationHint(
        long parentRouterOffset,
        int routeIndex,
        VarKeyScalar8MutationHint mutationHint)
    {
        if (!mutationHint.Sampled || routeIndex < 0)
        {
            return;
        }

        VarKeyScalar8RouteHintKey key = new(parentRouterOffset, routeIndex);
        if (varKeyScalar8RouteMutationHints.TryGetValue(key, out VarKeyScalar8RouteMutationHint current))
        {
            varKeyScalar8RouteMutationHints[key] = new VarKeyScalar8RouteMutationHint(
                SampleCount: checked(current.SampleCount + 1),
                MaxCommonPrefixBytes: Math.Max(current.MaxCommonPrefixBytes, mutationHint.MaxCommonPrefixBytes),
                MaxCommonPrefixDepth: Math.Max(current.MaxCommonPrefixDepth, mutationHint.MaxCommonPrefixDepth));
            return;
        }

        varKeyScalar8RouteMutationHints[key] = new VarKeyScalar8RouteMutationHint(
            SampleCount: 1,
            MaxCommonPrefixBytes: mutationHint.MaxCommonPrefixBytes,
            MaxCommonPrefixDepth: mutationHint.MaxCommonPrefixDepth);
    }

    private VarKeyScalar8RouteMutationHint GetVarKeyScalar8RouteMutationHint(long parentRouterOffset, int routeIndex)
    {
        return routeIndex >= 0 &&
            varKeyScalar8RouteMutationHints.TryGetValue(new VarKeyScalar8RouteHintKey(parentRouterOffset, routeIndex), out VarKeyScalar8RouteMutationHint hint)
            ? hint
            : default;
    }

    /// <summary>
    /// Decides whether a `VS8` insert should collect common-prefix mutation evidence while rewriting a reached shelf.<br/>
    /// Default intent keeps the existing sparse sampling cadence; clustered intent samples every warmed shelf mutation so multi-byte router opportunities emerge quickly for hierarchical or repeated-token keys.<br/>
    /// </summary>
    /// <param name="shelfBytes">The reached shelf bytes before the incoming tuple is applied.</param>
    /// <returns>`true` when the insert path should collect mutation-hint evidence for this shelf rewrite.</returns>
    private bool ShouldSampleVarKeyScalar8MutationHint(ReadOnlySpan<byte> shelfBytes)
    {
        int itemCount = VarKeyScalar8Layout.ReadItemCount(shelfBytes);
        if (itemCount < VarKeyScalar8MutationHintWarmupItemCount)
        {
            return false;
        }

        if (currentWriteIntent.Locality == LibraDexWriteLocality.Clustered)
        {
            return true;
        }

        if (currentWriteIntent.Locality == LibraDexWriteLocality.Broad)
        {
            return (itemCount & VarKeyScalar8MutationHintSparseSampleMask) == 0;
        }

        if (currentWriteIntent.Order == LibraDexWriteOrder.Sorted &&
            currentWriteIntent.Priority != LibraDexWritePriority.Compactness)
        {
            return false;
        }

        if (currentWriteIntent.Priority == LibraDexWritePriority.WriteSpeed)
        {
            return (itemCount & VarKeyScalar8MutationHintSparseSampleMask) == 0;
        }

        return (itemCount & VarKeyScalar8MutationHintSampleMask) == 0;
    }

    /// <summary>
    /// Chooses the raw-key byte depth and right-side prefix boundary for a `VS8` transform split.<br/>
    /// The search starts at the router depth replacing the full shelf and advances until it finds a prefix transition near the median.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlots">The sorted source-slot map for existing tuples plus the incoming tuple.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="firstKeyDepth">The first raw-key byte depth the replacement router can own.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="maxKeyLength">The maximum supported raw-key length.</param>
    /// <returns>The selected raw-key byte depth and first right-side prefix byte.</returns>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar8TransformSplitPlan(
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<byte> incomingKey,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (keyOffsets.Length < 2 || keyOffsets.Length != keyLengths.Length)
        {
            throw new InvalidDataException("The VS8 transform split boundary requires at least two complete key descriptors.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar8TransformSplitRightPrefix(existingShelf.Bytes, keyOffsets, keyLengths, incomingKey, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The VS8 transform split path requires at least two distinct prefixes in the remaining raw key bytes.");
    }

    /// <summary>
    /// Chooses the right-side prefix byte for a `VS8` transform split from predecoded key-location arrays.<br/>
    /// This avoids repeated varint length decoding while preserving raw byte comparison semantics over the existing shelf image.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The authoritative byte image of the existing shelf.</param>
    /// <param name="keyOffsets">The sorted key-payload offsets for existing tuples, with negative values representing the incoming tuple.</param>
    /// <param name="keyLengths">The sorted key lengths matching <paramref name="keyOffsets"/>.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="keyDepth">The raw-key byte depth to evaluate.</param>
    /// <param name="hintRightPrefixByte">The incoming prefix byte at the initial child-router depth.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte.</param>
    /// <returns>`true` when the source range can be divided at <paramref name="keyDepth"/>.</returns>
    private static bool TryChooseVarKeyScalar8TransformSplitRightPrefix(
        byte[] existingShelfBytes,
        ReadOnlySpan<int> keyOffsets,
        ReadOnlySpan<int> keyLengths,
        ReadOnlySpan<byte> incomingKey,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = keyOffsets.Length / 2;
        for (int i = desiredRightStart; i < keyOffsets.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[i - 1], keyLengths[i - 1], incomingKey, keyDepth);
            byte rightPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[i], keyLengths[i], incomingKey, keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[i - 1], keyLengths[i - 1], incomingKey, keyDepth);
            byte rightPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[i], keyLengths[i], incomingKey, keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[0], keyLengths[0], incomingKey, keyDepth);
        byte lastPrefix = GetVarKeyScalar8SplitSourcePrefix(existingShelfBytes, keyOffsets[^1], keyLengths[^1], incomingKey, keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    /// <summary>
    /// Chooses the raw-key byte depth and right-side prefix boundary for a `VS8` transform split from source slots.<br/>
    /// This overload is retained for experiments that have a source-slot map but have not predecoded key payload locations.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlots">The sorted source-slot map for existing tuples plus the incoming tuple.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="firstKeyDepth">The first raw-key byte depth the replacement router can own.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="maxKeyLength">The maximum supported raw-key length.</param>
    /// <returns>The selected raw-key byte depth and first right-side prefix byte.</returns>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar8TransformSplitPlan(
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<int> sourceSlots,
        ReadOnlySpan<byte> incomingKey,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (sourceSlots.Length < 2)
        {
            throw new InvalidDataException("The VS8 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar8TransformSplitRightPrefix(existingShelf, sourceSlots, incomingKey, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The VS8 transform split path requires at least two distinct prefixes in the remaining raw key bytes.");
    }

    /// <summary>
    /// Chooses the right-side prefix byte for a `VS8` transform split from source slots instead of cloned key arrays.<br/>
    /// The search prefers a transition near the median and falls back to the incoming-prefix hint when it still divides the observed source range.<br/>
    /// </summary>
    /// <param name="existingShelf">The decoded mutable shelf that owns existing source slots.</param>
    /// <param name="sourceSlots">The sorted source-slot map for existing tuples plus the incoming tuple.</param>
    /// <param name="incomingKey">The incoming raw key bytes.</param>
    /// <param name="keyDepth">The raw-key byte depth to evaluate.</param>
    /// <param name="hintRightPrefixByte">The incoming prefix byte at the initial child-router depth.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte.</param>
    /// <returns>`true` when the source range can be divided at <paramref name="keyDepth"/>.</returns>
    private static bool TryChooseVarKeyScalar8TransformSplitRightPrefix(
        VarKeyScalar8MutableShelf existingShelf,
        ReadOnlySpan<int> sourceSlots,
        ReadOnlySpan<byte> incomingKey,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sourceSlots.Length / 2;
        for (int i = desiredRightStart; i < sourceSlots.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[i - 1], incomingKey), keyDepth);
            byte rightPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[i], incomingKey), keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[i - 1], incomingKey), keyDepth);
            byte rightPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[i], incomingKey), keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[0], incomingKey), keyDepth);
        byte lastPrefix = GetVarKeyScalar8Prefix(ReadVarKeyScalar8SplitSourceKey(existingShelf, sourceSlots[^1], incomingKey), keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    /// <summary>
    /// Chooses the raw-key byte depth and right-side prefix boundary for a `VS8` transform split from cloned key arrays.<br/>
    /// This overload is retained for older callers and shape bring-up tests that still construct a sorted raw-key array before splitting.<br/>
    /// </summary>
    /// <param name="sortedKeys">The complete sorted raw-key set for the full shelf plus incoming tuple.</param>
    /// <param name="firstKeyDepth">The first raw-key byte depth the replacement router can own.</param>
    /// <param name="hintRightPrefixByte">The incoming key prefix at <paramref name="firstKeyDepth"/>.</param>
    /// <param name="maxKeyLength">The maximum supported raw-key length.</param>
    /// <returns>The selected raw-key byte depth and first right-side prefix byte.</returns>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar8TransformSplitPlan(
        ReadOnlySpan<byte[]> sortedKeys,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (sortedKeys.Length < 2)
        {
            throw new InvalidDataException("The VS8 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar8TransformSplitRightPrefix(sortedKeys, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The VS8 transform split path requires at least two distinct prefixes in the remaining raw key bytes.");
    }

    private static bool TryChooseVarKeyScalar8TransformSplitRightPrefix(
        ReadOnlySpan<byte[]> sortedKeys,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKeys.Length / 2;
        for (int i = desiredRightStart; i < sortedKeys.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar8Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetVarKeyScalar8Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar8Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetVarKeyScalar8Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar8Prefix(sortedKeys[0], keyDepth);
        byte lastPrefix = GetVarKeyScalar8Prefix(sortedKeys[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    private static int CompareVarKeyScalar8Tuple(ReadOnlySpan<byte> leftKey, ulong leftIdentity, ReadOnlySpan<byte> rightKey, ulong rightIdentity)
    {
        int keyComparison = leftKey.SequenceCompareTo(rightKey);
        if (keyComparison != 0)
        {
            return keyComparison;
        }

        if (leftIdentity < rightIdentity)
        {
            return -1;
        }

        return leftIdentity > rightIdentity ? 1 : 0;
    }

    private static byte[] CreateVarKeyScalar16SplitPrefixStem(ReadOnlySpan<byte> representativeKey, ushort firstKeyDepth, ushort splitKeyDepth)
    {
        int stemLength = splitKeyDepth - firstKeyDepth;
        byte[] stem = new byte[stemLength];
        for (int i = 0; i < stem.Length; i++)
        {
            stem[i] = GetVarKeyScalar16Prefix(representativeKey, firstKeyDepth + i);
        }

        return stem;
    }

    private static VarKeyScalar16TransformRouterPlan ChooseVarKeyScalar16TransformRouterPlan(
        ushort childRouterKeyDepth,
        ushort splitKeyDepth,
        ReadOnlySpan<byte> selectedPrefixStem)
    {
        if (splitKeyDepth == childRouterKeyDepth)
        {
            return VarKeyScalar16TransformRouterPlan.ExpandedOneByte;
        }

        int stemLength = splitKeyDepth - childRouterKeyDepth;
        if (stemLength >= VarKeyScalar8MultiByteRouterMinStemBytes &&
            stemLength < VarKeyScalar8MultiByteRouterMaxPrefixBytes &&
            selectedPrefixStem.Length == stemLength)
        {
            byte[] stem = selectedPrefixStem.ToArray();
            return VarKeyScalar16TransformRouterPlan.CompressedMultiByte(
                checked((byte)(stemLength + 1)),
                stem);
        }

        return VarKeyScalar16TransformRouterPlan.ExpandedOneByteChain;
    }

    private static (ushort KeyDepth, byte RightPrefixByte) ChooseVarKeyScalar16TransformSplitPlan(
        ReadOnlySpan<byte[]> sortedKeys,
        ushort firstKeyDepth,
        byte hintRightPrefixByte,
        int maxKeyLength)
    {
        if (sortedKeys.Length < 2)
        {
            throw new InvalidDataException("The VS16 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < maxKeyLength; keyDepth++)
        {
            if (TryChooseVarKeyScalar16TransformSplitRightPrefix(sortedKeys, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The VS16 transform split path requires at least two distinct prefixes in the remaining raw key bytes.");
    }

    private static bool TryChooseVarKeyScalar16TransformSplitRightPrefix(
        ReadOnlySpan<byte[]> sortedKeys,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKeys.Length / 2;
        for (int i = desiredRightStart; i < sortedKeys.Length; i++)
        {
            byte leftPrefix = GetVarKeyScalar16Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetVarKeyScalar16Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetVarKeyScalar16Prefix(sortedKeys[i - 1], keyDepth);
            byte rightPrefix = GetVarKeyScalar16Prefix(sortedKeys[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetVarKeyScalar16Prefix(sortedKeys[0], keyDepth);
        byte lastPrefix = GetVarKeyScalar16Prefix(sortedKeys[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }

    private static int CompareVarKeyScalar16Tuple(
        ReadOnlySpan<byte> leftKey,
        ulong leftIdentityHigh,
        ulong leftIdentityLow,
        ReadOnlySpan<byte> rightKey,
        ulong rightIdentityHigh,
        ulong rightIdentityLow)
    {
        int keyComparison = leftKey.SequenceCompareTo(rightKey);
        if (keyComparison != 0)
        {
            return keyComparison;
        }

        if (leftIdentityHigh < rightIdentityHigh)
        {
            return -1;
        }

        if (leftIdentityHigh > rightIdentityHigh)
        {
            return 1;
        }

        if (leftIdentityLow < rightIdentityLow)
        {
            return -1;
        }

        return leftIdentityLow > rightIdentityLow ? 1 : 0;
    }

    /// <summary>
    /// Inserts one raw varlen key and encoded 8-byte identity through the routed `VS8` shelf path.<br/>
    /// No-split inserts rewrite the reached shelf extent; when the shelf is full but has a larger growth class, a larger shelf is appended and the parent route is repointed.<br/>
    /// This first routed slice deliberately stops at growth-before-split so varlen persistence, route repointing, and range reads can be measured before deeper split policy is added.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="key">The raw byte key to insert.</param>
    /// <param name="encodedIdentity">The encoded 8-byte identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.</param>
    /// <returns>The storage-facing routed insert result.</returns>
    internal VarKeyScalar8RoutedInsertResult InsertWalkedRoutedVarKeyScalar8(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        long routeWalkStart = Stopwatch.GetTimestamp();
        VarKeyScalar8RoutePathTarget pathTarget = WalkVarKeyScalar8RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        long routeWalkTicks = Stopwatch.GetTimestamp() - routeWalkStart;
        VarKeyScalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != VarKeyScalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at a VS8 shelf.");
        }

        long shelfReadStart = Stopwatch.GetTimestamp();
        VarKeyScalar8MutableShelf existingShelf = ReadVarKeyScalar8MutableShelf(target.Offset, maxKeyLength);
        VarKeyScalar8Profile profile = existingShelf.Profile;
        long shelfReadTicks = Stopwatch.GetTimestamp() - shelfReadStart;
        bool sampleMutationHint = ShouldSampleVarKeyScalar8MutationHint(existingShelf.Bytes);
        long mutationStart = Stopwatch.GetTimestamp();
        VarKeyScalar8InsertResult insertResult = existingShelf.InsertWithMutationHint(
            key,
            encodedIdentity,
            allowDuplicateKeys,
            hintStartDepth: target.RouterDepth,
            maxHintBytes: sampleMutationHint ? VarKeyScalar8MutationHintMaxBytes : 0,
            out VarKeyScalar8MutationHint mutationHint);
        long mutationTicks = Stopwatch.GetTimestamp() - mutationStart;
        if (insertResult == VarKeyScalar8InsertResult.Inserted)
        {
            long stageStart = Stopwatch.GetTimestamp();
            RecordVarKeyScalar8RouteMutationHint(pathTarget.ParentRouterOffset, pathTarget.RouteIndex, mutationHint);
            DataKernelCommitTelemetry telemetry = StageVarKeyScalar8ShelfRewrite(target.Offset, existingShelf);
            long stageTicks = Stopwatch.GetTimestamp() - stageStart;
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                telemetry,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, stageTicks, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar8InsertResult.AlreadyPresent)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar8InsertResult.KeyConflict)
        {
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                default,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        long structuralStart = Stopwatch.GetTimestamp();
        if (insertResult == VarKeyScalar8InsertResult.Full &&
            VarKeyScalar8.TryGrowAndInsert(existingShelf.Bytes, profile, key, encodedIdentity, allowDuplicateKeys, out VarKeyScalar8Profile grownProfile, out byte[] grownShelf, out VarKeyScalar8InsertResult grownResult))
        {
            if (grownResult != VarKeyScalar8InsertResult.Inserted)
            {
                long grownNoOpStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
                return new VarKeyScalar8RoutedInsertResult(
                    grownResult == VarKeyScalar8InsertResult.KeyConflict ? VarKeyScalar8RoutedInsertKind.KeyConflict : VarKeyScalar8RoutedInsertKind.NoOp,
                    grownResult,
                    target.Offset,
                    0,
                    default,
                    new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, grownNoOpStructuralTicks),
                    existingShelf.ItemCount,
                    profile.ShelfExtentSize,
                    target.RouterDepth);
            }

            varKeyScalar8MutableBatchShelves.Remove(target.Offset);
            RawDataReservation grownReservation = kernel.Reserve(grownProfile.ShelfExtentSize);
            grownShelf.CopyTo(grownReservation.Span);
            byte[] parentRouterBytes = new byte[RouterLayout.Size];
            kernel.Read(pathTarget.ParentRouterOffset, parentRouterBytes);
            RouterReader parentReader = new(parentRouterBytes);
            if (!parentReader.IsValid)
            {
                throw new InvalidDataException("The VS8 growth parent router is invalid.");
            }

            RawDataReservation parentRouterRewrite = kernel.ReserveAt(pathTarget.ParentRouterOffset, RouterLayout.Size);
            parentRouterBytes.CopyTo(parentRouterRewrite.Span);
            RouterWriter parentWriter = new(parentRouterRewrite.Span);
            parentWriter.WriteRouteTarget(pathTarget.RouteIndex, grownReservation.Extent.Offset);

            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            existingShelf.Release(clearShelfBytes: true);
            long growStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
            return new VarKeyScalar8RoutedInsertResult(
                VarKeyScalar8RoutedInsertKind.WalkedGrow,
                grownResult,
                target.Offset,
                grownReservation.Extent.Offset,
                telemetry,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, growStructuralTicks),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth);
        }

        if (insertResult == VarKeyScalar8InsertResult.Full)
        {
            ushort childRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
            byte rightPrefixByte = GetVarKeyScalar8Prefix(key, childRouterKeyDepth);
            VarKeyScalar8RouteMutationHint routeMutationHint = GetVarKeyScalar8RouteMutationHint(pathTarget.ParentRouterOffset, pathTarget.RouteIndex);
            varKeyScalar8MutableBatchShelves.Remove(target.Offset);
            (
                long childRouterOffset,
                long leftShelfOffset,
                long rightShelfOffset,
                _,
                _,
                VarKeyScalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedVarKeyScalar8ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                key,
                    encodedIdentity,
                    target.AllocationClassId,
                    childRouterKeyDepth,
                    routeMutationHint);
            existingShelf.Release(clearShelfBytes: true);

            VarKeyScalar8RoutedInsertKind kind = transformResult == VarKeyScalar8InsertResult.Inserted
                ? VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit
                : VarKeyScalar8RoutedInsertKind.NoOp;
            long transformStructuralTicks = Stopwatch.GetTimestamp() - structuralStart;
            return new VarKeyScalar8RoutedInsertResult(
                kind,
                transformResult,
                childRouterOffset,
                transformResult == VarKeyScalar8InsertResult.Inserted ? rightShelfOffset : leftShelfOffset,
                transformCommit,
                new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, transformStructuralTicks),
                existingShelf.ItemCount,
                profile.ShelfExtentSize,
                target.RouterDepth,
                childRouterKeyDepth);
        }

        return new VarKeyScalar8RoutedInsertResult(
            insertResult == VarKeyScalar8InsertResult.Invalid ? VarKeyScalar8RoutedInsertKind.Invalid : VarKeyScalar8RoutedInsertKind.Full,
            insertResult,
            target.Offset,
            0,
            default,
            new VarKeyScalar8WalkedWriteAttribution(routeWalkTicks, shelfReadTicks, mutationTicks, 0, 0),
            existingShelf.ItemCount,
            profile.ShelfExtentSize,
            target.RouterDepth);
    }

    /// <summary>
    /// Reads encoded identities for an inclusive raw-byte `VS8` key range across root-router prefixes.<br/>
    /// The reader enumerates the requested root-prefix span and recursively descends any transformed child routers created by full-shelf splits.<br/>
    /// Each distinct shelf reached by the route graph is scanned once, preserving the ordered-shelf range-scoop behavior while allowing varlen shelves to split beyond the first key byte.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="lowerKey">The inclusive lower raw key.</param>
    /// <param name="upperKey">The inclusive upper raw key.</param>
    /// <param name="encodedIdentities">The caller-owned output span that receives matching identities.</param>
    /// <returns>The number of identities copied.</returns>
    internal int ReadVarKeyScalar8IdentityRange(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        Span<ulong> encodedIdentities)
    {
        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            throw new ArgumentException("The upper VS8 key must be greater than or equal to the lower key.", nameof(upperKey));
        }

        byte lowerPrefix = GetVarKeyScalar8Prefix(lowerKey, 0);
        byte upperPrefix = GetVarKeyScalar8Prefix(upperKey, 0);
        int copied = 0;
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long shelfOffset = FindRouterTarget(rootRouterOffset, (byte)prefix);
            if (shelfOffset == 0)
            {
                continue;
            }

            copied = CopyVarKeyScalar8RangeFromTarget(
                shelfOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                encodedIdentities,
                copied,
                visitedShelves,
                visitedRouters,
                remainingRouterHops: DefaultVarKeyScalar8MaxRouterHops);
        }

        return copied;
    }

    /// <summary>
    /// Deletes encoded identities for an inclusive raw-byte `VS8` key range across the routed varlen-key tree.<br/>
    /// The traversal mirrors the range reader's target pruning, but shelf mutation uses the mutable sidecar view so active durability batches keep tombstones until commit-time slot normalization.<br/>
    /// Non-batch callers are also supported by normalizing the touched shelf before immediate publication, which preserves durable delete correctness without exposing tombstones in the persisted shelf format.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="lowerKey">The inclusive lower raw key.</param>
    /// <param name="upperKey">The inclusive upper raw key.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.</param>
    /// <returns>The number of live tuples deleted.</returns>
    internal long DeleteVarKeyScalar8KeyRange(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lowerKey,
        ReadOnlySpan<byte> upperKey,
        int maxRouterHops = DefaultVarKeyScalar8MaxRouterHops)
    {
        if (lowerKey.SequenceCompareTo(upperKey) > 0)
        {
            return 0;
        }

        byte lowerPrefix = GetVarKeyScalar8Prefix(lowerKey, 0);
        byte upperPrefix = GetVarKeyScalar8Prefix(upperKey, 0);
        long deleted = 0;
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        for (int prefix = lowerPrefix; prefix <= upperPrefix; prefix++)
        {
            long targetOffset = FindRouterTarget(rootRouterOffset, (byte)prefix);
            if (targetOffset == 0)
            {
                continue;
            }

            deleted += DeleteVarKeyScalar8RangeFromTarget(
                targetOffset,
                maxKeyLength,
                lowerKey,
                upperKey,
                visitedShelves,
                visitedRouters,
                maxRouterHops);
        }

        return deleted;
    }

    /// <summary>
    /// Deletes one exact raw-key and encoded-identity tuple from a routed `VS8` index.<br/>
    /// The route walk targets the shelf that owns the key bytes, then the mutable shelf sidecar marks only the matching tuple slot.<br/>
    /// Active durability batches retain the tombstone until commit-time normalization; non-batch callers normalize immediately before publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The root router offset for the index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the profile family.</param>
    /// <param name="key">The exact raw key bytes.</param>
    /// <param name="encodedIdentity">The exact encoded identity.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow.</param>
    /// <returns><see langword="true"/> when a live tuple was deleted.</returns>
    internal bool DeleteVarKeyScalar8ExactTuple(
        long rootRouterOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> key,
        ulong encodedIdentity,
        int maxRouterHops = DefaultVarKeyScalar8MaxRouterHops)
    {
        VarKeyScalar8RoutePathTarget pathTarget = WalkVarKeyScalar8RoutePathTarget(rootRouterOffset, key, maxRouterHops);
        VarKeyScalar8RouteTarget target = pathTarget.Target;
        if (target.Kind != VarKeyScalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at a VS8 shelf for exact tuple delete.");
        }

        VarKeyScalar8MutableShelf shelf = ReadVarKeyScalar8MutableShelf(target.Offset, maxKeyLength);
        if (!shelf.MarkTupleDeleted(key, encodedIdentity))
        {
            return false;
        }

        if (!durabilityBatchActive)
        {
            _ = shelf.NormalizeDeletedSlotsForPublication();
        }

        _ = StageVarKeyScalar8ShelfRewrite(target.Offset, shelf);
        return true;
    }

