    private byte[] ReadVarKeyScalar8ShelfBytes(long shelfOffset, int maxKeyLength, out VarKeyScalar8Profile profile)
    {
        if (durabilityBatchActive &&
            varKeyScalar8MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar8MutableShelf? mutableShelf))
        {
            profile = mutableShelf.Profile;
            return mutableShelf.Bytes;
        }

        if (!durabilityBatchActive &&
            varKeyScalar8ReadShelfCache.TryGetValue(shelfOffset, out byte[]? cachedShelfBytes))
        {
            int cachedShelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(cachedShelfBytes);
            profile = VarKeyScalar8Profile.Create(cachedShelfExtentSize, maxKeyLength);
            VarKeyScalar8ReadOnly cachedShelf = new(cachedShelfBytes, profile);
            if (!cachedShelf.IsValid)
            {
                throw new InvalidDataException("The session-local VS8 read shelf cache contained invalid shelf bytes.");
            }

            return cachedShelfBytes;
        }

        byte[] header = new byte[VarKeyScalar8Layout.HeaderSize];
        kernel.Read(shelfOffset, header);
        if (VarKeyScalar8Layout.ReadMagic(header) != VarKeyScalar8Layout.Magic ||
            VarKeyScalar8Layout.ReadFormatVersion(header) != VarKeyScalar8Layout.FormatVersion ||
            VarKeyScalar8Layout.ReadHeaderSize(header) != VarKeyScalar8Layout.HeaderSize)
        {
            throw new InvalidDataException("The routed VS8 shelf header is invalid.");
        }

        int shelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(header);
        profile = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
        byte[] shelfBytes = new byte[shelfExtentSize];
        header.CopyTo(shelfBytes.AsSpan(0, header.Length));
        kernel.Read(shelfOffset, shelfBytes);
        if (!durabilityBatchActive)
        {
            varKeyScalar8ReadShelfCache[shelfOffset] = shelfBytes;
        }

        return shelfBytes;
    }

