    /// <summary>
    /// Reads one `VS8` shelf as a session-owned mutable view, reusing any dirty batch view already decoded for this shelf offset.<br/>
    /// The mutable view keeps the persisted byte image authoritative while caching decoded slot offsets and prefixes for repeated inserts into the same shelf.<br/>
    /// During a durability batch the view is retained immediately so subsequent mutations avoid repeat shelf validation and slot decoding; non-batch callers receive a temporary view.<br/>
    /// </summary>
    /// <param name="shelfOffset">The file offset of the shelf to read.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the caller's `VS8` profile family.</param>
    /// <returns>The mutable shelf view for this session operation.</returns>
    /// <exception cref="InvalidDataException">Thrown when the loaded shelf bytes fail `VS8` validation.</exception>
    private VarKeyScalar8MutableShelf ReadVarKeyScalar8MutableShelf(long shelfOffset, int maxKeyLength)
    {
        if (durabilityBatchActive &&
            varKeyScalar8MutableBatchShelves.TryGetValue(shelfOffset, out VarKeyScalar8MutableShelf? mutableShelf))
        {
            return mutableShelf;
        }

        byte[] shelfBytes;
        VarKeyScalar8Profile profile;
        bool ownsBytes = false;
        bool rentSidecars = durabilityBatchActive;
        if (durabilityBatchActive)
        {
            Span<byte> header = stackalloc byte[VarKeyScalar8Layout.HeaderSize];
            kernel.Read(shelfOffset, header);
            if (VarKeyScalar8Layout.ReadMagic(header) != VarKeyScalar8Layout.Magic ||
                VarKeyScalar8Layout.ReadFormatVersion(header) != VarKeyScalar8Layout.FormatVersion ||
                VarKeyScalar8Layout.ReadHeaderSize(header) != VarKeyScalar8Layout.HeaderSize)
            {
                throw new InvalidDataException("The routed VS8 shelf header is invalid.");
            }

            int shelfExtentSize = VarKeyScalar8Layout.ReadShelfExtentSize(header);
            profile = VarKeyScalar8Profile.Create(shelfExtentSize, maxKeyLength);
            shelfBytes = ArrayPool<byte>.Shared.Rent(shelfExtentSize);
            ownsBytes = true;
            kernel.Read(shelfOffset, shelfBytes.AsSpan(0, shelfExtentSize));
        }
        else
        {
            shelfBytes = ReadVarKeyScalar8ShelfBytes(shelfOffset, maxKeyLength, out profile);
        }

        if (!VarKeyScalar8MutableShelf.TryCreate(shelfBytes, profile, ownsBytes, rentSidecars, out VarKeyScalar8MutableShelf shelf))
        {
            throw new InvalidDataException("The routed VS8 mutable shelf bytes are invalid.");
        }

        if (durabilityBatchActive)
        {
            varKeyScalar8MutableBatchShelves[shelfOffset] = shelf;
        }

        return shelf;
    }

