    /// <summary>
    /// Flushes dirty `SV8` mutable batch shelves into DataKernel staging before the durability batch publishes.<br/>
    /// Each shelf is copied once regardless of how many in-place inserts touched it during the batch.<br/>
    /// </summary>
    private void FlushDirtyScalar8VarIdentityMutableBatchShelves()
    {
        foreach (KeyValuePair<long, Scalar8VarIdentityMutableShelfView> mutableShelf in scalar8VarIdentityMutableBatchShelves)
