    /// <summary>
    /// Releases session-owned `SV8` mutable batch shelf buffers.<br/>
    /// The first implementation uses ordinary arrays, but clearing on release keeps the lifecycle aligned with pooled varlen shelves.<br/>
    /// </summary>
    /// <param name="clearShelfBytes">Whether to clear shelf bytes before dropping references.</param>
    private void ReleaseScalar8VarIdentityMutableBatchShelves(bool clearShelfBytes)
    {
        if (clearShelfBytes)
        {
            foreach (Scalar8VarIdentityMutableShelfView mutableShelf in scalar8VarIdentityMutableBatchShelves.Values)
            {
                mutableShelf.Bytes.AsSpan(0, mutableShelf.Profile.ShelfExtentSize).Clear();
            }
        }

        scalar8VarIdentityMutableBatchShelves.Clear();
    }

    /// <summary>
    /// Releases session-owned `SV16` mutable batch shelf buffers.<br/>
    /// The first implementation mirrors the `SV8` array-backed lifecycle so commit and abort behavior stay symmetric across reverse-varlen shapes.<br/>
    /// </summary>
    /// <param name="clearShelfBytes">Whether to clear shelf bytes before dropping references.</param>
    private void ReleaseScalar16VarIdentityMutableBatchShelves(bool clearShelfBytes)
    {
        if (clearShelfBytes)
        {
            foreach (Scalar16VarIdentityMutableShelfView mutableShelf in scalar16VarIdentityMutableBatchShelves.Values)
            {
                mutableShelf.Bytes.AsSpan(0, mutableShelf.Profile.ShelfExtentSize).Clear();
            }
        }

        scalar16VarIdentityMutableBatchShelves.Clear();
    }

    /// <summary>
    /// Holds one mutable, disk-shaped `SV8` shelf image during a session durability batch.<br/>
    /// The byte array remains authoritative; this deliberately narrow sidecar tracks only profile and dirty state because `Scalar8VarIdentityReadOnly` already decodes slot sidecars for classification.<br/>
    /// </summary>
    private sealed class Scalar8VarIdentityMutableBatchShelf
    {
        /// <summary>
        /// Initializes a mutable `SV8` batch shelf wrapper.<br/>
        /// The caller owns validation before construction and controls when the image is flushed to DataKernel staging.<br/>
        /// </summary>
        /// <param name="bytes">The mutable shelf bytes.</param>
        /// <param name="profile">The profile matching the shelf bytes.</param>
        public Scalar8VarIdentityMutableBatchShelf(byte[] bytes, Scalar8VarIdentityProfile profile)
        {
            Bytes = bytes;
            Profile = profile;
        }

        /// <summary>
        /// Gets the mutable, disk-shaped shelf byte image.<br/>
        /// Insert paths mutate this buffer directly and batch commit copies it once when dirty.<br/>
        /// </summary>
        public byte[] Bytes { get; }

        /// <summary>
        /// Gets the shelf profile used to validate extent size and maximum identity length.<br/>
        /// </summary>
        public Scalar8VarIdentityProfile Profile { get; }

        /// <summary>
        /// Gets whether the shelf image has changed since it was loaded into the durability batch.<br/>
        /// </summary>
        public bool IsDirty { get; private set; }

        /// <summary>
        /// Marks the shelf image dirty so batch commit flushes it once.<br/>
        /// </summary>
        public void MarkDirty()
        {
            IsDirty = true;
        }
    }

    /// <summary>
    /// Reads a 4 KiB router page, preferring the session router-arena cache when the page belongs to a known arena.<br/>
    /// Whole-arena first-touch loading is intentionally limited to arena page zero so non-entry router pages do not pay a 32 KiB prefetch cost for one-off access.<br/>
    /// </summary>
    /// <param name="routerOffset">The router page file offset.</param>
    /// <param name="destination">The 4 KiB destination buffer that receives the router page.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly one router page.</exception>
    internal void ReadRouterPageUsingArenaCache(long routerOffset, Span<byte> destination)
    {
        if (destination.Length != RouterLayout.Size)
        {
            throw new ArgumentException("Router arena reads require a destination exactly one router page in length.", nameof(destination));
        }

        if (TryReadFromRouterArenaCache(routerOffset, destination))
        {
            return;
        }

        if (routerPageReadCache.TryGetValue(routerOffset, out byte[]? cachedRouterPage))
        {
            cachedRouterPage.CopyTo(destination);
            return;
        }

        kernel.Read(routerOffset, destination);
        RouterReader reader = new(destination);
        if (!reader.IsValid || !reader.IsArenaMember)
        {
            routerPageReadCache[routerOffset] = destination.ToArray();
            return;
        }

        long arenaBaseOffset = checked(routerOffset + reader.ArenaBaseDelta);
        int arenaLength = reader.ArenaLength;
        if (arenaLength <= RouterLayout.Size)
        {
            return;
        }

        LoadRouterArenaReadCache(arenaBaseOffset, arenaLength);
        RegisterRouterArenaFromCachedBytes(arenaBaseOffset, arenaLength);
        _ = routerArenaReadCache.TryCopy(routerOffset, destination);
    }

    /// <summary>
    /// Classifies a route target while allowing router-arena cached bytes to satisfy router magic reads.<br/>
    /// Shelf targets still use the normal four-byte `DataKernel` read unless they happen to overlap a cached router arena, which should not occur for valid structures.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `SS8-8` shelf magic value.</exception>
    private Scalar8Scalar8RouteTargetKind ClassifyScalar8Scalar8RouteTargetUsingArenaCache(long targetOffset)
    {
        if (targetOffset == 0)
        {
            return Scalar8Scalar8RouteTargetKind.None;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        if (!TryReadFromRouterArenaCache(targetOffset, magicBytes))
        {
            kernel.Read(targetOffset, magicBytes);
        }

        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            return Scalar8Scalar8RouteTargetKind.Router;
        }

        if (magic == Scalar8Scalar8Layout.Magic)
        {
            return Scalar8Scalar8RouteTargetKind.Shelf;
        }

        throw new InvalidDataException($"Route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }

    /// <summary>
    /// Attempts to satisfy a byte read from the current router-arena cache or from a session-registered router arena.<br/>
    /// A registered arena hit loads the whole arena only when the requested range starts at arena page zero; non-entry pages use normal reads unless the arena is already cached.<br/>
    /// </summary>
    /// <param name="offset">The file offset to read.</param>
    /// <param name="destination">The destination span that receives the requested bytes.</param>
    /// <returns>True when the read was served from the router-arena cache path; otherwise false.</returns>
    private bool TryReadFromRouterArenaCache(long offset, Span<byte> destination)
    {
        if (destination.Length == 0)
        {
            return true;
        }

        if (routerArenaReadCache.TryCopy(offset, destination))
        {
            return true;
        }

        RouterArenaState? arena = FindContainingRouterArena(offset, destination.Length);
        if (arena is null)
        {
            return false;
        }

        LoadRouterArenaReadCache(arena.BaseOffset, arena.Length);
        return routerArenaReadCache.TryCopy(offset, destination);
    }

    /// <summary>
    /// Loads one full router micro-arena into the session's single-entry read cache.<br/>
    /// Loading the same arena repeatedly is avoided so repeated reads within an arena do not create extra backing reads.<br/>
    /// </summary>
    /// <param name="arenaBaseOffset">The file offset where the arena starts.</param>
    /// <param name="arenaLength">The full arena byte length.</param>
    private void LoadRouterArenaReadCache(long arenaBaseOffset, int arenaLength)
    {
        if (routerArenaReadCache.Contains(arenaBaseOffset, arenaLength))
        {
            return;
        }

        byte[] arenaBytes = new byte[arenaLength];
        kernel.Read(arenaBaseOffset, arenaBytes);
        routerArenaReadCache.Store(arenaBaseOffset, arenaBytes, arenaLength, RouterArenaReadCacheMaxBytes);
    }

    /// <summary>
    /// Registers a persisted router arena discovered from one member router and marks pages that already contain router magic.<br/>
    /// This lets a reopened session recover the reusable-page map from contiguous arena bytes without relying on in-memory state from the writer session.<br/>
    /// </summary>
    /// <param name="arenaBaseOffset">The file offset where the arena starts.</param>
    /// <param name="arenaLength">The full arena byte length.</param>
    private void RegisterRouterArenaFromCachedBytes(long arenaBaseOffset, int arenaLength)
    {
        RouterArenaState arena = RegisterRouterArena(arenaBaseOffset, arenaLength);
        int pageCount = arenaLength / RouterLayout.Size;
        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        for (int pageIndex = 0; pageIndex < pageCount; pageIndex++)
        {
            long pageOffset = arenaBaseOffset + ((long)pageIndex * RouterLayout.Size);
            if (!routerArenaReadCache.TryCopy(pageOffset, magicBytes))
            {
                continue;
            }

            if (BinaryPrimitives.ReadUInt32LittleEndian(magicBytes) == RouterLayout.Magic)
            {
                arena.MarkUsed(pageIndex);
            }
        }
    }

    /// <summary>
    /// Registers a router micro-arena in the current file session or returns the existing registry entry.<br/>
    /// This first allocator registry is session-local and intentionally avoids becoming a general persisted free-space manager.<br/>
    /// </summary>
    /// <param name="baseOffset">The arena base file offset.</param>
    /// <param name="length">The arena byte length.</param>
    /// <returns>The mutable session-local arena state.</returns>
    private RouterArenaState RegisterRouterArena(long baseOffset, int length)
    {
        RouterArenaState? existing = FindRouterArena(baseOffset);
        if (existing is not null)
        {
            return existing;
        }

        RouterArenaState arena = new(baseOffset, length, RouterLayout.Size);
        routerArenas.Add(arena);
        return arena;
    }

    /// <summary>
    /// Finds a session-local router arena by base offset.<br/>
    /// </summary>
    /// <param name="baseOffset">The arena base file offset.</param>
    /// <returns>The matching arena state, or null when not registered.</returns>
    private RouterArenaState? FindRouterArena(long baseOffset)
    {
        for (int i = 0; i < routerArenas.Count; i++)
        {
            RouterArenaState arena = routerArenas[i];
            if (arena.BaseOffset == baseOffset)
            {
                return arena;
            }
        }

        return null;
    }

    /// <summary>
    /// Finds the first session-local router arena with at least one free router page.<br/>
    /// </summary>
    /// <returns>An arena with free capacity, or null when every known arena is full.</returns>
    private RouterArenaState? FindAnyRouterArenaWithFreePage()
    {
        for (int i = 0; i < routerArenas.Count; i++)
        {
            RouterArenaState arena = routerArenas[i];
            if (arena.TryFindFreePage(out _))
            {
                return arena;
            }
        }

        return null;
    }

    /// <summary>
    /// Finds the first registered router arena that fully contains the requested byte range.<br/>
    /// This is used as a cheap session-local hint before falling back to persisted arena metadata discovery.<br/>
    /// </summary>
    /// <param name="offset">The starting file offset of the requested range.</param>
    /// <param name="length">The requested byte count.</param>
    /// <returns>The containing router arena, or null when the range is outside known arenas.</returns>
    private RouterArenaState? FindContainingRouterArena(long offset, int length)
    {
        long endOffset = checked(offset + length);
        for (int i = 0; i < routerArenas.Count; i++)
        {
            RouterArenaState arena = routerArenas[i];
            long arenaEndOffset = checked(arena.BaseOffset + arena.Length);
            if (offset >= arena.BaseOffset && endOffset <= arenaEndOffset)
            {
                return arena;
            }
        }

        return null;
    }

    /// <summary>
    /// Returns and resets the session's accumulated DataKernel read telemetry.<br/>
    /// This is a validation hook so routed integration tests can assert read-call and byte shape without exposing the DataKernel itself.<br/>
    /// </summary>
    /// <returns>The accumulated read telemetry since the previous reset.</returns>
    public DataKernelReadTelemetry GetAndResetReadTelemetry()
    {
        return kernel.GetAndResetReadTelemetry();
    }

    /// <summary>
    /// Clears the session router-arena read cache for validation and benchmark isolation.<br/>
    /// Production mutation paths clear this cache structurally through commits; this hook exists so harness scenarios can start from a known cold-cache state without creating a new file session.<br/>
    /// </summary>
    internal void ClearRouterArenaReadCacheForValidation()
    {
        ClearRouterReadCaches();
    }

    /// <summary>
    /// Returns the current router-arena read-cache size for validation and benchmark diagnostics.<br/>
    /// The values are session-local and are not durable format state.<br/>
    /// </summary>
    /// <returns>The number of cached router arenas and the total cached bytes.</returns>
    internal (int ArenaCount, long CachedBytes) GetRouterArenaReadCacheStatsForValidation()
    {
        return (routerArenaReadCache.Count, routerArenaReadCache.CachedBytes);
    }

    /// <summary>
    /// Clears all session-local router read projections.<br/>
    /// Promoted router RAM offsets are session-local accelerators, so structural commits and validation resets invalidate them together with cached router bytes.<br/>
    /// </summary>
    private void ClearRouterReadCaches()
    {
        routerArenaReadCache.Clear();
        routerPageReadCache.Clear();
        directRouterViewCache.Clear();
        nonDirectRouterViewOffsets.Clear();
        multiByteRouterViewCache.Clear();
        promotedRouterArena.Clear();
        scalar8Scalar8CleanShelfCache.Clear();
        varKeyScalar8ReadShelfCache.Clear();
        varKeyScalar16ReadShelfCache.Clear();
        varKeyVarIdentityReadShelfCache.Clear();
        varKeyVarIdentityReadOnlyShelfCache.Clear();
        varKeyScalar8RouteTargetKindCache.Clear();
        varKeyScalar16RouteTargetKindCache.Clear();
        varKeyVarIdentityRouteTargetKindCache.Clear();
    }

    public void Dispose()
    {
        if (disposed)
        {
            return;
        }

        disposed = true;
        ReleaseVarKeyScalar8MutableBatchShelves(clearShelfBytes: true);
        ReleaseVarKeyScalar16MutableBatchShelves(clearShelfBytes: true);
        ReleaseVarKeyVarIdentityMutableBatchShelves(clearShelfBytes: true);
        varKeyScalar8RouteTargetKindCache.Dispose();
        varKeyScalar16RouteTargetKindCache.Dispose();
        varKeyVarIdentityRouteTargetKindCache.Dispose();
        ArrayPool<byte>.Shared.Return(varKeyScalar8RouteWalkRouterScratch, clearArray: false);
        ArrayPool<byte>.Shared.Return(varKeyScalar16RouteWalkRouterScratch, clearArray: false);
        kernel.Dispose();
    }

    private sealed class RouterArenaState
    {
        private readonly bool[] usedPages;

        public RouterArenaState(long baseOffset, int length, int pageSize)
        {
            if (length <= 0 || pageSize <= 0 || length % pageSize != 0)
            {
                throw new ArgumentOutOfRangeException(nameof(length), length, "Router arena length must be a positive multiple of page size.");
            }

            BaseOffset = baseOffset;
            Length = length;
            PageSize = pageSize;
            PageCount = length / pageSize;
            usedPages = new bool[PageCount];
        }

        public long BaseOffset { get; }

        public int Length { get; }

        public int PageSize { get; }

        public int PageCount { get; }

        public bool TryFindFreePage(out int pageIndex)
        {
            for (int i = 0; i < usedPages.Length; i++)
            {
                if (!usedPages[i])
                {
                    pageIndex = i;
                    return true;
                }
            }

            pageIndex = -1;
            return false;
        }

        public void MarkUsed(int pageIndex)
        {
            if ((uint)pageIndex >= (uint)usedPages.Length)
            {
                throw new ArgumentOutOfRangeException(nameof(pageIndex), pageIndex, "Router arena page index is outside the arena.");
            }

            usedPages[pageIndex] = true;
        }
    }

    private sealed class RouterArenaReadCache
    {
        private readonly Dictionary<long, Entry> entriesByBaseOffset = [];
        private long cachedBytes;

        public int Count => entriesByBaseOffset.Count;

        public long CachedBytes => cachedBytes;

        /// <summary>
        /// Returns whether the cache currently contains exactly the supplied arena extent.<br/>
        /// Multiple transformed shelves can contribute router arenas to one range read, so the cache keeps every discovered arena until session invalidation.<br/>
        /// </summary>
        /// <param name="arenaBaseOffset">The arena base file offset.</param>
        /// <param name="arenaLength">The arena byte length.</param>
        /// <returns>True when the current cache entry matches the supplied extent.</returns>
        public bool Contains(long arenaBaseOffset, int arenaLength)
        {
            return entriesByBaseOffset.TryGetValue(arenaBaseOffset, out Entry? entry) &&
                entry.Length == arenaLength;
        }

        /// <summary>
        /// Stores one full router arena as a session-local read cache entry.<br/>
        /// Ownership of <paramref name="arenaBytes"/> transfers to the cache so callers should not mutate the array after storing it.<br/>
        /// </summary>
        /// <param name="arenaBaseOffset">The arena base file offset.</param>
        /// <param name="arenaBytes">The full arena bytes.</param>
        /// <param name="arenaLength">The valid byte length inside <paramref name="arenaBytes"/>.</param>
        public void Store(long arenaBaseOffset, byte[] arenaBytes, int arenaLength, long maxCachedBytes)
        {
            if (arenaLength > maxCachedBytes)
            {
                return;
            }

            if (entriesByBaseOffset.TryGetValue(arenaBaseOffset, out Entry? existing))
            {
                cachedBytes -= existing.Length;
            }

            if (cachedBytes + arenaLength > maxCachedBytes)
            {
                Clear();
            }

            entriesByBaseOffset[arenaBaseOffset] = new Entry(arenaBaseOffset, arenaBytes, arenaLength);
            cachedBytes += arenaLength;
        }

        /// <summary>
        /// Attempts to copy a requested byte range from any cached router arena.<br/>
        /// The method returns false when no cached arena fully contains the requested range.<br/>
        /// </summary>
        /// <param name="offset">The requested file offset.</param>
        /// <param name="destination">The destination span that receives cached bytes.</param>
        /// <returns>True when bytes were copied from the cache; otherwise false.</returns>
        public bool TryCopy(long offset, Span<byte> destination)
        {
            foreach (Entry entry in entriesByBaseOffset.Values)
            {
                if (entry.TryCopy(offset, destination))
                {
                    return true;
                }
            }

            return false;
        }

        /// <summary>
        /// Clears all current cache entries.<br/>
        /// Session commits call this conservatively so later reads cannot observe stale router bytes after structural mutation.<br/>
        /// </summary>
        public void Clear()
        {
            entriesByBaseOffset.Clear();
            cachedBytes = 0;
        }

        private sealed class Entry
        {
            private readonly byte[] bytes;
            private readonly long baseOffset;

            public Entry(long baseOffset, byte[] bytes, int length)
            {
                this.baseOffset = baseOffset;
                this.bytes = bytes;
                Length = length;
            }

            public int Length { get; }

            public bool TryCopy(long offset, Span<byte> destination)
            {
                long relativeOffset = offset - baseOffset;
                if (relativeOffset < 0 || relativeOffset > int.MaxValue)
                {
                    return false;
                }

                int start = (int)relativeOffset;
                if (start > Length || destination.Length > Length - start)
                {
                    return false;
                }

                bytes.AsSpan(start, destination.Length).CopyTo(destination);
                return true;
            }
        }
    }

    private sealed class DirectRouterView
    {
        private readonly long[] targetOffsets;
        private readonly Scalar8Scalar8RouteTargetKind[] targetKinds;
        private readonly uint[] targetRouterRamOffsets;

        internal DirectRouterView(long fileOffset, ushort keyDepth, ushort allocationClassId, long[] targetOffsets)
        {
            FileOffset = fileOffset;
            KeyDepth = keyDepth;
            AllocationClassId = allocationClassId;
            this.targetOffsets = targetOffsets;
            targetKinds = new Scalar8Scalar8RouteTargetKind[targetOffsets.Length];
            targetRouterRamOffsets = new uint[targetOffsets.Length];
        }

        internal long FileOffset { get; }

        internal uint RamOffset { get; set; }

        internal ushort KeyDepth { get; }

        internal ushort AllocationClassId { get; }

        /// <summary>
        /// Gets the durable file target offset for one direct route prefix.<br/>
        /// This offset remains the authoritative route identity across reopen and structural invalidation boundaries.<br/>
        /// </summary>
        /// <param name="prefixByte">The direct route prefix byte.</param>
        /// <returns>The durable file target offset, or zero when the route is unset.</returns>
        internal long GetTarget(byte prefixByte)
        {
            return targetOffsets[prefixByte];
        }

        /// <summary>
        /// Gets the cached classified target kind for one direct route prefix.<br/>
        /// `None` means the session has not classified the durable target offset yet or the route is unset.<br/>
        /// </summary>
        /// <param name="prefixByte">The direct route prefix byte.</param>
        /// <returns>The cached target kind for the route entry.</returns>
        internal Scalar8Scalar8RouteTargetKind GetTargetKind(byte prefixByte)
        {
            return targetKinds[prefixByte];
        }

        /// <summary>
        /// Stores the classified target kind for one direct route prefix.<br/>
        /// This is a session-local accelerator and is discarded whenever router read projections are invalidated.<br/>
        /// </summary>
        /// <param name="prefixByte">The direct route prefix byte.</param>
        /// <param name="kind">The classified route target kind.</param>
        internal void SetTargetKind(byte prefixByte, Scalar8Scalar8RouteTargetKind kind)
        {
            targetKinds[prefixByte] = kind;
        }

        /// <summary>
        /// Gets the cached promoted-router RAM offset for one direct route prefix.<br/>
        /// Offset zero means the target is not a promoted child router or has not been promoted in the current session.<br/>
        /// </summary>
        /// <param name="prefixByte">The direct route prefix byte.</param>
        /// <returns>The session-local promoted-router RAM offset.</returns>
        internal uint GetTargetRouterRamOffset(byte prefixByte)
        {
            return targetRouterRamOffsets[prefixByte];
        }

        /// <summary>
        /// Stores the promoted child-router RAM offset for one direct route prefix.<br/>
        /// The durable file offset stays unchanged; this value only shortcuts child-router projection during the current session.<br/>
        /// </summary>
        /// <param name="prefixByte">The direct route prefix byte.</param>
        /// <param name="ramOffset">The session-local promoted-router RAM offset.</param>
        internal void SetTargetRouterRamOffset(byte prefixByte, uint ramOffset)
        {
            targetRouterRamOffsets[prefixByte] = ramOffset;
        }
    }

    private sealed class MultiByteRouterView
    {
        private readonly byte[] stems;
        private readonly byte[] prefixStarts;
        private readonly byte[] prefixEnds;
        private readonly long[] targetOffsets;
        private readonly PromotedRouteTargetKind[] targetKinds;
        private readonly int stemLength;

        internal MultiByteRouterView(
            long fileOffset,
            ushort keyDepth,
            ushort allocationClassId,
            int prefixByteCount,
            byte[] stems,
            byte[] prefixStarts,
            byte[] prefixEnds,
            long[] targetOffsets,
            PromotedRouteTargetKind[] targetKinds)
        {
            FileOffset = fileOffset;
            KeyDepth = keyDepth;
            AllocationClassId = allocationClassId;
            PrefixByteCount = prefixByteCount;
            this.stems = stems;
            this.prefixStarts = prefixStarts;
            this.prefixEnds = prefixEnds;
            this.targetOffsets = targetOffsets;
            this.targetKinds = targetKinds;
            stemLength = prefixByteCount - 1;
        }

        internal long FileOffset { get; }

        internal ushort KeyDepth { get; }

        internal ushort AllocationClassId { get; }

        internal int PrefixByteCount { get; }

        /// <summary>
        /// Finds the target offset for one raw-key route through the promoted compressed multi-byte router.<br/>
        /// The method compares the persisted stem bytes and final route byte directly from decoded arrays, avoiding a router-page read and RouterReader reconstruction on repeated walked writes.<br/>
        /// </summary>
        /// <param name="key">The raw key being routed.</param>
        /// <param name="routeIndex">The selected route index, or `-1` when no route matches.</param>
        /// <returns>The target offset for the matched route, or zero when no route matches.</returns>
        internal long FindTarget(ReadOnlySpan<byte> key, out int routeIndex)
        {
            byte finalByte = GetVarKeyScalar8Prefix(key, KeyDepth + stemLength);
            for (int i = 0; i < targetOffsets.Length; i++)
            {
                if (!StemMatchesKey(i, key))
                {
                    continue;
                }

                if (finalByte >= prefixStarts[i] && finalByte <= prefixEnds[i])
                {
                    routeIndex = i;
                    return targetOffsets[i];
                }
            }

            routeIndex = -1;
            return 0;
        }

        /// <summary>
        /// Gets the cached classified route target kind for one promoted multi-byte route entry.<br/>
        /// `None` means the target has not been classified yet or the route is unset.<br/>
        /// </summary>
        /// <param name="routeIndex">The selected route index.</param>
        /// <returns>The cached target kind.</returns>
        internal PromotedRouteTargetKind GetTargetKind(int routeIndex)
        {
            return targetKinds[routeIndex];
        }

        /// <summary>
        /// Stores the classified route target kind for one promoted multi-byte route entry.<br/>
        /// This avoids repeated route-target magic classification for stable compressed router routes during walked writes.<br/>
        /// </summary>
        /// <param name="routeIndex">The selected route index.</param>
        /// <param name="kind">The classified target kind.</param>
        internal void SetTargetKind(int routeIndex, PromotedRouteTargetKind kind)
        {
            targetKinds[routeIndex] = kind;
        }

        private bool StemMatchesKey(int routeIndex, ReadOnlySpan<byte> key)
        {
            int stemOffset = routeIndex * stemLength;
            for (int i = 0; i < stemLength; i++)
            {
                if (stems[stemOffset + i] != GetVarKeyScalar8Prefix(key, KeyDepth + i))
                {
                    return false;
                }
            }

            return true;
        }
    }

    private sealed class PromotedRouterArena
    {
        private const uint RecordSize = RouterLayout.MaxOneByteRouteCount * 16;
        private uint nextOffset = RecordSize;
        private readonly Dictionary<uint, DirectRouterView> viewsByOffset = [];

        /// <summary>
        /// Adds a promoted direct-router view and returns its session-local logical RAM offset.<br/>
        /// Offset zero is reserved as "no promoted router"; real offsets advance by a fixed logical record size so they can later map to byte slabs without changing route-entry width.<br/>
        /// </summary>
        /// <param name="view">The promoted router view to register.</param>
        /// <returns>The session-local logical RAM offset for <paramref name="view"/>.</returns>
        /// <exception cref="InvalidOperationException">Thrown when the 4-byte logical arena is exhausted.</exception>
        internal uint Add(DirectRouterView view)
        {
            uint offset = nextOffset;
            if (uint.MaxValue - nextOffset < RecordSize)
            {
                throw new InvalidOperationException("The promoted router arena exhausted its 4-byte logical offset space.");
            }

            nextOffset += RecordSize;
            viewsByOffset.Add(offset, view);
            return offset;
        }

        /// <summary>
        /// Attempts to resolve a promoted direct-router view by its session-local logical RAM offset.<br/>
        /// The implementation currently maps offsets to managed views, while the method boundary preserves the future option to project records from contiguous or segmented byte slabs.<br/>
        /// </summary>
        /// <param name="ramOffset">The session-local logical RAM offset.</param>
        /// <param name="view">The promoted router view when the offset is valid.</param>
        /// <returns>True when the offset identifies a promoted router; otherwise false.</returns>
        internal bool TryGetRouterView(uint ramOffset, out DirectRouterView? view)
        {
            if (ramOffset == 0)
            {
                view = null;
                return false;
            }

            return viewsByOffset.TryGetValue(ramOffset, out view);
        }

        /// <summary>
        /// Clears all promoted router records and resets logical offsets.<br/>
        /// Session commits call this because route bytes or target classifications may have changed under the in-memory projection.<br/>
        /// </summary>
        internal void Clear()
        {
            viewsByOffset.Clear();
            nextOffset = RecordSize;
        }
    }

    private readonly Dictionary<long, byte[]> fixed32Scalar16CleanShelfCache = [];


    /// <summary>
    /// Classifies the structure stored at a direct `FS32-16` route target offset by reading only the persisted magic value.<br/>
    /// Offset zero is treated as `None`; unknown magic values are invalid because route targets must point to known storage structures.<br/>
    /// This method intentionally exposes the extra classification read so walker costs stay measurable while direct fast paths remain unchanged.<br/>
    /// </summary>
    /// <param name="targetOffset">The route target file offset to classify.</param>
    /// <returns>The classified route target kind.</returns>
    /// <exception cref="InvalidDataException">Thrown when the target offset does not contain a recognized router or `FS32-16` shelf magic value.</exception>
    internal Fixed32Scalar16RouteTargetKind ClassifyFixed32Scalar16RouteTarget(long targetOffset)
    {
        if (targetOffset == 0)
        {
            return Fixed32Scalar16RouteTargetKind.None;
        }

        Span<byte> magicBytes = stackalloc byte[sizeof(uint)];
        kernel.Read(targetOffset, magicBytes);
        uint magic = BinaryPrimitives.ReadUInt32LittleEndian(magicBytes);
        if (magic == RouterLayout.Magic)
        {
            return Fixed32Scalar16RouteTargetKind.Router;
        }

        if (magic == Fixed32Scalar16Layout.Magic)
        {
            return Fixed32Scalar16RouteTargetKind.Shelf;
        }

        throw new InvalidDataException($"FS32-16 route target at offset {targetOffset} does not contain a recognized LibraDex structure.");
    }


    /// <summary>
    /// Walks direct one-byte routers for an encoded `FS32-16` key until the route target is classified as a shelf.<br/>
    /// The current implementation reads full router pages plus a 4-byte target classifier at each hop, matching the first fixed scalar route walker shape.<br/>
    /// This walker is intentionally internal and conservative while route-target typing and deeper split behavior remain shape-local.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="key0">The encoded fixed key part 0 whose prefix bytes drive routing.</param>
    /// <param name="key1">The encoded fixed key part 1 whose prefix bytes drive routing.</param>
    /// <param name="key2">The encoded fixed key part 2 whose prefix bytes drive routing.</param>
    /// <param name="key3">The encoded fixed key part 3 whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified shelf target reached by the route walk.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Fixed32Scalar16RouteTarget WalkFixed32Scalar16RouteTarget(
        long rootRouterOffset,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        int maxRouterHops)
    {
        return WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops).Target;
    }


    /// <summary>
    /// Walks direct one-byte routers for an encoded `FS32-16` key and returns both the classified target and the parent router route that selected it.<br/>
    /// Parent-route split logic uses this to refine the exact router page that currently fans several prefixes into the same full shelf.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="key0">The encoded fixed key part 0 whose prefix bytes drive routing.</param>
    /// <param name="key1">The encoded fixed key part 1 whose prefix bytes drive routing.</param>
    /// <param name="key2">The encoded fixed key part 2 whose prefix bytes drive routing.</param>
    /// <param name="key3">The encoded fixed key part 3 whose prefix bytes drive routing.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The classified route target and parent router route metadata.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when a route is unset, a router is invalid, or routing does not terminate at a shelf.</exception>
    internal Fixed32Scalar16RoutePathTarget WalkFixed32Scalar16RoutePathTarget(
        long rootRouterOffset,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        int maxRouterHops)
    {
        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The maximum router hop count must be positive.");
        }

        long routerOffset = rootRouterOffset;
        for (int hop = 0; hop < maxRouterHops; hop++)
        {
            byte[] routerBytes = new byte[RouterLayout.Size];
            kernel.Read(routerOffset, routerBytes);
            RouterReader reader = new(routerBytes);
            if (!reader.IsValid)
            {
                throw new InvalidDataException("The routed page is not a valid router.");
            }

            byte prefixByte = GetFixed32Scalar16Prefix(key0, key1, key2, key3, reader.KeyDepth);
            long targetOffset = reader.FindTarget(prefixByte);
            if (targetOffset == 0)
            {
                throw new InvalidDataException("The routed FS32-16 target is unset.");
            }

            Fixed32Scalar16RouteTargetKind kind = ClassifyFixed32Scalar16RouteTarget(targetOffset);
            if (kind == Fixed32Scalar16RouteTargetKind.Shelf)
            {
                return new Fixed32Scalar16RoutePathTarget(
                    new Fixed32Scalar16RouteTarget(kind, targetOffset, reader.KeyDepth, reader.AllocationClassId),
                    routerOffset,
                    prefixByte);
            }

            if (kind == Fixed32Scalar16RouteTargetKind.Router)
            {
                routerOffset = targetOffset;
                continue;
            }

            throw new InvalidDataException("The routed FS32-16 target is not a shelf or router.");
        }

        throw new InvalidDataException("The routed FS32-16 target walk exceeded the configured maximum router hop count.");
    }


    /// <summary>
    /// Reads and validates one full `FS32-16` shelf extent for a batch-local mutation cache.<br/>
    /// During an active durability batch this is the pending writer view: an existing dirty shelf image is returned before committed backing bytes.<br/>
    /// Dirty images are normalized before reuse by default so writer-side search/insert code can keep using ordinary compact shelf algorithms.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent to read.</param>
    /// <param name="profile">The `FS32-16` profile that determines the shelf extent size.</param>
    /// <param name="normalizePendingBeforeReturn">Whether an existing dirty image should be normalized before it is returned for writer-side search or insertion.</param>
    /// <returns>A mutable byte array containing the current shelf image.</returns>
    /// <exception cref="InvalidDataException">Thrown when the bytes at <paramref name="shelfOffset"/> are not a valid `FS32-16` shelf.</exception>
    internal byte[] ReadFixed32Scalar16ShelfBytesForBatch(long shelfOffset, Fixed32Scalar16Profile profile, bool normalizePendingBeforeReturn = true)
    {
        if (durabilityBatchActive &&
            fixed32Scalar16MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
        {
            if (normalizePendingBeforeReturn)
            {
                Fixed32Scalar16 shelf = new(dirtyShelfBytes, profile);
                _ = shelf.NormalizeDeletedSlotsForPublication();
            }

            return dirtyShelfBytes;
        }

        if (fixed32Scalar16CleanShelfCache.Remove(shelfOffset, out byte[]? cachedShelfBytes))
        {
            Fixed32Scalar16ReadOnly cachedReadOnly = new(cachedShelfBytes, profile);
            if (!cachedReadOnly.IsValid)
            {
                throw new InvalidDataException("The session-local FS32-16 clean shelf cache contained invalid shelf bytes.");
            }

            return cachedShelfBytes;
        }

        byte[] shelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, shelfBytes);
        Fixed32Scalar16ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The batch-local FS32-16 shelf cache read invalid shelf bytes.");
        }

        return shelfBytes;
    }


    /// <summary>
    /// Stores one clean `FS32-16` shelf image for reuse by a later batch in the same session.<br/>
    /// The image must represent bytes already published through a successful commit; the cache is a performance hint and never the durable source of truth.<br/>
    /// </summary>
    /// <param name="shelfOffset">The shelf offset used as the cache key.</param>
    /// <param name="profile">The `FS32-16` profile that determines the shelf extent size.</param>
    /// <param name="shelfBytes">The clean shelf image to keep for a later batch.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="shelfBytes"/> does not match the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="shelfBytes"/> is not a valid `FS32-16` shelf image.</exception>
    internal void StoreFixed32Scalar16CleanShelfBytesForBatch(long shelfOffset, Fixed32Scalar16Profile profile, byte[] shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The session-local FS32-16 clean shelf cache image must match the profiled shelf extent size.", nameof(shelfBytes));
        }

        Fixed32Scalar16ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The session-local FS32-16 clean shelf cache attempted to store invalid shelf bytes.");
        }

        fixed32Scalar16CleanShelfCache[shelfOffset] = shelfBytes;
    }


    /// <summary>
    /// Stages one full `FS32-16` shelf rewrite for a batch-local mutation cache.<br/>
    /// In an active durability batch this increments the deferred commit-request count and leaves publication to the outer batch commit.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent to rewrite.</param>
    /// <param name="profile">The `FS32-16` profile that determines the expected shelf extent size.</param>
    /// <param name="shelfBytes">The final shelf bytes to stage.</param>
    /// <returns>Commit telemetry when no durability batch is active; otherwise default telemetry with the request deferred.</returns>
    /// <exception cref="ArgumentException">Thrown when the shelf byte span does not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when <paramref name="shelfBytes"/> does not contain a valid `FS32-16` shelf.</exception>
    internal DataKernelCommitTelemetry StageFixed32Scalar16ShelfRewriteForBatch(
        long shelfOffset,
        Fixed32Scalar16Profile profile,
        ReadOnlySpan<byte> shelfBytes)
    {
        if (shelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The batch-local FS32-16 shelf rewrite bytes must match the profiled shelf extent size.", nameof(shelfBytes));
        }

        Fixed32Scalar16ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The batch-local FS32-16 shelf cache attempted to stage invalid shelf bytes.");
        }

        if (durabilityBatchActive)
        {
            fixed32Scalar16MutableBatchShelfBytes[shelfOffset] = shelfBytes.ToArray();
            return CommitWithoutInvalidatingRouterReadCache();
        }

        RawDataReservation rewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        shelfBytes.CopyTo(rewrite.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }


    /// <summary>
    /// Stages one partial `FS32-16` shelf rewrite for a batch-local mutation cache.<br/>
    /// The caller owns full-shelf validation and only passes byte ranges whose contents were changed by cached shelf mutation.<br/>
    /// In an active durability batch this increments the deferred commit-request count and leaves publication to the outer batch commit.<br/>
    /// </summary>
    /// <param name="shelfOffset">The offset of the shelf extent that owns the slice.</param>
    /// <param name="profile">The `FS32-16` profile that determines valid shelf bounds.</param>
    /// <param name="sliceOffset">The byte offset inside the shelf extent where the slice begins.</param>
    /// <param name="sliceBytes">The changed shelf bytes to stage.</param>
    /// <returns>Commit telemetry when no durability batch is active; otherwise default telemetry with the request deferred.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the slice is outside the profiled shelf extent.</exception>
    internal DataKernelCommitTelemetry StageFixed32Scalar16ShelfSliceRewriteForBatch(
        long shelfOffset,
        Fixed32Scalar16Profile profile,
        int sliceOffset,
        ReadOnlySpan<byte> sliceBytes)
    {
        if (sliceOffset < 0 || sliceOffset > profile.ShelfExtentSize || sliceBytes.Length > profile.ShelfExtentSize - sliceOffset)
        {
            throw new ArgumentOutOfRangeException(nameof(sliceOffset), sliceOffset, "The batch-local FS32-16 shelf slice must fit inside the profiled shelf extent.");
        }

        if (sliceBytes.Length == 0)
        {
            return default;
        }

        if (durabilityBatchActive)
        {
            if (!fixed32Scalar16MutableBatchShelfBytes.TryGetValue(shelfOffset, out byte[]? dirtyShelfBytes))
            {
                dirtyShelfBytes = new byte[profile.ShelfExtentSize];
                kernel.Read(shelfOffset, dirtyShelfBytes);
                fixed32Scalar16MutableBatchShelfBytes[shelfOffset] = dirtyShelfBytes;
            }

            sliceBytes.CopyTo(dirtyShelfBytes.AsSpan(sliceOffset, sliceBytes.Length));
            return CommitWithoutInvalidatingRouterReadCache();
        }

        RawDataReservation rewrite = kernel.ReserveAt(shelfOffset + sliceOffset, sliceBytes.Length);
        sliceBytes.CopyTo(rewrite.Span);
        return CommitWithoutInvalidatingRouterReadCache();
    }


    /// <summary>
    /// Reads one `FS32-16` shelf into caller-owned scratch for harness-level routed range scans.<br/>
    /// The method validates the shelf image but does not interact with the batch-local clean-shelf cache used by write benchmarks.<br/>
    /// </summary>
    /// <param name="shelfOffset">The file offset of the shelf extent to read.</param>
    /// <param name="profile">The `FS32-16` profile that determines the shelf extent size.</param>
    /// <param name="destination">The caller-owned shelf scratch buffer.</param>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly one profiled shelf extent.</exception>
    /// <exception cref="InvalidDataException">Thrown when the bytes at <paramref name="shelfOffset"/> are not a valid `FS32-16` shelf.</exception>
    internal void ReadFixed32Scalar16ShelfForRangeScan(long shelfOffset, Fixed32Scalar16Profile profile, Span<byte> destination)
    {
        if (destination.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The FS32-16 range-scan shelf scratch buffer must match the profiled shelf extent size.", nameof(destination));
        }

        kernel.Read(shelfOffset, destination);
        Fixed32Scalar16ReadOnly readOnly = new(destination, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The routed range-scan FS32-16 shelf is invalid.");
        }
    }

    /// <summary>
    /// Reads encoded identity pairs for an inclusive `FS32-16` encoded key range using caller-owned scratch and route-kind cache state.<br/>
    /// The traversal follows the persisted router topology and copies both identity lanes directly from validated shelf bytes.<br/>
    /// Reusing <paramref name="targetKindCache"/> across repeated reads over the same session avoids repeated target-classifier reads while keeping cache lifetime explicit.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lower0">The inclusive lower fixed-key lane 0.</param>
    /// <param name="lower1">The inclusive lower fixed-key lane 1.</param>
    /// <param name="lower2">The inclusive lower fixed-key lane 2.</param>
    /// <param name="lower3">The inclusive lower fixed-key lane 3.</param>
    /// <param name="upper0">The inclusive upper fixed-key lane 0.</param>
    /// <param name="upper1">The inclusive upper fixed-key lane 1.</param>
    /// <param name="upper2">The inclusive upper fixed-key lane 2.</param>
    /// <param name="upper3">The inclusive upper fixed-key lane 3.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="encodedIdentityHighs">The caller-owned output span that receives matching encoded identity high lanes.</param>
    /// <param name="encodedIdentityLows">The caller-owned output span that receives matching encoded identity low lanes.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `FS32-16` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>The number of encoded identity pairs copied into <paramref name="encodedIdentityHighs"/> and <paramref name="encodedIdentityLows"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when the key range is invalid, output spans are mismatched, or shelf scratch does not match the profile.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `FS32-16` shelves.</exception>
    internal int ReadFixed32Scalar16IdentityRange(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        int maxRouterHops,
        Span<ulong> encodedIdentityHighs,
        Span<ulong> encodedIdentityLows,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        if (CompareFixed32Scalar8Key(lower0, lower1, lower2, lower3, upper0, upper1, upper2, upper3) > 0)
        {
            throw new ArgumentException("The upper FS32-16 encoded key must be greater than or equal to the lower encoded key.", nameof(upper0));
        }

        if (encodedIdentityLows.Length < encodedIdentityHighs.Length)
        {
            throw new ArgumentException("The FS32-16 identity-low output span must be at least as long as the identity-high output span.", nameof(encodedIdentityLows));
        }

        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The FS32-16 range read route-hop limit must be positive.");
        }

        if (shelfScratch.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The FS32-16 range-read shelf scratch length must match the profiled shelf extent size.", nameof(shelfScratch));
        }

        Span<byte> routerScratch = stackalloc byte[RouterLayout.Size];
        return ReadFixed32Scalar16IdentityRangeFromRouter(
            rootRouterOffset,
            profile,
            lower0,
            lower1,
            lower2,
            lower3,
            upper0,
            upper1,
            upper2,
            upper3,
            remainingRouterHops: maxRouterHops,
            lowerEdge: true,
            upperEdge: true,
            encodedIdentityHighs,
            encodedIdentityLows,
            routerScratch,
            shelfScratch,
            previousShelfOffset: 0,
            targetKindCache);
    }

    /// <summary>
    /// Reads encoded identity pairs for an inclusive `FS32-16` encoded key range using the session default route-hop guard.<br/>
    /// This wrapper returns a result contract while preserving explicit caller-owned scratch and cache lifetimes for hot paths.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lower0">The inclusive lower fixed-key lane 0.</param>
    /// <param name="lower1">The inclusive lower fixed-key lane 1.</param>
    /// <param name="lower2">The inclusive lower fixed-key lane 2.</param>
    /// <param name="lower3">The inclusive lower fixed-key lane 3.</param>
    /// <param name="upper0">The inclusive upper fixed-key lane 0.</param>
    /// <param name="upper1">The inclusive upper fixed-key lane 1.</param>
    /// <param name="upper2">The inclusive upper fixed-key lane 2.</param>
    /// <param name="upper3">The inclusive upper fixed-key lane 3.</param>
    /// <param name="encodedIdentityHighs">The caller-owned output span that receives matching encoded identity high lanes.</param>
    /// <param name="encodedIdentityLows">The caller-owned output span that receives matching encoded identity low lanes.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `FS32-16` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>A result describing the copied identity-pair count and cache shape.</returns>
    internal Fixed32Scalar16RangeReadResult ReadEncodedFixed32Scalar16IdentityRange(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        Span<ulong> encodedIdentityHighs,
        Span<ulong> encodedIdentityLows,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        int identityCount = ReadFixed32Scalar16IdentityRange(
            rootRouterOffset,
            profile,
            lower0,
            lower1,
            lower2,
            lower3,
            upper0,
            upper1,
            upper2,
            upper3,
            DefaultFixed32Scalar16MaxRouterHops,
            encodedIdentityHighs,
            encodedIdentityLows,
            shelfScratch,
            targetKindCache);
        return new Fixed32Scalar16RangeReadResult(
            identityCount,
            UsedRouteKindCache: true,
            targetKindCache.Count);
    }

    private int ReadFixed32Scalar16IdentityRangeFromRouter(
        long routerOffset,
        Fixed32Scalar16Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        int remainingRouterHops,
        bool lowerEdge,
        bool upperEdge,
        Span<ulong> encodedIdentityHighs,
        Span<ulong> encodedIdentityLows,
        Span<byte> routerScratch,
        Span<byte> shelfScratch,
        long previousShelfOffset,
        RouteTargetKindCache targetKindCache)
    {
        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The FS32-16 routed range traversal exceeded the configured maximum router hop count.");
        }

        ReadRouterPageForRangeScan(routerOffset, routerScratch);
        RouterReader reader = new(routerScratch);
        byte startPrefix = lowerEdge ? GetFixed32Scalar16Prefix(lower0, lower1, lower2, lower3, reader.KeyDepth) : (byte)0;
        byte endPrefix = upperEdge ? GetFixed32Scalar16Prefix(upper0, upper1, upper2, upper3, reader.KeyDepth) : byte.MaxValue;
        int routeCount = endPrefix - startPrefix + 1;
        Span<long> targetOffsets = stackalloc long[routeCount];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            targetOffsets[prefix - startPrefix] = reader.FindTarget((byte)prefix);
        }

        int copied = 0;
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            byte prefixByte = (byte)prefix;
            long targetOffset = targetOffsets[prefix - startPrefix];
            if (targetOffset == 0)
            {
                continue;
            }

            Fixed32Scalar16RouteTargetKind kind = GetFixed32Scalar16RouteTargetKind(targetOffset, targetKindCache);
            if (kind == Fixed32Scalar16RouteTargetKind.Router)
            {
                copied += ReadFixed32Scalar16IdentityRangeFromRouter(
                    targetOffset,
                    profile,
                    lower0,
                    lower1,
                    lower2,
                    lower3,
                    upper0,
                    upper1,
                    upper2,
                    upper3,
                    remainingRouterHops - 1,
                    lowerEdge && prefixByte == startPrefix,
                    upperEdge && prefixByte == endPrefix,
                    encodedIdentityHighs[copied..],
                    encodedIdentityLows[copied..],
                    routerScratch,
                    shelfScratch,
                    previousShelfOffset,
                    targetKindCache);
                continue;
            }

            if (kind != Fixed32Scalar16RouteTargetKind.Shelf || targetOffset == previousShelfOffset)
            {
                continue;
            }

            ReadFixed32Scalar16ShelfForRangeScan(targetOffset, profile, shelfScratch);
            Fixed32Scalar16ReadOnly shelf = new(shelfScratch, profile);
            copied += shelf.CopyIdentitiesInKeyRange(lower0, lower1, lower2, lower3, upper0, upper1, upper2, upper3, encodedIdentityHighs[copied..], encodedIdentityLows[copied..]);
            previousShelfOffset = targetOffset;
        }

        return copied;
    }

    /// <summary>
    /// Reads encoded identity lows for an inclusive `FS32-16` encoded key range using caller-owned scratch and route-kind cache state.<br/>
    /// Current `FS32-16` harness data stores the useful scalar identity in the low half; this method returns that low lane to match existing fixed-32 read parity checks.<br/>
    /// Reusing <paramref name="targetKindCache"/> across repeated reads over the same session avoids repeated 4-byte target-classifier reads without introducing global mutable state.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lower0">The inclusive lower fixed-key lane 0.</param>
    /// <param name="lower1">The inclusive lower fixed-key lane 1.</param>
    /// <param name="lower2">The inclusive lower fixed-key lane 2.</param>
    /// <param name="lower3">The inclusive lower fixed-key lane 3.</param>
    /// <param name="upper0">The inclusive upper fixed-key lane 0.</param>
    /// <param name="upper1">The inclusive upper fixed-key lane 1.</param>
    /// <param name="upper2">The inclusive upper fixed-key lane 2.</param>
    /// <param name="upper3">The inclusive upper fixed-key lane 3.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <param name="encodedIdentityLows">The caller-owned output span that receives matching encoded identity low lanes.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `FS32-16` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>The number of encoded identity lows copied into <paramref name="encodedIdentityLows"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when the key range is invalid or shelf scratch does not match the profile.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="maxRouterHops"/> is not positive.</exception>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at valid `FS32-16` shelves.</exception>
    internal int ReadFixed32Scalar16IdentityLowRange(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        int maxRouterHops,
        Span<ulong> encodedIdentityLows,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        if (CompareFixed32Scalar8Key(lower0, lower1, lower2, lower3, upper0, upper1, upper2, upper3) > 0)
        {
            throw new ArgumentException("The upper FS32-16 encoded key must be greater than or equal to the lower encoded key.", nameof(upper0));
        }

        if (maxRouterHops <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(maxRouterHops), maxRouterHops, "The FS32-16 range read route-hop limit must be positive.");
        }

        if (shelfScratch.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The FS32-16 range-read shelf scratch length must match the profiled shelf extent size.", nameof(shelfScratch));
        }

        Span<byte> routerScratch = stackalloc byte[RouterLayout.Size];
        return ReadFixed32Scalar16IdentityLowRangeFromRouter(
            rootRouterOffset,
            profile,
            lower0,
            lower1,
            lower2,
            lower3,
            upper0,
            upper1,
            upper2,
            upper3,
            remainingRouterHops: maxRouterHops,
            lowerEdge: true,
            upperEdge: true,
            encodedIdentityLows,
            routerScratch,
            shelfScratch,
            previousShelfOffset: 0,
            targetKindCache);
    }

    /// <summary>
    /// Reads encoded identity lows for an inclusive `FS32-16` encoded key range using the session default route-hop guard.<br/>
    /// This wrapper returns a result contract while preserving explicit caller-owned scratch and cache lifetimes for hot paths.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent length and slot/item layout.</param>
    /// <param name="lower0">The inclusive lower fixed-key lane 0.</param>
    /// <param name="lower1">The inclusive lower fixed-key lane 1.</param>
    /// <param name="lower2">The inclusive lower fixed-key lane 2.</param>
    /// <param name="lower3">The inclusive lower fixed-key lane 3.</param>
    /// <param name="upper0">The inclusive upper fixed-key lane 0.</param>
    /// <param name="upper1">The inclusive upper fixed-key lane 1.</param>
    /// <param name="upper2">The inclusive upper fixed-key lane 2.</param>
    /// <param name="upper3">The inclusive upper fixed-key lane 3.</param>
    /// <param name="encodedIdentityLows">The caller-owned output span that receives matching encoded identity low lanes.</param>
    /// <param name="shelfScratch">The caller-owned buffer for one profiled `FS32-16` shelf extent.</param>
    /// <param name="targetKindCache">The caller-owned target-kind cache scoped to this session/file.</param>
    /// <returns>A result describing the copied identity count and cache shape.</returns>
    internal Fixed32Scalar16RangeReadResult ReadEncodedFixed32Scalar16IdentityLowRange(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        Span<ulong> encodedIdentityLows,
        Span<byte> shelfScratch,
        RouteTargetKindCache targetKindCache)
    {
        int identityCount = ReadFixed32Scalar16IdentityLowRange(
            rootRouterOffset,
            profile,
            lower0,
            lower1,
            lower2,
            lower3,
            upper0,
            upper1,
            upper2,
            upper3,
            DefaultFixed32Scalar16MaxRouterHops,
            encodedIdentityLows,
            shelfScratch,
            targetKindCache);
        return new Fixed32Scalar16RangeReadResult(
            identityCount,
            UsedRouteKindCache: true,
            targetKindCache.Count);
    }

    private int ReadFixed32Scalar16IdentityLowRangeFromRouter(
        long routerOffset,
        Fixed32Scalar16Profile profile,
        ulong lower0,
        ulong lower1,
        ulong lower2,
        ulong lower3,
        ulong upper0,
        ulong upper1,
        ulong upper2,
        ulong upper3,
        int remainingRouterHops,
        bool lowerEdge,
        bool upperEdge,
        Span<ulong> encodedIdentityLows,
        Span<byte> routerScratch,
        Span<byte> shelfScratch,
        long previousShelfOffset,
        RouteTargetKindCache targetKindCache)
    {
        if (remainingRouterHops <= 0)
        {
            throw new InvalidDataException("The FS32-16 routed range traversal exceeded the configured maximum router hop count.");
        }

        ReadRouterPageForRangeScan(routerOffset, routerScratch);
        RouterReader reader = new(routerScratch);
        byte startPrefix = lowerEdge ? GetFixed32Scalar16Prefix(lower0, lower1, lower2, lower3, reader.KeyDepth) : (byte)0;
        byte endPrefix = upperEdge ? GetFixed32Scalar16Prefix(upper0, upper1, upper2, upper3, reader.KeyDepth) : byte.MaxValue;
        int routeCount = endPrefix - startPrefix + 1;
        Span<long> targetOffsets = routeCount <= 256
            ? stackalloc long[routeCount]
            : new long[routeCount];
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            targetOffsets[prefix - startPrefix] = reader.FindTarget((byte)prefix);
        }

        int copied = 0;
        for (int prefix = startPrefix; prefix <= endPrefix; prefix++)
        {
            byte prefixByte = (byte)prefix;
            long targetOffset = targetOffsets[prefix - startPrefix];
            if (targetOffset == 0)
            {
                continue;
            }

            Fixed32Scalar16RouteTargetKind kind = GetFixed32Scalar16RouteTargetKind(targetOffset, targetKindCache);
            if (kind == Fixed32Scalar16RouteTargetKind.Router)
            {
                copied += ReadFixed32Scalar16IdentityLowRangeFromRouter(
                    targetOffset,
                    profile,
                    lower0,
                    lower1,
                    lower2,
                    lower3,
                    upper0,
                    upper1,
                    upper2,
                    upper3,
                    remainingRouterHops - 1,
                    lowerEdge && prefixByte == startPrefix,
                    upperEdge && prefixByte == endPrefix,
                    encodedIdentityLows[copied..],
                    routerScratch,
                    shelfScratch,
                    previousShelfOffset,
                    targetKindCache);
                continue;
            }

            if (kind != Fixed32Scalar16RouteTargetKind.Shelf || targetOffset == previousShelfOffset)
            {
                continue;
            }

            ReadFixed32Scalar16ShelfForRangeScan(targetOffset, profile, shelfScratch);
            Fixed32Scalar16ReadOnly shelf = new(shelfScratch, profile);
            copied += shelf.CopyIdentitiesInKeyRange(lower0, lower1, lower2, lower3, upper0, upper1, upper2, upper3, encodedIdentityLows[copied..]);
            previousShelfOffset = targetOffset;
        }

        return copied;
    }

    private Fixed32Scalar16RouteTargetKind GetFixed32Scalar16RouteTargetKind(long targetOffset, RouteTargetKindCache targetKindCache)
    {
        if (targetKindCache.TryGet(targetOffset, out int cachedKind))
        {
            return (Fixed32Scalar16RouteTargetKind)cachedKind;
        }

        Fixed32Scalar16RouteTargetKind kind = ClassifyFixed32Scalar16RouteTarget(targetOffset);
        targetKindCache.Set(targetOffset, (int)kind);
        return kind;
    }


    /// <summary>
    /// Appends a sorted `Fixed32Scalar16` shelf and links one root-router prefix byte to the new shelf in the same commit.<br/>
    /// The shelf is initialized with deterministic `(key0, key1, key2, key3, identity)` tuples where the key suffix plus identity equal the insert index.<br/>
    /// This mirrors the first `SS16-8` router-to-shelf primitive while keeping the fixed 32-byte key shelf isolated from split code.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte route to link to the new shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile used to size and populate the shelf extent.</param>
    /// <param name="itemCount">The number of deterministic sorted tuples to insert into the shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="itemCount"/> is outside the profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid, not direct-index capable, or shelf population fails.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateFixed32Scalar16ShelfAndLinkRootRoute(
        long rootRouterOffset,
        byte prefixByte,
        Fixed32Scalar16Profile profile,
        int itemCount)
    {
        if (itemCount < 0 || itemCount > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(itemCount), itemCount, "FS32-16 shelf item count is outside the profiled capacity.");
        }

        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingReader = new(existingRouter);
        if (!existingReader.IsValid || !existingReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < itemCount; i++)
        {
            Fixed32Scalar16Layout.EncodeFixed32FromUInt64((ulong)i, out ulong key0, out ulong key1, out ulong key2, out ulong key3);
            Fixed32Scalar16InsertResult result = shelf.Insert(
                key0,
                key1,
                key2,
                key3,
                Fixed32Scalar16Layout.EncodeUnsignedScalar8((ulong)i),
                allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-16 routed shelf insert at {i}, got {result}.");
            }
        }

        RawDataReservation routerReservation = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerReservation.Span);
        RouterWriter writer = new(routerReservation.Span);
        writer.WriteRoute(prefixByte, prefixByte, prefixByte, shelfReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (shelfReservation.Extent.Offset, telemetry);
    }


    /// <summary>
    /// Routes one prefix byte through a persisted root router and reads the targeted `FS32-16` shelf bytes into a caller buffer.<br/>
    /// This validation helper deliberately performs the two physical reads separately: root router first, then shelf extent.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte to route.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="destination">The caller buffer that receives the shelf bytes.</param>
    /// <returns>The routed shelf offset that was read into <paramref name="destination"/>.</returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when the route is unset or points to an invalid `FS32-16` shelf.</exception>
    internal long ReadRoutedFixed32Scalar16Shelf(
        long rootRouterOffset,
        byte prefixByte,
        Fixed32Scalar16Profile profile,
        Span<byte> destination)
    {
        if (destination.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The destination length must match the profiled FS32-16 shelf extent size.", nameof(destination));
        }

        long shelfOffset = FindRouterTarget(rootRouterOffset, prefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-16 shelf route is unset.");
        }

        kernel.Read(shelfOffset, destination);
        Fixed32Scalar16ReadOnly shelf = new(destination, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The routed FS32-16 shelf bytes are invalid.");
        }

        return shelfOffset;
    }


    /// <summary>
    /// Inserts one tuple into a routed `FS32-16` shelf without performing split handling.<br/>
    /// The method routes through the root router, reads the target fixed-key shelf, stages a same-offset shelf rewrite, and commits only when the shelf insert mutates bytes.<br/>
    /// If the tuple is already present, the method returns without committing because the physical mutation is a no-op.<br/>
    /// If the shelf is full or a unique-key conflict occurs, the method returns that insert result without committing so the caller can choose the next structural path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="prefixByte">The single prefix byte used to route to the shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="key0">The encoded sortable key part 0 to insert.</param>
    /// <param name="key1">The encoded sortable key part 1 to insert.</param>
    /// <param name="key2">The encoded sortable key part 2 to insert.</param>
    /// <param name="key3">The encoded sortable key part 3 to insert.</param>
    /// <param name="encodedIdentity">The encoded sortable identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The routed shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when the route is unset or points to an invalid `FS32-16` shelf.</exception>
    internal (long ShelfOffset, Fixed32Scalar16InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertRoutedFixed32Scalar16NoSplit(
        long rootRouterOffset,
        byte prefixByte,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        long shelfOffset = FindRouterTarget(rootRouterOffset, prefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-16 shelf route is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Fixed32Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The routed FS32-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Fixed32Scalar16 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar16InsertResult result = shelf.Insert(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys);
        if (result != Fixed32Scalar16InsertResult.Inserted)
        {
            return (shelfOffset, result, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (shelfOffset, result, telemetry);
    }


    /// <summary>
    /// Appends a caller-populated `FS32-16` shelf and links multiple root-router prefix bytes to that same shelf in one commit.<br/>
    /// This helper exists for fixed-key split-path validation where a single full shelf initially owns more than one root prefix byte.<br/>
    /// The supplied key and identity vectors are inserted through the shelf view, so persisted ordering and duplicate rules match normal shelf behavior.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that sizes the new shelf extent.</param>
    /// <param name="key0s">The encoded key part 0 values to insert into the shelf.</param>
    /// <param name="key1s">The encoded key part 1 values to insert into the shelf.</param>
    /// <param name="key2s">The encoded key part 2 values to insert into the shelf.</param>
    /// <param name="key3s">The encoded key part 3 values to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <param name="prefixBytes">The root-router prefix bytes to point at the new shelf.</param>
    /// <returns>The created shelf offset and commit telemetry for the combined shelf append plus root-router rewrite.</returns>
    /// <exception cref="ArgumentException">Thrown when key and identity vector lengths differ.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ShelfOffset, DataKernelCommitTelemetry Commit) CreateFixed32Scalar16ShelfAndLinkRootRoutes(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ReadOnlySpan<ulong> key0s,
        ReadOnlySpan<ulong> key1s,
        ReadOnlySpan<ulong> key2s,
        ReadOnlySpan<ulong> key3s,
        ReadOnlySpan<ulong> encodedIdentities,
        ReadOnlySpan<byte> prefixBytes)
    {
        if (key0s.Length != key1s.Length || key0s.Length != key2s.Length || key0s.Length != key3s.Length || key0s.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("FS32-16 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (key0s.Length <= 0 || key0s.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(key0s), key0s.Length, "FS32-16 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingReader = new(existingRouter);
        if (!existingReader.IsValid || !existingReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < key0s.Length; i++)
        {
            Fixed32Scalar16InsertResult result = shelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-16 setup shelf insert at {i}, got {result}.");
            }
        }

        RawDataReservation routerReservation = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerReservation.Span);
        RouterWriter writer = new(routerReservation.Span);
        for (int i = 0; i < prefixBytes.Length; i++)
        {
            byte prefix = prefixBytes[i];
            writer.WriteRoute(prefix, prefix, prefix, shelfReservation.Extent.Offset);
        }

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (shelfReservation.Extent.Offset, telemetry);
    }


    /// <summary>
    /// Splits a routed full `FS32-16` shelf by root prefix.<br/>
    /// This first fixed-key split path only covers split boundaries that are representable by the owning root router's current prefix byte.<br/>
    /// The existing shelf is read, the incoming tuple is merged into sorted order, tuples whose first fixed-key byte is below <paramref name="rightPrefixByte"/> remain left, and all others move right.<br/>
    /// Same-prefix splits are intentionally excluded because they require a later `FS32-16` shelf-to-router transform path.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="leftPrefixByte">The prefix byte that continues to route to the rewritten left shelf.</param>
    /// <param name="rightPrefixByte">The prefix byte that will route to the appended right shelf after the split.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both split shelves.</param>
    /// <param name="key0">The encoded key part 0 to insert during the split.</param>
    /// <param name="key1">The encoded key part 1 to insert during the split.</param>
    /// <param name="key2">The encoded key part 2 to insert during the split.</param>
    /// <param name="key3">The encoded key part 3 to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <returns>The left shelf offset, right shelf offset, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedFixed32Scalar16ByRootPrefix(
            long rootRouterOffset,
            byte leftPrefixByte,
            byte rightPrefixByte,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity)
    {
        long leftShelfOffset = FindRouterTarget(rootRouterOffset, leftPrefixByte);
        if (leftShelfOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-16 left shelf route is unset.");
        }

        long currentRightTarget = FindRouterTarget(rootRouterOffset, rightPrefixByte);
        if (currentRightTarget != leftShelfOffset)
        {
            throw new InvalidDataException("The first FS32-16 split path expects both root prefixes to currently route to the same full shelf.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(leftShelfOffset, existingShelfBytes);
        byte[] existingRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRouter);
        RouterReader existingRouterReader = new(existingRouter);
        if (!existingRouterReader.IsValid || !existingRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        Fixed32Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The first FS32-16 split path expects a valid full shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] key0s = new ulong[existingCount + 1];
        ulong[] key1s = new ulong[existingCount + 1];
        ulong[] key2s = new ulong[existingCount + 1];
        ulong[] key3s = new ulong[existingCount + 1];
        ulong[] identities = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentity = existingShelf.ReadIdentityAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar16Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentity, key0, key1, key2, key3, encodedIdentity) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identities[targetIndex] = encodedIdentity;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentity == encodedIdentity)
            {
                return (leftShelfOffset, 0, existingCount, 0, Fixed32Scalar16InsertResult.AlreadyPresent, default);
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identities[targetIndex] = currentIdentity;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identities[targetIndex] = encodedIdentity;
        }

        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar16 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = (byte)(key0s[i] >> 56) >= rightPrefixByte;
            Fixed32Scalar16InsertResult result = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identities[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split FS32-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The first FS32-16 split path requires both split shelves to receive at least one item.");
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(leftShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);
        RawDataReservation routerRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRouter.CopyTo(routerRewrite.Span);
        RouterWriter writer = new(routerRewrite.Span);
        writer.WriteRoute(rightPrefixByte, rightPrefixByte, rightPrefixByte, rightAppend.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (leftShelfOffset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Fixed32Scalar16InsertResult.Inserted, telemetry);
    }


    /// <summary>
    /// Splits a full routed `FS32-16` shelf by transforming the shelf's existing offset into a child router and appending two replacement shelves.<br/>
    /// This path covers same-root-prefix fixed-32-byte-key splits where the root route must stay stable and the next key byte decides left/right ownership.<br/>
    /// The parent root router is not dirtied; the former shelf location is structurally reused as a direct-index one-byte child router at key depth `1`.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root prefix byte that currently routes to the full shelf and will continue routing to the transformed child router.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing, shelf validity, or split partitioning is invalid.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedFixed32Scalar16ByShelfTransform(
            long rootRouterOffset,
            byte rootPrefixByte,
            byte rightPrefixByte,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity)
    {
        byte[] rootRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, rootRouterBytes);
        RouterReader rootRouterReader = new(rootRouterBytes);
        if (!rootRouterReader.IsValid || !rootRouterReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        ushort allocationClassId = rootRouterReader.AllocationClassId;
        long childRouterOffset = rootRouterReader.FindTarget(rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The routed FS32-16 transform source route is unset.");
        }

        byte[] existingShelfBytes = new byte[profile.ShelfExtentSize];
        kernel.Read(childRouterOffset, existingShelfBytes);
        return SplitRoutedFixed32Scalar16ByShelfTransform(
            childRouterOffset,
            existingShelfBytes,
            rightPrefixByte,
            profile,
            key0,
            key1,
            key2,
            key3,
            0,
            encodedIdentity,
            allocationClassId,
            childRouterKeyDepth: 1);
    }


    /// <summary>
    /// Splits an already-routed full `FS32-16` shelf by transforming its offset into a child router using caller-provided shelf bytes.<br/>
    /// This reuse path avoids rereading the root router and full shelf when an outer insert decision has already loaded them.<br/>
    /// </summary>
    /// <param name="childRouterOffset">The old shelf offset that will be rewritten as the child router.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="rightPrefixByte">The second-depth prefix byte that starts the right replacement shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="allocationClassId">The allocation class identifier to persist in the transformed child router.</param>
    /// <param name="childRouterKeyDepth">The key byte depth where the transformed router begins.</param>
    /// <returns>The child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when supplied shelf bytes do not match the profiled extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when shelf validity or split partitioning is invalid.</exception>
    private (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitRoutedFixed32Scalar16ByShelfTransform(
            long childRouterOffset,
            ReadOnlySpan<byte> existingShelfBytes,
            byte rightPrefixByte,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentityHigh,
            ulong encodedIdentityLow,
            ushort allocationClassId,
            ushort childRouterKeyDepth)
    {
        if (existingShelfBytes.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The existing shelf buffer must match the profiled FS32-16 shelf extent size.", nameof(existingShelfBytes));
        }

        Fixed32Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The transform split path expects a valid full FS32-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] key0s = new ulong[existingCount + 1];
        ulong[] key1s = new ulong[existingCount + 1];
        ulong[] key2s = new ulong[existingCount + 1];
        ulong[] key3s = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar16Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentityHigh, currentIdentityLow, key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                return (childRouterOffset, 0, 0, existingCount, 0, Fixed32Scalar16InsertResult.AlreadyPresent, default);
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        (ushort splitKeyDepth, byte selectedRightPrefixByte) = ChooseFixed32Scalar16TransformSplitPlan(key0s, key1s, key2s, key3s, childRouterKeyDepth, rightPrefixByte);
        byte[] leftShelfBytes = new byte[profile.ShelfExtentSize];
        byte[] rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar16 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = GetFixed32Scalar16Prefix(key0s[i], key1s[i], key2s[i], key3s[i], splitKeyDepth) >= selectedRightPrefixByte;
            Fixed32Scalar16InsertResult result = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected transform split FS32-16 insert at {i}, got {result}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            throw new InvalidDataException("The transform split path requires both replacement shelves to receive at least one item.");
        }

        RawDataReservation leftAppend = kernel.Reserve(profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftAppend.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        int appendedRouterCount = splitKeyDepth - childRouterKeyDepth;
        long nextRouterOffset = 0;
        for (int i = appendedRouterCount - 1; i >= 0; i--)
        {
            ushort routerDepth = checked((ushort)(childRouterKeyDepth + i + 1));
            long[] targets = routerDepth == splitKeyDepth
                ? CreateSplitScalar8Scalar8RouteTargets(leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte)
                : CreateFilledScalar8Scalar8RouteTargets(nextRouterOffset);
            RawDataReservation appendedRouter = kernel.Reserve(RouterLayout.Size);
            RouterWriter appendedWriter = new(appendedRouter.Span);
            appendedWriter.InitializeExpandedOneByte(routerDepth, allocationClassId, targets);
            nextRouterOffset = appendedRouter.Extent.Offset;
        }

        RawDataReservation childRouterRewrite = kernel.ReserveAt(childRouterOffset, RouterLayout.Size);
        RouterWriter childWriter = new(childRouterRewrite.Span);
        childWriter.InitializeExpandedOneByte(
            childRouterKeyDepth,
            allocationClassId,
            CreateUniformScalar8Scalar8RouteTargets(nextRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, selectedRightPrefixByte));
        childWriter.WriteArenaMetadata(
            arenaBaseDelta: 0,
            arenaLength: profile.ShelfExtentSize,
            routerPageSize: checked((ushort)RouterLayout.Size),
            routerPageIndex: 0,
            routerPageCount: checked((ushort)(profile.ShelfExtentSize / RouterLayout.Size)),
            arenaFlags: 0);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        RouterArenaState arena = RegisterRouterArena(childRouterOffset, profile.ShelfExtentSize);
        arena.MarkUsed(0);
        return (childRouterOffset, leftAppend.Extent.Offset, rightAppend.Extent.Offset, leftShelf.ItemCount, rightShelf.ItemCount, Fixed32Scalar16InsertResult.Inserted, telemetry);
    }


    /// <summary>
    /// Appends a caller-populated `FS32-16` shelf behind a new direct-index child router and links that child router from the root in one commit.<br/>
    /// This validation primitive mirrors the `SS16-8` deeper-route setup while keeping fixed-32-byte-key shelf population shape-local.<br/>
    /// The root router is rewritten in place, while the child router and shelf are appended contiguously for write-combined publication.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The root-router prefix byte that will point to the child router.</param>
    /// <param name="childPrefixByte">The child-router prefix byte that will point to the created shelf.</param>
    /// <param name="profile">The `FS32-16` shelf profile that sizes the new shelf extent.</param>
    /// <param name="key0s">The first encoded key lanes to insert into the shelf.</param>
    /// <param name="key1s">The second encoded key lanes to insert into the shelf.</param>
    /// <param name="key2s">The third encoded key lanes to insert into the shelf.</param>
    /// <param name="key3s">The fourth encoded key lanes to insert into the shelf.</param>
    /// <param name="encodedIdentities">The encoded scalar identities to insert into the shelf.</param>
    /// <returns>The child router offset, shelf offset, and commit telemetry.</returns>
    /// <exception cref="ArgumentException">Thrown when the supplied vectors have different lengths.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when the supplied tuple count is outside the shelf profile capacity.</exception>
    /// <exception cref="InvalidDataException">Thrown when the root router is invalid or the supplied tuples cannot be inserted.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, DataKernelCommitTelemetry Commit) CreateFixed32Scalar16ShelfBehindChildRouter(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Fixed32Scalar16Profile profile,
        ReadOnlySpan<ulong> key0s,
        ReadOnlySpan<ulong> key1s,
        ReadOnlySpan<ulong> key2s,
        ReadOnlySpan<ulong> key3s,
        ReadOnlySpan<ulong> encodedIdentities)
    {
        if (key0s.Length != key1s.Length || key0s.Length != key2s.Length || key0s.Length != key3s.Length || key0s.Length != encodedIdentities.Length)
        {
            throw new ArgumentException("FS32-16 key and identity vectors must have the same length.", nameof(encodedIdentities));
        }

        if (key0s.Length <= 0 || key0s.Length > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(key0s), key0s.Length, "FS32-16 supplied tuple count is outside the profiled capacity.");
        }

        byte[] existingRootRouter = new byte[RouterLayout.Size];
        kernel.Read(rootRouterOffset, existingRootRouter);
        RouterReader rootReader = new(existingRootRouter);
        if (!rootReader.IsValid || !rootReader.HasDirectIndex)
        {
            throw new InvalidDataException("The root router is invalid or not direct-index capable.");
        }

        RawDataReservation childRouterReservation = kernel.Reserve(RouterLayout.Size);
        RawDataReservation shelfReservation = kernel.Reserve(profile.ShelfExtentSize);
        Fixed32Scalar16 shelf = new(shelfReservation.Span, profile);
        shelf.Initialize();
        for (int i = 0; i < key0s.Length; i++)
        {
            Fixed32Scalar16InsertResult result = shelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], encodedIdentities[i], allowDuplicateKeys: true);
            if (result != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-16 child shelf insert at {i}, got {result}.");
            }
        }

        long[] childTargets = new long[RouterLayout.MaxOneByteRouteCount];
        childTargets[childPrefixByte] = shelfReservation.Extent.Offset;
        RouterWriter childWriter = new(childRouterReservation.Span);
        childWriter.InitializeExpandedOneByte(1, rootReader.AllocationClassId, childTargets);

        RawDataReservation rootRouterRewrite = kernel.ReserveAt(rootRouterOffset, RouterLayout.Size);
        existingRootRouter.CopyTo(rootRouterRewrite.Span);
        RouterWriter rootWriter = new(rootRouterRewrite.Span);
        rootWriter.WriteRoute(rootPrefixByte, rootPrefixByte, rootPrefixByte, childRouterReservation.Extent.Offset);

        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterReservation.Extent.Offset, shelfReservation.Extent.Offset, telemetry);
    }


    /// <summary>
    /// Tries to build replacement `FS32-16` shelves for a parent-route refinement split at one encoded key byte depth.<br/>
    /// The incoming tuple is merged into sorted order first, then the selected route prefix boundary is used to populate left and right replacement shelves.<br/>
    /// Returning false means the parent route cannot distinguish the tuples at this depth or the incoming tuple was already present.<br/>
    /// </summary>
    /// <param name="existingShelfBytes">The full source shelf bytes.</param>
    /// <param name="keyDepth">The parent router key byte depth used for partitioning.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix used as the initial boundary hint.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="selectedRightPrefixByte">The selected first right-side prefix byte.</param>
    /// <param name="leftShelfBytes">The populated left replacement shelf bytes.</param>
    /// <param name="rightShelfBytes">The populated right replacement shelf bytes.</param>
    /// <param name="leftItemCount">The number of tuples in the left replacement shelf.</param>
    /// <param name="rightItemCount">The number of tuples in the right replacement shelf.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <returns>True when replacement shelves were created; otherwise false.</returns>
    private static bool TryCreateFixed32Scalar16SplitShelves(
        ReadOnlySpan<byte> existingShelfBytes,
        ushort keyDepth,
        byte hintRightPrefixByte,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out byte selectedRightPrefixByte,
        out byte[] leftShelfBytes,
        out byte[] rightShelfBytes,
        out int leftItemCount,
        out int rightItemCount,
        out Fixed32Scalar16InsertResult insertResult)
    {
        selectedRightPrefixByte = 0;
        leftShelfBytes = [];
        rightShelfBytes = [];
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;

        Fixed32Scalar16ReadOnly existingShelf = new(existingShelfBytes, profile);
        if (!existingShelf.IsValid || existingShelf.ItemCount != profile.MaxItemCount)
        {
            throw new InvalidDataException("The split path expects a valid full FS32-16 shelf.");
        }

        int existingCount = existingShelf.ItemCount;
        ulong[] key0s = new ulong[existingCount + 1];
        ulong[] key1s = new ulong[existingCount + 1];
        ulong[] key2s = new ulong[existingCount + 1];
        ulong[] key3s = new ulong[existingCount + 1];
        ulong[] identityHighs = new ulong[existingCount + 1];
        ulong[] identityLows = new ulong[existingCount + 1];
        bool inserted = false;
        int targetIndex = 0;
        for (int sourceIndex = 0; sourceIndex < existingCount; sourceIndex++)
        {
            ulong currentKey0 = existingShelf.ReadKeyPart0At(sourceIndex);
            ulong currentKey1 = existingShelf.ReadKeyPart1At(sourceIndex);
            ulong currentKey2 = existingShelf.ReadKeyPart2At(sourceIndex);
            ulong currentKey3 = existingShelf.ReadKeyPart3At(sourceIndex);
            ulong currentIdentityHigh = existingShelf.ReadIdentityHighAt(sourceIndex);
            ulong currentIdentityLow = existingShelf.ReadIdentityLowAt(sourceIndex);
            if (!inserted && CompareFixed32Scalar16Tuple(currentKey0, currentKey1, currentKey2, currentKey3, currentIdentityHigh, currentIdentityLow, key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow) > 0)
            {
                key0s[targetIndex] = key0;
                key1s[targetIndex] = key1;
                key2s[targetIndex] = key2;
                key3s[targetIndex] = key3;
                identityHighs[targetIndex] = encodedIdentityHigh;
                identityLows[targetIndex] = encodedIdentityLow;
                targetIndex++;
                inserted = true;
            }

            if (currentKey0 == key0 && currentKey1 == key1 && currentKey2 == key2 && currentKey3 == key3 && currentIdentityHigh == encodedIdentityHigh && currentIdentityLow == encodedIdentityLow)
            {
                insertResult = Fixed32Scalar16InsertResult.AlreadyPresent;
                return false;
            }

            key0s[targetIndex] = currentKey0;
            key1s[targetIndex] = currentKey1;
            key2s[targetIndex] = currentKey2;
            key3s[targetIndex] = currentKey3;
            identityHighs[targetIndex] = currentIdentityHigh;
            identityLows[targetIndex] = currentIdentityLow;
            targetIndex++;
        }

        if (!inserted)
        {
            key0s[targetIndex] = key0;
            key1s[targetIndex] = key1;
            key2s[targetIndex] = key2;
            key3s[targetIndex] = key3;
            identityHighs[targetIndex] = encodedIdentityHigh;
            identityLows[targetIndex] = encodedIdentityLow;
        }

        if (!TryChooseFixed32Scalar16TransformSplitRightPrefix(key0s, key1s, key2s, key3s, keyDepth, hintRightPrefixByte, out selectedRightPrefixByte))
        {
            return false;
        }

        leftShelfBytes = new byte[profile.ShelfExtentSize];
        rightShelfBytes = new byte[profile.ShelfExtentSize];
        Fixed32Scalar16 leftShelf = new(leftShelfBytes, profile);
        Fixed32Scalar16 rightShelf = new(rightShelfBytes, profile);
        leftShelf.Initialize();
        rightShelf.Initialize();

        for (int i = 0; i < key0s.Length; i++)
        {
            bool goesRight = GetFixed32Scalar16Prefix(key0s[i], key1s[i], key2s[i], key3s[i], keyDepth) >= selectedRightPrefixByte;
            Fixed32Scalar16InsertResult itemResult = goesRight
                ? rightShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true)
                : leftShelf.Insert(key0s[i], key1s[i], key2s[i], key3s[i], identityHighs[i], identityLows[i], allowDuplicateKeys: true);
            if (itemResult != Fixed32Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected split FS32-16 insert at {i}, got {itemResult}.");
            }
        }

        if (leftShelf.ItemCount == 0 || rightShelf.ItemCount == 0)
        {
            return false;
        }

        leftItemCount = leftShelf.ItemCount;
        rightItemCount = rightShelf.ItemCount;
        insertResult = Fixed32Scalar16InsertResult.Inserted;
        return true;
    }


    /// <summary>
    /// Chooses the key byte depth and right-side prefix boundary for an `FS32-16` transform split.<br/>
    /// The search starts at the immediate child-router depth and advances until it finds a prefix byte that can divide the full shelf plus incoming tuple into two replacement shelves.<br/>
    /// This mirrors the `SS16-8` transform planner while reading from all four fixed-key lanes.<br/>
    /// </summary>
    /// <param name="sortedKey0s">The complete sorted first key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey1s">The complete sorted second key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey2s">The complete sorted third key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey3s">The complete sorted fourth key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="firstKeyDepth">The first encoded key byte depth that can be owned by the router being created at the transformed shelf offset.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <returns>The byte depth and first prefix byte that should route to the right replacement shelf.</returns>
    /// <exception cref="ArgumentException">Thrown when key lane vectors do not have the same length.</exception>
    /// <exception cref="InvalidDataException">Thrown when the key set has no usable prefix boundary in the encoded key.</exception>
    private static (ushort KeyDepth, byte RightPrefixByte) ChooseFixed32Scalar16TransformSplitPlan(
        ReadOnlySpan<ulong> sortedKey0s,
        ReadOnlySpan<ulong> sortedKey1s,
        ReadOnlySpan<ulong> sortedKey2s,
        ReadOnlySpan<ulong> sortedKey3s,
        ushort firstKeyDepth,
        byte hintRightPrefixByte)
    {
        if (sortedKey0s.Length != sortedKey1s.Length || sortedKey0s.Length != sortedKey2s.Length || sortedKey0s.Length != sortedKey3s.Length)
        {
            throw new ArgumentException("FS32-16 key lane vectors must have the same length.", nameof(sortedKey1s));
        }

        if (sortedKey0s.Length < 2)
        {
            throw new InvalidDataException("The FS32-16 transform split boundary requires at least two keys.");
        }

        for (ushort keyDepth = firstKeyDepth; keyDepth < Fixed32Scalar16Layout.KeySize; keyDepth++)
        {
            if (TryChooseFixed32Scalar16TransformSplitRightPrefix(sortedKey0s, sortedKey1s, sortedKey2s, sortedKey3s, keyDepth, hintRightPrefixByte, out byte rightPrefixByte))
            {
                return (keyDepth, rightPrefixByte);
            }
        }

        throw new InvalidDataException("The FS32-16 transform split path requires at least two distinct prefixes in the remaining encoded key bytes.");
    }


    /// <summary>
    /// Tries to choose the right-side prefix boundary for an `FS32-16` transform split at one encoded key depth.<br/>
    /// The chosen boundary is the nearest usable prefix transition around the median of the full shelf plus incoming tuple set.<br/>
    /// Returning false means all tuples share the same prefix at this byte depth and the caller must try a deeper router byte.<br/>
    /// </summary>
    /// <param name="sortedKey0s">The complete sorted first key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey1s">The complete sorted second key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey2s">The complete sorted third key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="sortedKey3s">The complete sorted fourth key lanes for the full shelf plus the incoming tuple.</param>
    /// <param name="keyDepth">The encoded key byte depth being evaluated.</param>
    /// <param name="hintRightPrefixByte">The incoming tuple prefix that older split code used directly as the right-side boundary.</param>
    /// <param name="rightPrefixByte">The selected first right-side prefix byte when a usable boundary exists.</param>
    /// <returns>True when a usable boundary exists at <paramref name="keyDepth"/>; otherwise false.</returns>
    private static bool TryChooseFixed32Scalar16TransformSplitRightPrefix(
        ReadOnlySpan<ulong> sortedKey0s,
        ReadOnlySpan<ulong> sortedKey1s,
        ReadOnlySpan<ulong> sortedKey2s,
        ReadOnlySpan<ulong> sortedKey3s,
        ushort keyDepth,
        byte hintRightPrefixByte,
        out byte rightPrefixByte)
    {
        int desiredRightStart = sortedKey0s.Length / 2;
        for (int i = desiredRightStart; i < sortedKey0s.Length; i++)
        {
            byte leftPrefix = GetFixed32Scalar16Prefix(sortedKey0s[i - 1], sortedKey1s[i - 1], sortedKey2s[i - 1], sortedKey3s[i - 1], keyDepth);
            byte rightPrefix = GetFixed32Scalar16Prefix(sortedKey0s[i], sortedKey1s[i], sortedKey2s[i], sortedKey3s[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        for (int i = desiredRightStart - 1; i > 0; i--)
        {
            byte leftPrefix = GetFixed32Scalar16Prefix(sortedKey0s[i - 1], sortedKey1s[i - 1], sortedKey2s[i - 1], sortedKey3s[i - 1], keyDepth);
            byte rightPrefix = GetFixed32Scalar16Prefix(sortedKey0s[i], sortedKey1s[i], sortedKey2s[i], sortedKey3s[i], keyDepth);
            if (rightPrefix > leftPrefix)
            {
                rightPrefixByte = rightPrefix;
                return true;
            }
        }

        byte firstPrefix = GetFixed32Scalar16Prefix(sortedKey0s[0], sortedKey1s[0], sortedKey2s[0], sortedKey3s[0], keyDepth);
        byte lastPrefix = GetFixed32Scalar16Prefix(sortedKey0s[^1], sortedKey1s[^1], sortedKey2s[^1], sortedKey3s[^1], keyDepth);
        if (hintRightPrefixByte > firstPrefix && hintRightPrefixByte <= lastPrefix)
        {
            rightPrefixByte = hintRightPrefixByte;
            return true;
        }

        rightPrefixByte = 0;
        return false;
    }


    /// <summary>
    /// Routes through a direct-index root router and one direct-index child router, then reads the targeted `FS32-16` shelf bytes into a caller buffer.<br/>
    /// This validation helper supports same-root-prefix fixed-32-byte-key split testing before a general multi-depth routing walker exists.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The first encoded key byte used by the root router.</param>
    /// <param name="childPrefixByte">The second encoded key byte used by the transformed child router.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="destination">The caller buffer that receives the shelf bytes.</param>
    /// <returns>The child router offset and routed shelf offset.</returns>
    /// <exception cref="ArgumentException">Thrown when <paramref name="destination"/> is not exactly the profiled shelf extent size.</exception>
    /// <exception cref="InvalidDataException">Thrown when either route is unset or the shelf bytes are invalid.</exception>
    internal (long ChildRouterOffset, long ShelfOffset) ReadTwoLevelRoutedFixed32Scalar16Shelf(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Fixed32Scalar16Profile profile,
        Span<byte> destination)
    {
        if (destination.Length != profile.ShelfExtentSize)
        {
            throw new ArgumentException("The destination length must match the profiled FS32-16 shelf extent size.", nameof(destination));
        }

        long childRouterOffset = FindRouterTarget(rootRouterOffset, rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The root route to the transformed child router is unset.");
        }

        long shelfOffset = FindRouterTarget(childRouterOffset, childPrefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The child route to the FS32-16 shelf is unset.");
        }

        kernel.Read(shelfOffset, destination);
        Fixed32Scalar16ReadOnly shelf = new(destination, profile);
        if (!shelf.IsValid)
        {
            throw new InvalidDataException("The two-level routed FS32-16 shelf bytes are invalid.");
        }

        return (childRouterOffset, shelfOffset);
    }


    /// <summary>
    /// Inserts one encoded tuple into an `FS32-16` shelf reached through a root router and one direct-index child router without performing split handling.<br/>
    /// This validates the first post-transform fixed-32-byte-key mutation path while deeper routed insert orchestration and generalized split selection are still shape-local.<br/>
    /// If the tuple is already present, the method returns without committing because the physical mutation is a no-op.<br/>
    /// If the shelf is full or a unique-key conflict occurs, the method returns that insert result without committing so the next structural path can be added later.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the direct-index root router starts.</param>
    /// <param name="rootPrefixByte">The first encoded key byte used by the root router.</param>
    /// <param name="childPrefixByte">The second encoded key byte used by the transformed child router.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="key0">The first encoded key lane to insert.</param>
    /// <param name="key1">The second encoded key lane to insert.</param>
    /// <param name="key2">The third encoded key lane to insert.</param>
    /// <param name="key3">The fourth encoded key lane to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <returns>The child router offset, shelf offset, insert result, and commit telemetry when a physical rewrite occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when either route is unset or the shelf bytes are invalid.</exception>
    internal (long ChildRouterOffset, long ShelfOffset, Fixed32Scalar16InsertResult InsertResult, DataKernelCommitTelemetry Commit) InsertTwoLevelRoutedFixed32Scalar16NoSplit(
        long rootRouterOffset,
        byte rootPrefixByte,
        byte childPrefixByte,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys)
    {
        long childRouterOffset = FindRouterTarget(rootRouterOffset, rootPrefixByte);
        if (childRouterOffset == 0)
        {
            throw new InvalidDataException("The root route to the transformed child router is unset.");
        }

        long shelfOffset = FindRouterTarget(childRouterOffset, childPrefixByte);
        if (shelfOffset == 0)
        {
            throw new InvalidDataException("The child route to the FS32-16 shelf is unset.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(shelfOffset, existingShelf);
        Fixed32Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The two-level routed FS32-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Fixed32Scalar16 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar16InsertResult insertResult = shelf.Insert(key0, key1, key2, key3, encodedIdentity, allowDuplicateKeys);
        if (insertResult != Fixed32Scalar16InsertResult.Inserted)
        {
            return (childRouterOffset, shelfOffset, insertResult, default);
        }

        RawDataReservation shelfRewrite = kernel.ReserveAt(shelfOffset, profile.ShelfExtentSize);
        rewrittenShelf.CopyTo(shelfRewrite.Span);
        DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
        return (childRouterOffset, shelfOffset, insertResult, telemetry);
    }


    /// <summary>
    /// Splits a full `FS32-16` shelf reached by the classified route walker by transforming that shelf offset into the next-depth router.<br/>
    /// This is the fixed-32-byte-key counterpart to the validated `SS16-8` walked shelf-transform path and intentionally keeps the mutation shape inside the concrete shelf family.<br/>
    /// The parent router route remains stable; only the walked full shelf offset is rewritten as a router and replacement shelves are appended.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines the shelf extent length.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The transformed child router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `FS32-16` shelf or the transform cannot partition safely.</exception>
    internal (
        long ChildRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedFixed32Scalar16ByShelfTransform(
            long rootRouterOffset,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity,
            int maxRouterHops)
    {
        Fixed32Scalar16RouteTarget target = WalkFixed32Scalar16RouteTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar16Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        return SplitRoutedFixed32Scalar16ByShelfTransform(
            target.Offset,
            existingShelf,
            rightPrefixByte,
            profile,
            key0,
            key1,
            key2,
            key3,
            0,
            encodedIdentity,
            target.AllocationClassId,
            nextRouterKeyDepth);
    }


    /// <summary>
    /// Splits a full `FS32-16` shelf reached by the classified route walker by refining the parent router routes that already point at that shelf.<br/>
    /// This is the normal split counterpart to the transform path: the full shelf offset is rewritten for the left side, one right shelf is appended, and the parent router is rewritten.<br/>
    /// The method returns false when the parent router byte cannot distinguish the full shelf plus incoming tuple, allowing callers to choose a deeper transform instead.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>Whether the parent split occurred, the parent router offset, left/right shelf offsets, left/right item counts, insert result, and commit telemetry.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid full `FS32-16` shelf or the parent router is invalid.</exception>
    internal (
        bool DidSplit,
        long ParentRouterOffset,
        long LeftShelfOffset,
        long RightShelfOffset,
        int LeftItemCount,
        int RightItemCount,
        Fixed32Scalar16InsertResult InsertResult,
        DataKernelCommitTelemetry Commit) SplitWalkedRoutedFixed32Scalar16ByParentRoute(
            long rootRouterOffset,
            Fixed32Scalar16Profile profile,
            ulong key0,
            ulong key1,
            ulong key2,
            ulong key3,
            ulong encodedIdentity,
            int maxRouterHops)
    {
        Fixed32Scalar16RoutePathTarget pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        if (!TrySplitRoutedFixed32Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            0,
            encodedIdentity,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out int leftItemCount,
            out int rightItemCount,
            out Fixed32Scalar16InsertResult insertResult,
            out DataKernelCommitTelemetry telemetry))
        {
            return (false, pathTarget.ParentRouterOffset, target.Offset, 0, 0, 0, insertResult, default);
        }

        return (true, parentRouterOffset, leftShelfOffset, rightShelfOffset, leftItemCount, rightItemCount, insertResult, telemetry);
    }


    /// <summary>
    /// Tries to split a full walked `FS32-16` shelf by refining the parent router routes that currently point at that shelf.<br/>
    /// This is the shape-local fixed-32-byte-key counterpart to the `SS16-8` parent-route split helper.<br/>
    /// </summary>
    /// <param name="parentRouterOffset">The file offset of the parent router that selected the full shelf.</param>
    /// <param name="fullShelfOffset">The file offset of the full shelf being replaced.</param>
    /// <param name="existingShelfBytes">The already-read full shelf bytes.</param>
    /// <param name="parentRouterKeyDepth">The key byte depth owned by the parent router.</param>
    /// <param name="profile">The `FS32-16` shelf profile used for both replacement shelves.</param>
    /// <param name="key0">The first encoded key lane to insert during the split.</param>
    /// <param name="key1">The second encoded key lane to insert during the split.</param>
    /// <param name="key2">The third encoded key lane to insert during the split.</param>
    /// <param name="key3">The fourth encoded key lane to insert during the split.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert during the split.</param>
    /// <param name="resultParentRouterOffset">The parent router offset that was rewritten.</param>
    /// <param name="leftShelfOffset">The left shelf offset after the split.</param>
    /// <param name="rightShelfOffset">The right shelf offset after the split.</param>
    /// <param name="leftItemCount">The left replacement shelf item count.</param>
    /// <param name="rightItemCount">The right replacement shelf item count.</param>
    /// <param name="insertResult">The split insert result.</param>
    /// <param name="telemetry">The commit telemetry when a split occurred.</param>
    /// <returns>True when the full shelf was split by parent-route refinement; otherwise false.</returns>
    private bool TrySplitRoutedFixed32Scalar16ByParentRoute(
        long parentRouterOffset,
        long fullShelfOffset,
        ReadOnlySpan<byte> existingShelfBytes,
        ushort parentRouterKeyDepth,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        out long resultParentRouterOffset,
        out long leftShelfOffset,
        out long rightShelfOffset,
        out int leftItemCount,
        out int rightItemCount,
        out Fixed32Scalar16InsertResult insertResult,
        out DataKernelCommitTelemetry telemetry)
    {
        resultParentRouterOffset = parentRouterOffset;
        leftShelfOffset = 0;
        rightShelfOffset = 0;
        leftItemCount = 0;
        rightItemCount = 0;
        insertResult = default;
        telemetry = default;
        if (!TryCreateFixed32Scalar16SplitShelves(
            existingShelfBytes,
            parentRouterKeyDepth,
            hintRightPrefixByte: GetFixed32Scalar16Prefix(key0, key1, key2, key3, parentRouterKeyDepth),
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            out byte selectedRightPrefixByte,
            out byte[] leftShelfBytes,
            out byte[] rightShelfBytes,
            out leftItemCount,
            out rightItemCount,
            out insertResult))
        {
            return false;
        }

        RawDataReservation leftRewrite = kernel.ReserveAt(fullShelfOffset, profile.ShelfExtentSize);
        leftShelfBytes.CopyTo(leftRewrite.Span);
        RawDataReservation rightAppend = kernel.Reserve(profile.ShelfExtentSize);
        rightShelfBytes.CopyTo(rightAppend.Span);

        byte[] parentRouterBytes = new byte[RouterLayout.Size];
        kernel.Read(parentRouterOffset, parentRouterBytes);
        RouterReader parentReader = new(parentRouterBytes);
        if (!parentReader.IsValid || !parentReader.HasDirectIndex)
        {
            throw new InvalidDataException("The walked FS32-16 parent-route split requires a valid direct-index parent router.");
        }

        RawDataReservation parentRouterRewrite = kernel.ReserveAt(parentRouterOffset, RouterLayout.Size);
        parentRouterBytes.CopyTo(parentRouterRewrite.Span);
        RouterWriter parentWriter = new(parentRouterRewrite.Span);
        for (int prefix = 0; prefix < RouterLayout.MaxOneByteRouteCount; prefix++)
        {
            byte prefixByte = (byte)prefix;
            if (parentReader.GetDirectTarget(prefixByte) == fullShelfOffset)
            {
                long targetOffset = prefixByte < selectedRightPrefixByte
                    ? leftRewrite.Extent.Offset
                    : rightAppend.Extent.Offset;
                parentWriter.WriteRoute(prefix, prefixByte, prefixByte, targetOffset);
            }
        }

        telemetry = CommitAndInvalidateRouterReadCache();
        leftShelfOffset = leftRewrite.Extent.Offset;
        rightShelfOffset = rightAppend.Extent.Offset;
        return true;
    }


    /// <summary>
    /// Inserts one encoded tuple through the classified `FS32-16` route walker when the routed shelf has room for a no-split rewrite.<br/>
    /// The method supports post-transform routing depth without requiring the caller to know whether the root target is a shelf or another router.<br/>
    /// Full-shelf split selection remains deliberately outside this slice; walked transform and parent-route refinement are added as separate validated steps.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent sizing.</param>
    /// <param name="key0">The first encoded key lane to insert.</param>
    /// <param name="key1">The second encoded key lane to insert.</param>
    /// <param name="key2">The third encoded key lane to insert.</param>
    /// <param name="key3">The fourth encoded key lane to insert.</param>
    /// <param name="encodedIdentity">The encoded scalar identity to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `FS32-16` shelf or when a full shelf requires a not-yet-selected walked split path.</exception>
    internal Fixed32Scalar16RoutedInsertResult InsertWalkedRoutedFixed32Scalar16(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentity,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        return InsertWalkedRoutedFixed32Scalar16(
            rootRouterOffset,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh: 0,
            encodedIdentityLow: encodedIdentity,
            allowDuplicateKeys,
            maxRouterHops);
    }

    /// <summary>
    /// Inserts one encoded full-identity tuple through the classified `FS32-16` route walker.<br/>
    /// This overload preserves both persisted identity lanes through no-split inserts and walked split paths.<br/>
    /// </summary>
    /// <param name="rootRouterOffset">The file offset where the root router starts.</param>
    /// <param name="profile">The `FS32-16` shelf profile that determines shelf extent sizing.</param>
    /// <param name="key0">The first encoded key lane to insert.</param>
    /// <param name="key1">The second encoded key lane to insert.</param>
    /// <param name="key2">The third encoded key lane to insert.</param>
    /// <param name="key3">The fourth encoded key lane to insert.</param>
    /// <param name="encodedIdentityHigh">The encoded high identity lane to insert.</param>
    /// <param name="encodedIdentityLow">The encoded low identity lane to insert.</param>
    /// <param name="allowDuplicateKeys">Whether duplicate keys with different identities are allowed.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow before treating the route graph as invalid.</param>
    /// <returns>The storage-facing routed insert result and commit telemetry when a physical mutation occurred.</returns>
    /// <exception cref="InvalidDataException">Thrown when routing does not terminate at a valid `FS32-16` shelf or a split cannot preserve shape invariants.</exception>
    internal Fixed32Scalar16RoutedInsertResult InsertWalkedRoutedFixed32Scalar16(
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        ulong encodedIdentityHigh,
        ulong encodedIdentityLow,
        bool allowDuplicateKeys,
        int maxRouterHops)
    {
        Fixed32Scalar16RoutePathTarget pathTarget = WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops);
        Fixed32Scalar16RouteTarget target = pathTarget.Target;
        if (target.Kind != Fixed32Scalar16RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("The classified route walker did not terminate at an FS32-16 shelf.");
        }

        byte[] existingShelf = new byte[profile.ShelfExtentSize];
        kernel.Read(target.Offset, existingShelf);
        Fixed32Scalar16ReadOnly existingReadOnly = new(existingShelf, profile);
        if (!existingReadOnly.IsValid)
        {
            throw new InvalidDataException("The walked routed FS32-16 shelf bytes are invalid.");
        }

        byte[] rewrittenShelf = new byte[profile.ShelfExtentSize];
        existingShelf.CopyTo(rewrittenShelf.AsSpan());
        Fixed32Scalar16 shelf = new(rewrittenShelf, profile);
        Fixed32Scalar16InsertResult insertResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, encodedIdentityHigh, encodedIdentityLow, allowDuplicateKeys, out Fixed32Scalar16MutationBounds mutationBounds);
        if (insertResult == Fixed32Scalar16InsertResult.Inserted)
        {
            _ = TryConsumeDeletedShelfPayloadOffset(target.Offset, checked((ushort)mutationBounds.ItemOffset));
            RawDataReservation shelfRewrite = kernel.ReserveAt(target.Offset, profile.ShelfExtentSize);
            rewrittenShelf.CopyTo(shelfRewrite.Span);
            DataKernelCommitTelemetry telemetry = CommitAndInvalidateRouterReadCache();
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.WalkedNoSplit,
                insertResult,
                target.Offset,
                target.Offset,
                0,
                telemetry);
        }

        if (insertResult == Fixed32Scalar16InsertResult.AlreadyPresent)
        {
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.NoOp,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult == Fixed32Scalar16InsertResult.KeyConflict)
        {
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.KeyConflict,
                insertResult,
                target.Offset,
                0,
                0,
                default);
        }

        if (insertResult != Fixed32Scalar16InsertResult.Full)
        {
            throw new InvalidDataException($"Unsupported FS32-16 walked insert result {insertResult}.");
        }

        if (TrySplitRoutedFixed32Scalar16ByParentRoute(
            pathTarget.ParentRouterOffset,
            target.Offset,
            existingShelf,
            target.RouterDepth,
            profile,
            key0,
            key1,
            key2,
            key3,
            encodedIdentityHigh,
            encodedIdentityLow,
            out long parentRouterOffset,
            out long leftShelfOffset,
            out long rightShelfOffset,
            out _,
            out _,
            out Fixed32Scalar16InsertResult parentSplitResult,
            out DataKernelCommitTelemetry parentSplitCommit))
        {
            return new Fixed32Scalar16RoutedInsertResult(
                Fixed32Scalar16RoutedInsertKind.WalkedParentRouteSplit,
                parentSplitResult,
                parentRouterOffset,
                leftShelfOffset,
                rightShelfOffset,
                parentSplitCommit);
        }

        ushort nextRouterKeyDepth = checked((ushort)(target.RouterDepth + 1));
        byte rightPrefixByte = GetFixed32Scalar16Prefix(key0, key1, key2, key3, nextRouterKeyDepth);
        (
            long childRouterOffset,
            long transformLeftShelfOffset,
            long transformRightShelfOffset,
            _,
            _,
            Fixed32Scalar16InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = SplitRoutedFixed32Scalar16ByShelfTransform(
                target.Offset,
                existingShelf,
                rightPrefixByte,
                profile,
                key0,
                key1,
                key2,
                key3,
                encodedIdentityHigh,
                encodedIdentityLow,
                target.AllocationClassId,
                nextRouterKeyDepth);

        Fixed32Scalar16RoutedInsertKind kind = transformResult == Fixed32Scalar16InsertResult.Inserted
            ? Fixed32Scalar16RoutedInsertKind.WalkedShelfTransformSplit
            : Fixed32Scalar16RoutedInsertKind.NoOp;
        return new Fixed32Scalar16RoutedInsertResult(
            kind,
            transformResult,
            childRouterOffset,
            transformLeftShelfOffset,
            transformRightShelfOffset,
            transformCommit);
    }


    /// <summary>
    /// Compares two encoded `FS32-16` tuples using the persisted shelf ordering.<br/>
    /// Keys compare by four fixed key parts, then identity, so this helper can merge an incoming split tuple without constructing a temporary shelf.<br/>
    /// </summary>
    /// <param name="left0">The left encoded key part 0.</param>
    /// <param name="left1">The left encoded key part 1.</param>
    /// <param name="left2">The left encoded key part 2.</param>
    /// <param name="left3">The left encoded key part 3.</param>
    /// <param name="leftIdentity">The left encoded identity.</param>
    /// <param name="right0">The right encoded key part 0.</param>
    /// <param name="right1">The right encoded key part 1.</param>
    /// <param name="right2">The right encoded key part 2.</param>
    /// <param name="right3">The right encoded key part 3.</param>
    /// <param name="rightIdentity">The right encoded identity.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when the full tuple matches.</returns>
    private static int CompareFixed32Scalar16Tuple(
        ulong left0,
        ulong left1,
        ulong left2,
        ulong left3,
        ulong leftIdentity,
        ulong right0,
        ulong right1,
        ulong right2,
        ulong right3,
        ulong rightIdentity)
    {
        return CompareFixed32Scalar16Tuple(
            left0,
            left1,
            left2,
            left3,
            0,
            leftIdentity,
            right0,
            right1,
            right2,
            right3,
            0,
            rightIdentity);
    }

    /// <summary>
    /// Compares two encoded `FS32-16` full-identity tuples using the persisted shelf ordering.<br/>
    /// Keys compare by four fixed key parts, then identity high and identity low, matching the physical slot order.<br/>
    /// </summary>
    /// <param name="left0">The left encoded key part 0.</param>
    /// <param name="left1">The left encoded key part 1.</param>
    /// <param name="left2">The left encoded key part 2.</param>
    /// <param name="left3">The left encoded key part 3.</param>
    /// <param name="leftIdentityHigh">The left encoded high identity lane.</param>
    /// <param name="leftIdentityLow">The left encoded low identity lane.</param>
    /// <param name="right0">The right encoded key part 0.</param>
    /// <param name="right1">The right encoded key part 1.</param>
    /// <param name="right2">The right encoded key part 2.</param>
    /// <param name="right3">The right encoded key part 3.</param>
    /// <param name="rightIdentityHigh">The right encoded high identity lane.</param>
    /// <param name="rightIdentityLow">The right encoded low identity lane.</param>
    /// <returns>Negative when left sorts before right, positive when left sorts after right, and zero when the full tuple matches.</returns>
    private static int CompareFixed32Scalar16Tuple(
        ulong left0,
        ulong left1,
        ulong left2,
        ulong left3,
        ulong leftIdentityHigh,
        ulong leftIdentityLow,
        ulong right0,
        ulong right1,
        ulong right2,
        ulong right3,
        ulong rightIdentityHigh,
        ulong rightIdentityLow)
    {
        if (left0 != right0)
        {
            return left0 < right0 ? -1 : 1;
        }

        if (left1 != right1)
        {
            return left1 < right1 ? -1 : 1;
        }

        if (left2 != right2)
        {
            return left2 < right2 ? -1 : 1;
        }

        if (left3 != right3)
        {
            return left3 < right3 ? -1 : 1;
        }

        if (leftIdentityHigh < rightIdentityHigh)
        {
            return -1;
        }

        if (leftIdentityHigh > rightIdentityHigh)
        {
            return 1;
        }

        if (leftIdentityLow < rightIdentityLow)
        {
            return -1;
        }

        if (leftIdentityLow > rightIdentityLow)
        {
            return 1;
        }

        return 0;
    }


    /// <summary>
    /// Extracts one persisted prefix byte from an encoded `FS32-16` key.<br/>
    /// The fixed key is stored in canonical sortable byte order as four 64-bit parts, so depths `0..31` read those parts from left to right.<br/>
    /// </summary>
    /// <param name="key0">The encoded fixed key part 0.</param>
    /// <param name="key1">The encoded fixed key part 1.</param>
    /// <param name="key2">The encoded fixed key part 2.</param>
    /// <param name="key3">The encoded fixed key part 3.</param>
    /// <param name="keyDepth">The zero-based byte depth to extract.</param>
    /// <returns>The persisted key byte at the requested depth.</returns>
    /// <exception cref="ArgumentOutOfRangeException">Thrown when <paramref name="keyDepth"/> is outside the 32-byte fixed key.</exception>
    private static byte GetFixed32Scalar16Prefix(ulong key0, ulong key1, ulong key2, ulong key3, int keyDepth)
    {
        if ((uint)keyDepth >= Fixed32Scalar16Layout.KeySize)
        {
            throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "FS32-16 fixed keys expose exactly thirty-two routing bytes.");
        }

        int partDepth = keyDepth % sizeof(ulong);
        int shift = (sizeof(ulong) - 1 - partDepth) * 8;
        return (keyDepth / sizeof(ulong)) switch
        {
            0 => (byte)(key0 >> shift),
            1 => (byte)(key1 >> shift),
            2 => (byte)(key2 >> shift),
            3 => (byte)(key3 >> shift),
            _ => throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "FS32-16 fixed keys expose exactly thirty-two routing bytes.")
        };
    }

}
